#!/usr/bin/env python3
"""Smart irrigation system for Raspberry Pi.

Controls a solenoid valve via BCM GPIO 17 and reads a capacitive analog
soil moisture sensor via an MCP3008 ADC on SPI bus 0, device 0, CE0.
Exposes a JSON command interface over TCP on port 8080.
"""

import argparse
import json
import logging
import signal
import socket
import sys
import time

import spidev
from gpiozero import OutputDevice

DEFAULT_MOISTURE_THRESHOLD = 30
DEFAULT_WEB_PORT = 8080
DEFAULT_LOG_FILE = "irrigation.log"
DEFAULT_VALVE_PIN = 17
DEFAULT_SPI_BUS = 0
DEFAULT_SPI_DEVICE = 0
DEFAULT_SPI_CHANNEL = 0


class IrrigationSystem:
    def __init__(self, moisture_threshold, web_port, log_file, valve_pin,
                 spi_bus, spi_device, spi_channel):
        self.moisture_threshold = moisture_threshold
        self.web_port = web_port
        self.log_file = log_file
        self.valve_pin = valve_pin
        self.spi_bus = spi_bus
        self.spi_device = spi_device
        self.spi_channel = spi_channel
        self.valve_state = False
        self.last_moisture = None
        self.last_decision = None
        self.running = True

        self.setup_logging()
        self.setup_gpio()
        self.setup_spi()
        self.setup_signal_handlers()

    def setup_logging(self):
        logging.basicConfig(
            filename=self.log_file,
            level=logging.INFO,
            format="%(asctime)s - %(levelname)s - %(message)s",
        )
        logging.info("Logging initialized.")

    def setup_gpio(self):
        try:
            self.valve = OutputDevice(self.valve_pin, active_high=True,
                                      initial_value=False)
            logging.info(f"GPIO pin {self.valve_pin} configured as output.")
        except Exception as e:
            logging.error(f"Failed to initialize GPIO pin {self.valve_pin}: {e}")
            raise

    def setup_spi(self):
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(self.spi_bus, self.spi_device)
            self.spi.max_speed_hz = 1000000
            self.spi.mode = 0
            logging.info(
                f"SPI opened: bus={self.spi_bus}, device={self.spi_device}, "
                f"channel={self.spi_channel}."
            )
        except Exception as e:
            logging.error(f"Failed to initialize SPI: {e}")
            raise

    def setup_signal_handlers(self):
        signal.signal(signal.SIGINT, self.signal_handler)
        signal.signal(signal.SIGTERM, self.signal_handler)

    def signal_handler(self, signum, frame):
        logging.info(f"Signal {signum} received. Shutting down.")
        self.running = False

    def read_moisture(self):
        try:
            adc_value = self.read_mcp3008(self.spi_channel)
            if adc_value is None:
                logging.warning("Sensor read returned None.")
                return None
            if adc_value == 0:
                logging.warning("Sensor read returned 0 (all zeros).")
                return 0
            if adc_value == 1023:
                logging.warning("Sensor read returned 1023 (all ones).")
                return 100
            moisture = 100 - (adc_value / 1023.0) * 100
            moisture = max(0, min(100, moisture))
            logging.debug(f"Raw ADC: {adc_value}, Moisture: {moisture:.2f}%")
            return moisture
        except Exception as e:
            logging.error(f"Error reading moisture sensor: {e}")
            return None

    def read_mcp3008(self, channel):
        if not 0 <= channel <= 7:
            logging.error(f"Invalid MCP3008 channel: {channel}")
            return None
        try:
            cmd = 0b11 << 6
            cmd |= (channel & 0x07) << 3
            cmd |= 0x00
            cmd <<= 4
            resp = self.spi.xfer2([cmd, 0x00, 0x00])
            adc_value = ((resp[1] & 0x03) << 8) | resp[2]
            return adc_value
        except Exception as e:
            logging.error(f"SPI communication error: {e}")
            return None

    def control_valve(self, state):
        try:
            if state:
                self.valve.on()
                self.valve_state = True
                logging.info("Valve opened.")
            else:
                self.valve.off()
                self.valve_state = False
                logging.info("Valve closed.")
        except Exception as e:
            logging.error(f"Error controlling valve: {e}")

    def decide_valve(self, moisture):
        if moisture is None:
            logging.warning("No moisture reading. Maintaining current valve state.")
            return self.valve_state
        if self.last_decision is None:
            decision = moisture < self.moisture_threshold
        else:
            decision = not self.last_decision
        if decision:
            self.control_valve(True)
        else:
            self.control_valve(False)
        self.last_decision = decision
        return decision

    def handle_command(self, command):
        try:
            data = json.loads(command)
            action = data.get("action")
            if action == "get_status":
                moisture = self.read_moisture()
                status = {
                    "moisture": moisture,
                    "valve_state": self.valve_state,
                    "threshold": self.moisture_threshold,
                }
                return json.dumps(status)
            elif action == "toggle_valve":
                self.valve_state = not self.valve_state
                self.control_valve(self.valve_state)
                return json.dumps({"valve_state": self.valve_state})
            else:
                logging.warning(f"Unknown action: {action}")
                return json.dumps({"error": "Invalid action"})
        except json.JSONDecodeError:
            logging.warning("Invalid JSON received.")
            return json.dumps({"error": "Invalid JSON"})
        except Exception as e:
            logging.error(f"Error handling command: {e}")
            return json.dumps({"error": "Internal server error"})

    def run(self):
        logging.info("Starting irrigation system.")
        while self.running:
            moisture = self.read_moisture()
            if moisture is not None:
                self.last_moisture = moisture
                self.decide_valve(moisture)
            time.sleep(5)
        self.cleanup()

    def cleanup(self):
        logging.info("Cleaning up resources.")
        try:
            self.valve.off()
            self.valve.close()
        except Exception:
            pass
        try:
            self.spi.close()
        except Exception:
            pass
        logging.info("Cleanup complete.")


def main():
    parser = argparse.ArgumentParser(
        description="Smart irrigation system for Raspberry Pi."
    )
    parser.add_argument(
        "--moisture_threshold", type=int, default=DEFAULT_MOISTURE_THRESHOLD,
        help="Moisture threshold in percentage (default: 30)"
    )
    parser.add_argument(
        "--web_port", type=int, default=DEFAULT_WEB_PORT,
        help="Port number for the web interface (default: 8080)"
    )
