        "--log_file", type=str, default=DEFAULT_LOG_FILE,
        help="Path to the log file (default: irrigation.log)"
    )
    parser.add_argument(
        "--valve_pin", type=int, default=DEFAULT_VALVE_PIN,
        help="BCM GPIO pin for the solenoid valve (default: 17)"
    )
    parser.add_argument(
        "--spi_bus", type=int, default=DEFAULT_SPI_BUS,
        help="SPI bus number (default: 0)"
    )
    parser.add_argument(
        "--spi_device", type=int, default=DEFAULT_SPI_DEVICE,
        help="SPI device number (default: 0)"
    )
    parser.add_argument(
        "--spi_channel", type=int, default=DEFAULT_SPI_CHANNEL,
        help="MCP3008 channel (default: 0)"
    )
    args = parser.parse_args()

    try:
        system = IrrigationSystem(
            args.moisture_threshold, args.web_port, args.log_file,
            args.valve_pin, args.spi_bus, args.spi_device, args.spi_channel
        )
        system.run()
    except Exception as e:
        logging.error(f"Fatal error: {e}")
        sys.exit(1)


if __name__ == "__main__":
    main()

