#!/usr/bin/env python3
"""
Raspberry Pi Smart Greenhouse Controller

Monitors DHT22 temperature/humidity sensor on BCM 4, reads analog values
from MCP3008 on SPI channel 0, controls pump, fan, and light relays on
BCM 17, 27, 22 respectively, and drives a status LED on BCM 25.

Uses modern libraries: gpiozero, spidev, adafruit-circuitpython-dht,
adafruit-circuitpython-mcp3008.
"""

import os
import sys
import time
import signal
import logging
import threading

import spidev
import gpiozero
import adafruit_dht
import adafruit_mcp3008

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
DHT_PIN = 4
PUMP_PIN = 17
FAN_PIN = 27
LIGHT_PIN = 22
LED_PIN = 25

SPI_BUS = 0
SPI_DEVICE = 0
SPI_MAX_SPEED_HZ = 1_000_000
ADC_CHANNEL = 0

SENSOR_READ_INTERVAL = 300
WATCHDOG_TIMEOUT = 600

LOG_FILE = "greenhouse.log"

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
spi = None
dht_device = None
mcp = None
pump = None
fan = None
light = None
led = None

last_activity = time.time()
watchdog_timer = None
running = True

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------
logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
log = logging.getLogger(__name__)


def log_error(message: str) -> None:
    log.error(message)
    print(f"ERROR: {message}", file=sys.stderr)


def log_info(message: str) -> None:
    log.info(message)
    print(f"INFO: {message}")


# ---------------------------------------------------------------------------
# Hardware initialization
# ---------------------------------------------------------------------------
def init_hardware() -> bool:
    global spi, dht_device, mcp, pump, fan, light, led

    # DHT22
    try:
        dht_device = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as exc:
        log_error(f"Failed to initialise DHT22 on BCM {DHT_PIN}: {exc}")
        dht_device = None

    # MCP3008
    try:
        spi = spidev.SpiDev()
        spi.open(SPI_BUS, SPI_DEVICE)
        spi.max_speed_hz = SPI_MAX_SPEED_HZ
        spi.mode = 0
        mcp = adafruit_mcp3008.MCP3008(spi, ADC_CHANNEL)
    except Exception as exc:
        log_error(f"Failed to initialise MCP3008 on SPI bus {SPI_BUS} device {SPI_DEVICE}: {exc}")
        if spi is not None:
            try:
                spi.close()
            except Exception:
                pass
            spi = None
        mcp = None

    # Relays
    try:
        pump = gpiozero.OutputDevice(PUMP_PIN, active_high=True, initial_value=False)
        fan = gpiozero.OutputDevice(FAN_PIN, active_high=True, initial_value=False)
        light = gpiozero.OutputDevice(LIGHT_PIN, active_high=True, initial_value=False)
    except Exception as exc:
        log_error(f"Failed to initialise relay GPIOs: {exc}")
        pump = fan = light = None

    # LED
    try:
        led = gpiozero.LED(LED_PIN)
        led.off()
    except Exception as exc:
        log_error(f"Failed to initialise LED on BCM {LED_PIN}: {exc}")
        led = None

    return all(
        dht_device is not None,
        mcp is not None,
        pump is not None,
        fan is not None,
        light is not None,
        led is not None,
    )


# ---------------------------------------------------------------------------
# Sensor reading
# ---------------------------------------------------------------------------
def read_dht22() -> tuple[float | None, float | None]:
    if dht_device is None:
        return None, None
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            log_error("DHT22 returned None values")
            return None, None
        return temperature, humidity
    except RuntimeError as exc:
        log_error(f"DHT22 read error (transient): {exc}")
        return None, None
    except Exception as exc:
        log_error(f"DHT22 unexpected error: {exc}")
        return None, None


def read_adc(channel: int) -> int | None:
    if mcp is None:
        return None
    try:
        return mcp.value
    except Exception as exc:
        log_error(f"MCP3008 read error on channel {channel}: {exc}")
        return None


# ---------------------------------------------------------------------------
# Actuator control
# ---------------------------------------------------------------------------
def control_pump(command: str) -> bool:
    if pump is None:
        log_error("Pump relay not initialised")
        return False
    try:
        if command == "on":
            pump.on()
        elif command == "off":
            pump.off()
        else:
            log_error(f"Invalid pump command: {command}")
            return False
        log_info(f"Pump {'activated' if command == 'on' else 'deactivated'}")
        return True
    except Exception as exc:
        log_error(f"Pump control error: {exc}")
        return False


def control_fan(command: str) -> bool:
    if fan is None:
        log_error("Fan relay not initialised")
        return False
    try:
        if command == "on":
            fan.on()
        elif command == "off":
            fan.off()
        else:
            log_error(f"Invalid fan command: {command}")
            return False
        log_info(f"Fan {'activated' if command == 'on' else 'deactivated'}")
        return True
    except Exception as exc:
        log_error(f"Fan control error: {exc}")
        return False


def control_light(command: str) -> bool:
    if light is None:
        log_error("Light relay not initialised")
        return False
    try:
        if command == "on":
            light.on()
        elif command == "off":
            light.off()
        else:
            log_error(f"Invalid light command: {command}")
            return False
        log_info(f"Light {'activated' if command == 'on' else 'deactivated'}")
        return True
    except Exception as exc:
        log_error(f"Light control error: {exc}")
        return False


# ---------------------------------------------------------------------------
# LED status
# ---------------------------------------------------------------------------
def set_led_status(status: str) -> None:
    if led is None:
        return
    try:
        if status == "online":
            led.on()
        elif status == "offline":
            led.off()
        elif status == "error":
            led.blink(on_time=0.2, off_time=0.2, n=5, background=True)
        elif status == "synchronizing":
            led.blink(on_time=0.2, off_time=0.2, n=5, background=True)
        else:
            log_error(f"Invalid LED status: {status}")
    except Exception as exc:
        log_error(f"LED control error: {exc}")


# ---------------------------------------------------------------------------
# Watchdog
# ---------------------------------------------------------------------------
def reset_watchdog() -> None:
    global last_activity
    last_activity = time.time()


def watchdog_check() -> None:
    global watchdog_timer
    if time.time() - last_activity > WATCHDOG_TIMEOUT:
        log_error("Watchdog timeout! Restarting...")
        try:
            os.execv(sys.executable, [sys.executable] + sys.argv)
        except Exception as exc:
            log_error(f"execv failed: {exc}")
            sys.exit(1)
    if watchdog_timer is not None:
        watchdog_timer.cancel()
    watchdog_timer = threading.Timer(WATCHDOG_TIMEOUT / 2, watchdog_check)
    watchdog_timer.daemon = True
    watchdog_timer.start()


# ---------------------------------------------------------------------------
# Cleanup
# ---------------------------------------------------------------------------
def cleanup() -> None:
    global running
    running = False
    log_info("Cleaning up resources...")
    if watchdog_timer is not None:
        watchdog_timer.cancel()
    for dev, name in (
        (pump, "pump"),
        (fan, "fan"),
        (light, "light"),
        (led, "led"),
    ):
        if dev is not None:
            try:
                dev.close()
            except Exception:
                pass
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass
    if spi is not None:
        try:
            spi.close()
        except Exception:
            pass
    log_info("Cleanup complete.")


# ---------------------------------------------------------------------------
# Signal handlers
# ---------------------------------------------------------------------------
def signal_handler(signum, frame) -> None:
    log_info(f"Received signal {signum}, shutting down...")
    cleanup()
    sys.exit(0)


# ---------------------------------------------------------------------------
# Main loop
# ---------------------------------------------------------------------------
def main() -> None:
    global last_activity

    signal.signal(signal.SIGTERM, signal_handler)
    signal.signal(signal.SIGINT, signal_handler)

    if not init_hardware():
        log_error("Hardware initialisation failed. Exiting.")
        sys.exit(1)

    set_led_status("online")
    reset_watchdog()
    watchdog_check()

    log_info("Greenhouse controller started.")

    try:
        while running:
            reset_watchdog()

            # --- Sensor read ---
            temperature, humidity = read_dht22()
            if temperature is not None and humidity is not None:
                log_info(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
            else:
                log_error("Failed to read DHT22 sensor data.")

            soil_moisture = read_adc(ADC_CHANNEL)
            if soil_moisture is not None:
                log_info(f"Soil Moisture: {soil_moisture}")
            else:
                log_error("Failed to read soil moisture from MCP3008.")

            # --- Actuator control ---
            # Example: pump on if humidity > 70%, fan on if humidity < 30%
            if humidity is not None:
                if humidity > 70:
                    if not control_pump("on"):
                        log_error("Failed to activate pump.")
                elif humidity < 30:
                    if not control_fan("on"):
                        log_error("Failed to activate fan.")
                else:
                    if not control_pump("off"):
                        log_error("Failed to deactivate pump.")
                    if not control_fan("off"):
                        log_error("Failed to deactivate fan.")

            time.sleep(SENSOR_READ_INTERVAL)

    except Exception as exc:
        log_error(f"Unexpected error in main loop: {exc}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

