import time
import logging
import threading
import argparse
import queue
import RPi.GPIO as GPIO
import spidev


class SoundSensor:
    """
    Represents a sound sensor and handles reading, debouncing, and event detection.
    """

    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.last_reading = 0
        self.spi = None
        self.running = False
        self.lock = threading.Lock()

        if self.sensor_type == "digital":
            GPIO.setmode(GPIO.BCM)
            for pin in self.gpio_pins:
                GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        elif self.sensor_type == "analog":
            try:
                self.spi = spidev.SpiDev()
                self.spi.open(0, 0)
                self.spi.max_speed_hz = self.spi_speed
                self.spi.mode = 0
            except Exception as e:
                logging.error(f"Sensor {self.sensor_id}: Failed to initialize SPI: {e}")
                self.spi = None
        else:
            logging.error(f"Sensor {self.sensor_id}: Invalid sensor type: {self.sensor_type}")
            raise ValueError(f"Invalid sensor type: {self.sensor_type}")

    def read_digital(self):
        """Reads a digital sound sensor value from the configured GPIO pins."""
        try:
            for pin in self.gpio_pins:
                value = GPIO.input(pin)
                if value == 1:
                    return 1
            return 0
        except Exception as e:
            logging.error(f"Sensor {self.sensor_id}: Error reading digital sensor: {e}")
            return None

    def read_analog(self):
        """Reads an analog sound sensor value from the MCP3008 ADC."""
        if self.spi is None:
            logging.error(f"Sensor {self.sensor_id}: SPI not initialized.")
            return None
        try:
            channel = self.channels[0]
            if not 0 <= channel <= 7:
                logging.error(f"Sensor {self.sensor_id}: Invalid channel {channel}.")
                return None
            # MCP3008 single-ended read: start bit, single-ended mode, channel bits, dummy byte
            adc = self.spi.xfer2([1, (8 + channel) << 4, 0])
            data = ((adc[1] & 3) << 8) + adc[2]
            return data
        except Exception as e:
            logging.error(f"Sensor {self.sensor_id}: Error reading analog sensor: {e}")
            return None

    def read(self):
        """Reads the sound sensor value and debounces it."""
        with self.lock:
            if self.sensor_type == "digital":
                value = self.read_digital()
            elif self.sensor_type == "analog":
                value = self.read_analog()
            else:
                logging.error(f"Sensor {self.sensor_id}: Invalid sensor type: {self.sensor_type}")
                return None

            if value is None:
                return None

            if value != self.last_reading:
                self.last_reading = value
                time.sleep(0.1)
                return value
            return None

    def detect_event(self, value):
        """Detects an event based on the sensor reading and threshold."""
        if value is None:
            return False
        if self.sensor_type == "digital":
            return value == 1
        elif self.sensor_type == "analog":
            return value >= self.threshold
        return False

    def log_event(self, value):
        """Logs the detected event to the log queue."""
        if self.log_queue is not None:
            try:
                self.log_queue.put(f"Sensor {self.sensor_id} triggered: {value}")
            except Exception as e:
                logging.error(f"Sensor {self.sensor_id}: Error putting log message: {e}")

    def run(self):
        """Main loop for reading and detecting events."""
        self.running = True
        try:
            while self.running:
                value = self.read()
                if value is not None and self.detect_event(value):
                    self.log_event(value)
                time.sleep(1 / self.sample_rate)
        except Exception as e:
            logging.error(f"Sensor {self.sensor_id}: Error in main loop: {e}")
        finally:
            self.stop()

    def stop(self):
        """Stops the sensor reading loop and cleans up resources."""
        self.running = False
        if self.spi is not None:
            try:
                self.spi.close()
            except Exception as e:
                logging.error(f"Sensor {self.sensor_id}: Error closing SPI: {e}")
            self.spi = None
        if self.sensor_type == "digital":
            try:
                GPIO.cleanup(self.gpio_pins)
            except Exception as e:
                logging.error(f"Sensor {self.sensor_id}: Error cleaning up GPIO: {e}")


def main():
    parser = argparse.ArgumentParser(description="Sound Sensor Monitoring System")
    parser.add_argument("--sensor_type", required=True, choices=["digital", "analog"])
    parser.add_argument("--threshold", type=int, required=True)
    parser.add_argument("--sample_rate", type=int, required=True)
    parser.add_argument("--log_file", required=True)
    parser.add_argument("--gpio_pins", nargs="+", type=int, required=False)
    parser.add_argument("--channels", nargs="+", type=int, required=False)
    parser.add_argument("--spi_speed", type=int, default=1000000)
    parser.add_argument("--sensor_ids", nargs="+", type=str, required=True)

    args = parser.parse_args()

    logging.basicConfig(filename=args.log_file, level=logging.INFO,
                        format='%(asctime)s - %(levelname)s - %(message)s')

    log_queue = queue.Queue()
    sensors = []

    try:
        for i, sensor_id in enumerate(args.sensor_ids):
            gpio_pins = args.gpio_pins[i] if i < len(args.gpio_pins) else []
            channels = args.channels[i] if i < len(args.channels) else []

            sensor = SoundSensor(sensor_id, args.sensor_type, args.threshold, args.sample_rate,
                                 gpio_pins, channels, args.spi_speed, log_queue)
            sensors.append(sensor)

            thread = threading.Thread(target=sensor.run, daemon=True)
            thread.start()

        while True:
            try:
                message = log_queue.get(timeout=1)
                logging.info(message)
            except queue.Empty:
                pass

    except KeyboardInterrupt:
        logging.info("Exiting program.")
    finally:
        for sensor in sensors:
            sensor.stop()
        GPIO.cleanup()


if __name__ == "__main__":
    main()

