import RPi.GPIO as GPIO
import time
import sys

GAS_SENSOR_PIN = 16
WARNING_LED_PIN = 12
SAMPLE_INTERVAL = 0.5
LOW_THRESHOLD = 3
FLASH_ON_TIME = 0.2
FLASH_OFF_TIME = 0.2

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(GAS_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    GPIO.setup(WARNING_LED_PIN, GPIO.OUT, initial=GPIO.LOW)

def cleanup_gpio():
    GPIO.cleanup()

def flash_led(pin, on_time, off_time, repeat=3):
    for _ in range(repeat):
        GPIO.output(pin, GPIO.HIGH)
        time.sleep(on_time)
        GPIO.output(pin, GPIO.LOW)
        time.sleep(off_time)

def main():
    setup_gpio()
    low_count = 0
    try:
        while True:
            try:
                gas_level = GPIO.input(GAS_SENSOR_PIN)
            except Exception as e:
                print(f"Error reading gas sensor on pin {GAS_SENSOR_PIN}: {e}")
                time.sleep(SAMPLE_INTERVAL)
                continue

            if gas_level == GPIO.LOW:
                low_count += 1
                if low_count >= LOW_THRESHOLD:
                    print("Gas leak detected!")
                    flash_led(WARNING_LED_PIN, FLASH_ON_TIME, FLASH_OFF_TIME)
                    low_count = 0
            else:
                if low_count >= LOW_THRESHOLD:
                    print("Gas leak cleared!")
                low_count = 0

            time.sleep(SAMPLE_INTERVAL)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

