#!/usr/bin/env python3
"""
Industrial Air Quality Monitoring System for Raspberry Pi 5.

Reads MQ-2, MQ-7, and MQ-135 gas sensors via an MCP3008 ADC on SPI bus 0, CE0.
Logs measurements to ~/logs/industrial_air_quality.log and controls an
actuator whose BCM GPIO pin is specified in config.json.
"""

import json
import os
import signal
import sys
import time

