import signal
import sys
import os

import cv2
import numpy as np

try:
    from picamera2 import Picamera2
except ImportError:
    print("picamera2 is not installed. Install with: pip install picamera2")
    sys.exit(1)

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("gpiozero is not installed. Install with: pip install gpiozero")
    sys.exit(1)

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
CONFIG_FILE = "config.json"

DEFAULT_CONFIG = {
    "resolution": (224, 224),
    "gpio_led": 17,
    "gpio_door_control": 18,
    "bird_threshold": 0.5,
    "bird_detection_interval": 0.1,
    "bird_detection_duration": 1.0,
}

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_camera = None
_led = None
_door = None
_running = True


def load_config(path=CONFIG_FILE):
    """Load configuration from JSON, merging with defaults."""
    cfg = dict(DEFAULT_CONFIG)
    try:
        with open(path, "r") as f:
            user_cfg = json.load(f)
        cfg.update(user_cfg)
    except FileNotFoundError:
        print(f"Config file '{path}' not found; using defaults.")
    except json.JSONDecodeError as exc:
        print(f"Config file '{path}' is invalid JSON: {exc}; using defaults.")
    return cfg


def indicate_bird(led_pin):
    """Drive the LED HIGH for one second, then LOW."""
    if led_pin is None:
        return
    try:
        led = OutputDevice(led_pin)
        led.on()
        time.sleep(1.0)
        led.off()
    except GPIOZeroError as exc:
        print(f"GPIO error on pin {led_pin}: {exc}")
    finally:
        if led is not None:
            led.close()


def signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for clean shutdown."""
    global _running
    _running = False


def cleanup():
    """Release all hardware resources."""
    global _camera, _led, _door
    if _camera is not None:
        try:
            _camera.stop()
        except Exception:
            pass
        _camera = None
    if _led is not None:
        try:
            _led.close()
        except Exception:
            pass
        _led = None
    if _door is not None:
        try:
            _door.close()
        except Exception:
            pass
        _door = None


def main():
    global _camera, _led, _door, _running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config()

    # -----------------------------------------------------------------------
    # GPIO setup
    # -----------------------------------------------------------------------
    led_pin = config.get("gpio_led")
    door_pin = config.get("gpio_door_control")

    if led_pin is not None:
        try:
            _led = OutputDevice(led_pin)
        except GPIOZeroError as exc:
            print(f"Failed to init LED on GPIO{led_pin}: {exc}")
            _led = None

    if door_pin is not None:
        try:
            _door = OutputDevice(door_pin)
        except GPIOZeroError as exc:
            print(f"Failed to init door control on GPIO{door_pin}: {exc}")
            _door = None

    # -----------------------------------------------------------------------
    # Camera setup
    # -----------------------------------------------------------------------
    try:
        _camera = Picamera2()
        _camera.configure(
            _camera.create_preview_configuration(
                main={"size": config["resolution"], "format": "RGB888"}
            )
        )
        _camera.start()
    except Exception as exc:
        print(f"Failed to initialize camera: {exc}")
        cleanup()
        sys.exit(1)

    # -----------------------------------------------------------------------
    # Main loop
    # -----------------------------------------------------------------------
    try:
        while _running:
            try:
                frame = _camera.capture_array()
            except Exception as exc:
                print(f"Frame capture error: {exc}")
                time.sleep(0.1)
                continue

            if frame is None or frame.size == 0:
                print("Empty frame received.")
                time.sleep(0.1)
                continue

            # Placeholder for bird-detection inference (replace with actual model).
            # In a real scenario, this would run a TFLite model on the frame.
            bird_detected = False

            if bird_detected:
                indicate_bird(led_pin)

                if door_pin is not None:
                    try:
                        _door.on()
                        time.sleep(config["bird_detection_duration"])
                        _door.off()
                    except GPIOZeroError as exc:
                        print(f"Door control error: {exc}")

            time.sleep(config["bird_detection_interval"])

    except Exception as exc:
        print(f"Unexpected error in main loop: {exc}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

