import argparse
import datetime
import io
import json
import logging
import os
import queue
import signal
import sys
import threading
import time

import cv2
import numpy as np

try:
    from picamera2 import Picamera2
except ImportError:
    logging.error("picamera2 library is not installed. Please install via 'pip install picamera2'.")
    sys.exit(1)

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError
except ImportError:
    logging.error("gpiozero library is not installed. Please install via 'pip install gpiozero'.")
    sys.exit(1)


class MotionDetectionCamera:
    """
    A class to encapsulate camera and motion detection functionalities.
    """

    def __init__(self, config_path):
        self.config_path = config_path
        self.config = self.load_config()
        self.logger = self.setup_logging()
        self.camera = None
        self.led = None
        self.frame_queue = queue.Queue(maxsize=self.config["max_queue_size"])
        self.motion_detected = False
        self.led_timer = None
        self.running = True
        self.lock = threading.Lock()

    def load_config(self):
        try:
            with open(self.config_path, "r") as f:
                return json.load(f)
        except FileNotFoundError:
            logging.error(f"Configuration file not found: {self.config_path}")
            sys.exit(1)
        except json.JSONDecodeError:
            logging.error(f"Invalid JSON format in configuration file: {self.config_path}")
            sys.exit(1)

    def setup_logging(self):
        logger = logging.getLogger(__name__)
        logger.setLevel(logging.INFO)
        handler = logging.StreamHandler(sys.stdout)
        formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        logger.addHandler(handler)
        return logger

    def initialize_camera(self):
        try:
            self.camera = Picamera2()
            camera_config = self.camera.create_preview_configuration(
                main={"size": (self.config["resolution_width"], self.config["resolution_height"])}
            )
            self.camera.configure(camera_config)
            self.camera.start()
            time.sleep(self.config["warmup_time"])
            self.logger.info("Camera initialized successfully.")
        except Exception as e:
            self.logger.error(f"Error initializing camera: {e}")
            self.cleanup()
            sys.exit(1)

    def initialize_led(self):
        try:
            gpio_pin = self.config.get("gpio_pin", None)
            if gpio_pin is not None:
                self.led = LED(gpio_pin)
                self.logger.info(f"LED initialized on GPIO pin {gpio_pin}.")
            else:
                self.logger.info("LED not configured. Skipping initialization.")
        except GPIOZeroError as e:
            self.logger.error(f"Error initializing LED: {e}")
            self.cleanup()
            sys.exit(1)

    def capture_frame(self):
        try:
            frame = self.camera.capture_array()
            return frame
        except Exception as e:
            self.logger.error(f"Error capturing frame: {e}")
            return None

    def detect_motion(self, frame1, frame2):
        try:
            diff = cv2.absdiff(frame1, frame2)
            gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
            blur = cv2.GaussianBlur(gray, (5, 5), 0)
            _, thresh = cv2.threshold(blur, self.config["motion_threshold"], 255, cv2.THRESH_BINARY)
            dilated = cv2.dilate(thresh, None, iterations=3)
            contours, _ = cv2.findContours(dilated, cv2.RETR_TREE, cv2.CHAIN_APPROX_SIMPLE)
            for contour in contours:
                if cv2.contourArea(contour) > self.config["min_motion_area"]:
                    return True
            return False
        except Exception as e:
            self.logger.error(f"Error detecting motion: {e}")
            return False

    def trigger_alert(self):
        try:
            if self.led:
                self.led.on()
                self.logger.info("Motion detected! LED activated.")
                self.led_timer = threading.Timer(self.config["led_activation_duration"], self.deactivate_led)
                self.led_timer.start()
        except Exception as e:
            self.logger.error(f"Error triggering alert: {e}")

    def deactivate_led(self):
        try:
            if self.led:
                self.led.off()
                self.logger.info("LED deactivated.")
        except Exception as e:
            self.logger.error(f"Error deactivating LED: {e}")

    def capture_and_process(self):
        try:
            frame1 = self.capture_frame()
            if frame1 is None:
                return

            time.sleep(0.1)

            frame2 = self.capture_frame()
            if frame2 is None:
                return

            if self.detect_motion(frame1, frame2):
                with self.lock:
                    if not self.motion_detected:
                        self.motion_detected = True
                        self.trigger_alert()
            else:
                with self.lock:
                    self.motion_detected = False

        except Exception as e:
            self.logger.error(f"Error in capture_and_process: {e}")

    def run(self):
        self.initialize_camera()
        self.initialize_led()

        try:
            while self.running:
                self.capture_and_process()
        except KeyboardInterrupt:
            self.logger.info("Program interrupted by user.")
        finally:
            self.cleanup()

    def cleanup(self):
        self.logger.info("Cleaning up resources...")
        if self.led_timer:
            self.led_timer.cancel()
        if self.led:
            self.led.close()
        if self.camera:
            self.camera.stop()
            self.camera.close()
        cv2.destroyAllWindows()
        self.logger.info("Cleanup complete.")


def signal_handler(sig, frame, camera):
    camera.running = False


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Motion detection camera with LED alert.")
    parser.add_argument("--config", default="config.json", help="Path to the configuration file.")
    args = parser.parse_args()

    camera = MotionDetectionCamera(args.config)
    signal.signal(signal.SIGINT, lambda s, f: signal_handler(s, f, camera))
    camera.run()

