                )
                self.picam2.configure(config)
                self.picam2.start()
                self.logger.info(
                    "Picamera2 started at %s @ %d fps", self.resolution, self.framerate
                )
            except Exception as e:
                self.logger.error("Failed to initialize Picamera2: %s", e)
                self.picam2 = None
        else:
