            return None
        try:
            return self.picam2.capture_array()
        except Exception as e:
            self.logger.error("Camera read error: %s", e)
            return None


class GestureRecognizer:
    def __init__(self, model_path="gesture_model_quantized.tflite"):
        self.model_path = model_path
        self.interpreter = None
        self.input_details = None
        self.output_details = None
        self.labels = [
            "Open Hand",
            "Closed Fist",
            "Pointing Up",
            "Pointing Down",
            "Peace Sign",
        ]
        self.logger = logging.getLogger(__name__)

    def load_model(self):
        if not os.path.isfile(self.model_path):
            self.logger.error("Model file not found: %s", self.model_path)
            return False
        try:
            self.interpreter = tflite.Interpreter(model_path=self.model_path)
            self.interpreter.allocate_tensors()
            self.input_details = self.interpreter.get_input_details()
            self.output_details = self.interpreter.get_output_details()
            self.logger.info("Model loaded successfully from %s", self.model_path)
            return True
        except Exception as e:
            self.logger.error("Failed to load model: %s", e)
            self.interpreter = None
            return False

    def preprocess(self, frame):
        try:
            resized = cv2.resize(frame, (224, 224))
            return resized.astype(np.float32) / 255.0
        except Exception as e:
            self.logger.error("Preprocessing error: %s", e)
            return None

    def recognize(self, frame):
        if self.interpreter is None:
            return None, 0.0
        try:
            input_data = self.preprocess(frame)
            if input_data is None:
                return None, 0.0
            self.interpreter.set_tensor(self.input_details[0]["index"], [input_data])
            self.interpreter.invoke()
            output_data = self.interpreter.get_tensor(self.output_details[0]["index"])
            predicted_index = int(np.argmax(output_data[0]))
            confidence = float(output_data[0][predicted_index])
            return self.labels[predicted_index], confidence
        except Exception as e:
            self.logger.error("Inference error: %s", e)
            return None, 0.0


class SmartHomeController:
    def __init__(self, user_id="default_user"):
        self.user_id = user_id
        self.light_on = False
        self.thermostat_temp = 20
        self.tv_on = False
        self.logger = logging.getLogger(__name__)
        if LED is not None:
            try:
                self.light_relay = LED(23)
                self.tv_relay = LED(24)
                self.logger.info("GPIO initialized for light and TV relays")
            except Exception as e:
                self.logger.warning("GPIO init failed: %s; running without relays", e)
                self.light_relay = None
                self.tv_relay = None
        else:
            self.light_relay = None
            self.tv_relay = None

    def toggle_light(self):
        self.light_on = not self.light_on
        if self.light_relay is not None:
            try:
                if self.light_on:
                    self.light_relay.on()
                else:
                    self.light_relay.off()
            except Exception as e:
                self.logger.error("GPIO light toggle error: %s", e)
        self.logger.info("Light toggled: %s", self.light_on)

    def set_thermostat(self, direction):
        if direction == "up":
            self.thermostat_temp = min(self.thermostat_temp + 1, 30)
        elif direction == "down":
            self.thermostat_temp = max(self.thermostat_temp - 1, 15)
        self.logger.info("Thermostat set to %d", self.thermostat_temp)

    def toggle_tv(self):
        self.tv_on = not self.tv_on
        if self.tv_relay is not None:
            try:
                if self.tv_on:
                    self.tv_relay.on()
                else:
                    self.tv_relay.off()
            except Exception as e:
                self.logger.error("GPIO TV toggle error: %s", e)
        self.logger.info("TV toggled: %s", self.tv_on)

    def get_state(self):
        return {
            "light_on": self.light_on,
            "thermostat_temp": self.thermostat_temp,
            "tv_on": self.tv_on,
        }


def log_to_cloud(data, cloud_queue):
    try:
        cloud_queue.put(data, timeout=1)
    except Full:
        logging.getLogger(__name__).warning("Cloud queue full, dropping data")


def log_to_file(data, log_file):
    try:
        with open(log_file, "a") as f:
            f.write(json.dumps(data) + "\n")
    except Exception as e:
        logging.getLogger(__name__).error("File logging error: %s", e)


def process_gesture(gesture, confidence, controller, last_gesture_time, cloud_queue, log_file):
    if confidence < 0.7:
        return last_gesture_time
    current_time = time.time()
    if current_time - last_gesture_time < 2.0:
        return last_gesture_time
    state = controller.get_state()
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
    log_data = {
        "timestamp": timestamp,
        "user_id": controller.user_id,
        "gesture": gesture,
        "confidence": confidence,
        "state": state,
    }
    log_to_file(log_data, log_file)
    log_to_cloud(log_data, cloud_queue)
    if gesture == "Open Hand":
        controller.toggle_light()
    elif gesture == "Closed Fist":
        controller.light_on = False
        if controller.light_relay is not None:
            controller.light_relay.off()
    elif gesture == "Pointing Up":
        controller.set_thermostat("up")
    elif gesture == "Pointing Down":
        controller.set_thermostat("down")
    elif gesture == "Peace Sign":
        controller.toggle_tv()
    return current_time


def camera_thread(camera, frame_queue):
    while True:
        frame = camera.read()
        if frame is not None:
            try:
                frame_queue.put(frame, timeout=1)
            except Full:
                logging.getLogger(__name__).warning("Frame queue full, dropping frame")
        time.sleep(1.0 / camera.framerate)


def inference_thread(frame_queue, recognizer, cloud_queue, log_file):
    last_gesture_time = 0.0
    while True:
        try:
            frame = frame_queue.get(timeout=1)
        except Empty:
            continue
        gesture, confidence = recognizer.recognize(frame)
        if gesture:
            last_gesture_time = process_gesture(
                gesture, confidence, controller, last_gesture_time, cloud_queue, log_file
            )


def cloud_thread(cloud_queue, log_file):
    while True:
        try:
            data = cloud_queue.get(timeout=1)
        except Empty:
            continue
        log_to_file(data, log_file)


def main():
    parser = argparse.ArgumentParser(description="Smart Home Gesture Control")
    parser.add_argument("--user_id", default="default_user")
    parser.add_argument("--model_path", default="gesture_model_quantized.tflite")
    parser.add_argument("--log_file", default="smart_home.log")
    parser.add_argument("--cloud_data_file", default="cloud_data.json")
    args = parser.parse_args()

    logging.basicConfig(
        filename=args.log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(name)s - %(message)s",
    )
    logger = logging.getLogger("main")
    logger.info("Starting Smart Home Gesture Control")

    camera = CameraHandler()
    recognizer = GestureRecognizer(args.model_path)
    controller = SmartHomeController(args.user_id)
    frame_queue = Queue(maxsize=10)
    cloud_queue = Queue(maxsize=10)

    if not recognizer.load_model():
        logger.error("Failed to load model. Exiting.")
        sys.exit(0)

    camera.start()

    threads = [
        threading.Thread(target=camera_thread, args=(camera, frame_queue), daemon=True),
        threading.Thread(
            target=inference_thread,
            args=(frame_queue, recognizer, cloud_queue, args.log_file),
            daemon=True,
        ),
        threading.Thread(
            target=cloud_thread, args=(cloud_queue, args.log_file), daemon=True
        ),
    ]
    for t in threads:
        t.start()

    def signal_handler(sig, frame):
        logger.info("Received signal %s, shutting down...", sig)
        camera.stop()
        for t in threads:
            t.join(timeout=2)
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        signal_handler(signal.SIGINT, None)


if __name__ == "__main__":
    main()

