import cv2
import numpy as np
import logging
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class CameraApp:
    def __init__(self, camera_index=0, resolution=(32, 32)):
        self.camera_index = camera_index
        self.resolution = resolution
        self.cap = None
        self.previous_frame = None
        self.running = False

    def initialize_camera(self):
        try:
            self.cap = cv2.VideoCapture(self.camera_index)
            if not self.cap.isOpened():
                raise IOError(f"Cannot open camera at index {self.camera_index}")
            self.cap.set(cv2.CAP_PROP_FRAME_WIDTH, self.resolution[0])
            self.cap.set(cv2.CAP_PROP_FRAME_HEIGHT, self.resolution[1])
            logging.info(f"Camera initialized with resolution {self.resolution}")
        except Exception as e:
            logging.error(f"Error initializing camera: {e}")
            self.cap = None

    def apply_gaussian_blur(self, frame):
        return cv2.GaussianBlur(frame, (3, 3), 0)

    def apply_clahe(self, frame):
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        clahe = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(8, 8))
        return clahe.apply(gray)

    def detect_motion(self, frame):
        if self.previous_frame is None:
            self.previous_frame = frame
            return False
        try:
            diff = cv2.absdiff(self.previous_frame, frame)
            mse = np.mean(diff ** 2)
            self.previous_frame = frame
            return mse > 100.0
        except Exception as e:
            logging.error(f"Error in motion detection: {e}")
            return False

    def process_frame(self, frame):
        blurred = self.apply_gaussian_blur(frame)
        compensated = self.apply_clahe(blurred)
        gray = cv2.cvtColor(compensated, cv2.COLOR_BGR2GRAY)
        edges = cv2.Canny(gray, 100, 200)
        return compensated, gray, edges

    def display_frames(self, original, compensated, gray, edges):
        cv2.imshow('Original', original)
        cv2.imshow('Compensated', compensated)
        cv2.imshow('Grayscale', gray)
        cv2.imshow('Edges', edges)

    def run(self):
        self.initialize_camera()
        if self.cap is None:
            return
        self.running = True
        try:
            while self.running:
                ret, frame = self.cap.read()
                if not ret:
                    logging.error("Failed to grab frame")
                    break
                compensated, gray, edges = self.process_frame(frame)
                if self.detect_motion(gray):
                    logging.info("Motion Detected using MSE!")
                self.display_frames(frame, compensated, gray, edges)
                if cv2.waitKey(1) & 0xFF == 27:
                    break
        except Exception as e:
            logging.error(f"Error during frame processing: {e}")
        finally:
            self.cleanup()

    def cleanup(self):
        if self.cap is not None:
            self.cap.release()
        cv2.destroyAllWindows()
        logging.info("Camera released and windows closed.")

    def signal_handler(self, signum, frame):
        logging.info(f"Signal {signum} received, shutting down...")
        self.running = False

if __name__ == "__main__":
    app = CameraApp(camera_index=0, resolution=(32, 32))
    signal.signal(signal.SIGINT, app.signal_handler)
    signal.signal(signal.SIGTERM, app.signal_handler)
    app.run()

