import signal
import sys
import time

running = True

def signal_handler(signum, frame):
    global running
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

camera = None
serial_port = None

try:
    camera = cv2.VideoCapture(0)
    if not camera.isOpened():
        raise IOError("Cannot open webcam")

    min_hsv = np.array([0, 0, 0])
    max_hsv = np.array([255, 255, 255])

    available_ports = [p.device for p in serial.tools.list_ports.comports()]
    preferred = "/dev/ttyACM0"
    port_name = None

    if preferred in available_ports:
        port_name = preferred
    elif available_ports:
        port_name = available_ports[0]

    if port_name:
        try:
            serial_port = serial.Serial(port_name, 9600, timeout=1)
            time.sleep(2)
        except serial.SerialException as e:
            print(f"Warning: could not open serial port {port_name}: {e}")
            serial_port = None
    else:
        print("Warning: no serial ports available")

    tracking_enabled = False

    while running:
        ret, frame = camera.read()
        if not ret:
            print("Failed to grab frame")
            break

        hsv_frame = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)

        if tracking_enabled:
            mask = cv2.inRange(hsv_frame, min_hsv, max_hsv)
            contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)

            for contour in contours:
                if cv2.contourArea(contour) > 500:
                    x, y, w, h = cv2.boundingRect(contour)
                    cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)

                    ball_x = x + w // 2
                    ball_y = y + h // 2
                    center_x = frame.shape[1] // 2
                    center_y = frame.shape[0] // 2

                    if abs(ball_x - center_x) > 50 and abs(ball_y - center_y) > 50:
                        if ball_x > center_x and ball_y > center_y:
                            output_data = "1"
                        elif ball_x > center_x and ball_y < center_y:
                            output_data = "2"
                        elif ball_x < center_x and ball_y > center_y:
                            output_data = "3"
                        elif ball_x < center_x and ball_y < center_y:
                            output_data = "4"
                        else:
                            output_data = "5"

                        if serial_port:
                            try:
                                serial_port.write(output_data.encode('utf-8'))
                            except serial.SerialException as e:
                                print(f"Serial write error: {e}")

        cv2.imshow("Frame", frame)

        key = cv2.waitKey(1) & 0xFF
        if key == ord('s'):
            roi = cv2.selectROI("Frame", frame, fromCenter=False)
            if roi != (0, 0, 0, 0):
                min_hsv = np.array([roi[0], roi[1], roi[2]])
                max_hsv = np.array([roi[0] + roi[2], roi[1] + roi[3], 255])
                tracking_enabled = True
        elif key == ord('o'):
            tracking_enabled = False
        elif key == 27:
            break

except Exception as e:
    print(f"Error: {e}")

finally:
    if camera is not None:
        camera.release()
    if serial_port is not None:
        try:
            serial_port.close()
        except Exception:
            pass
    cv2.destroyAllWindows()

