    cv2.destroyAllWindows()
    print("Cleanup complete.")


def send_command(ser, command):
    """Send a command to the Arduino via serial."""
    if ser is None or not ser.is_open:
        print("Serial port not open.", file=sys.stderr)
        return False
    try:
        ser.write(command.encode('utf-8'))
        return True
    except serial.SerialException as e:
        print(f"Serial communication error: {e}", file=sys.stderr)
        return False


def send_api_command(command):
    """Send a command to the API call interface."""
    print(f"Sending command to API: {command}")


def initialize_camera():
    """Initialize the CSI camera with picamera2."""
    global camera
    try:
        cam = Picamera2()
        config = cam.create_preview_configuration(
            main={"size": CAMERA_RESOLUTION, "format": "BGR888"}
        )
        cam.configure(config)
        cam.start()
        camera = cam
        return True
    except Exception as e:
        print(f"Camera initialization failed: {e}", file=sys.stderr)
        return False


def initialize_arduino():
    """Initialize the Arduino serial connection."""
    global arduino
    try:
        ser = serial.Serial(ARDUINO_PORT, ARDUINO_BAUDRATE, timeout=1)
        time.sleep(2)  # Allow Arduino to reset after serial open
        arduino = ser
        return True
    except serial.SerialException as e:
        print(f"Arduino initialization failed: {e}", file=sys.stderr)
        return False


def initialize_servos():
    """Initialize GPIO servos using gpiozero."""
    global servo_az, servo_el
    try:
        from gpiozero import PWMOutputDevice
        servo_az = PWMOutputDevice(SERVO_PIN_AZIMUTH, frequency=SERVO_FREQUENCY, initial_value=SERVO_INITIAL_DUTY / 100.0)
        servo_el = PWMOutputDevice(SERVO_PIN_ELEVATION, frequency=SERVO_FREQUENCY, initial_value=SERVO_INITIAL_DUTY / 100.0)
        return True
    except Exception as e:
        print(f"Servo initialization failed: {e}", file=sys.stderr)
        return False


def set_servo_duty(servo, duty):
    """Set the duty cycle of a PWM servo (0.0 to 1.0)."""
    if servo is None:
        return
    try:
        servo.value = duty / 100.0
    except Exception as e:
        print(f"Servo duty cycle error: {e}", file=sys.stderr)


def segment_color(frame):
    """Segment red objects using combined HSV and YCrCb color masks."""
    hsv = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
    mask_1 = cv2.inRange(hsv, np.array([160, 100, 100]), np.array([180, 255, 255]))
    ycr = cv2.cvtColor(frame, cv2.COLOR_BGR2YCrCb)
    mask_2 = cv2.inRange(ycr, np.array([0, 170, 0]), np.array([255, 255, 255]))
    mask = mask_1 | mask_2
    mask = cv2.erode(mask, np.ones((3, 3), np.uint8))
    mask = cv2.dilate(mask, np.ones((8, 8), np.uint8))
    return mask


def find_blob(mask):
    """Find the largest blob in the mask."""
    contours, _ = cv2.findContours(mask, cv2.RETR_CCOMP, cv2.CHAIN_APPROX_SIMPLE)
    largest_contour = None
    largest_area = 0
    for contour in contours:
        area = cv2.contourArea(contour)
        if area > largest_area:
            largest_area = area
            largest_contour = contour
    if largest_contour is None:
        return None
    x, y, w, h = cv2.boundingRect(largest_contour)
    return x + w / 2, y + h / 2, w, h


def calculate_blob_position(blob_x, blob_y, center_x, center_y):
    """Calculate blob position relative to center."""
    if blob_x < center_x - 10:
        return 'a'
    elif blob_x > center_x + 10:
        return 'b'
    elif blob_y < center_y - 10:
        return 'g'
    elif blob_y > center_y + 10:
        return 'j'
    else:
        return 'k'


def control_servos(blob_x, blob_y, center_x, center_y):
    """Control servos based on blob position."""
    position = calculate_blob_position(blob_x, blob_y, center_x, center_y)
    if position == 'a':
        send_api_command('a')
    elif position == 'b':
        send_api_command('b')
    elif position == 'g':
        send_api_command('g')
    elif position == 'j':
        send_api_command('j')
    elif position == 'k':
        send_api_command('k')

    if blob_x < center_x - 30 or blob_x > center_x + 30 or blob_y < center_y - 30 or blob_y > center_y + 30:
        send_api_command('f')
    else:
        send_api_command('d')


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not initialize_camera():
        sys.exit(1)
    if not initialize_arduino():
        sys.exit(1)
    if not initialize_servos():
        sys.exit(1)

    center_x = CAMERA_RESOLUTION[0] / 2
    center_y = CAMERA_RESOLUTION[1] / 2
    el_duty = SERVO_INITIAL_DUTY

    try:
        while running:
            frame = camera.capture_array()
            if frame is None:
                continue

            mask = segment_color(frame)
            blob = find_blob(mask)

            if blob:
                blob_x, blob_y, _, _ = blob
                control_servos(blob_x, blob_y, center_x, center_y)

                # Sweep elevation servo
                if el_duty < SERVO_MAX_DUTY:
                    el_duty += SERVO_DUTY_STEP
                else:
                    el_duty = SERVO_INITIAL_DUTY
                set_servo_duty(servo_el, el_duty)

                # Stop azimuth servo if close or far
                if blob_x < center_x - 30 or blob_x > center_x + 30:
                    set_servo_duty(servo_az, SERVO_STOP_DUTY)
                else:
                    set_servo_duty(servo_az, SERVO_INITIAL_DUTY)

                # Reset elevation if far
                if blob_x < center_x - 30 or blob_x > center_x + 30 or blob_y < center_y - 30 or blob_y > center_y + 30:
                    el_duty = SERVO_INITIAL_DUTY
                    set_servo_duty(servo_el, SERVO_INITIAL_DUTY)
            else:
                # Object not found: stop servos and reset elevation
                set_servo_duty(servo_az, SERVO_STOP_DUTY)
                set_servo_duty(servo_el, SERVO_INITIAL_DUTY)
                el_duty = SERVO_INITIAL_DUTY
                send_api_command('h')

            cv2.imshow("Mask", mask)
            cv2.imshow("Frame", frame)

            if cv2.waitKey(1) & 0xFF == ord('q'):
                break

    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

