import datetime

try:
    import RPi.GPIO as GPIO
    _GPIO_AVAILABLE = True
except ImportError:
    _GPIO_AVAILABLE = False

try:
    from picamera2 import Picamera2
    _CAMERA_AVAILABLE = True
except ImportError:
    _CAMERA_AVAILABLE = False

try:
    import speech_recognition as sr
    _SPEECH_RECOGNITION_AVAILABLE = True
except ImportError:
    _SPEECH_RECOGNITION_AVAILABLE = False

try:
    import board
    import adafruit_dht
    _DHT_AVAILABLE = True
except ImportError:
    _DHT_AVAILABLE = False

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

DHT_PIN = 4
LIGHT_PIN = 17

_running = True

def signal_handler(signum, frame):
    global _running
    logging.info(f"Signal {signum} received, shutting down...")
    _running = False

def init_gpio():
    if not _GPIO_AVAILABLE:
        logging.warning("RPi.GPIO not available; running in simulation mode.")
        return False
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LIGHT_PIN, GPIO.OUT, initial=GPIO.LOW)
        logging.info("GPIO initialized successfully.")
        return True
    except Exception as e:
        logging.error(f"GPIO initialization failed: {e}")
        return False

def cleanup_gpio():
    if _GPIO_AVAILABLE:
        try:
            GPIO.cleanup()
            logging.info("GPIO cleaned up.")
        except Exception as e:
            logging.error(f"GPIO cleanup failed: {e}")

def init_camera():
    if not _CAMERA_AVAILABLE:
        logging.warning("picamera2 not available; running in simulation mode.")
        return None
    try:
        picam2 = Picamera2()
        picam2.configure(picam2.create_still_configuration())
        picam2.start()
        logging.info("Camera initialized successfully.")
        return picam2
    except Exception as e:
        logging.error(f"Camera initialization failed: {e}")
        return None

def capture_image(picam2, filename="greenhouse.jpg"):
    if picam2 is None:
        logging.warning("Camera unavailable; saving placeholder image.")
        try:
            with open(filename, "wb") as f:
                f.write(os.urandom(64))
            logging.info(f"Placeholder image saved as {filename}")
        except Exception as e:
            logging.error(f"Failed to save placeholder image: {e}")
        return
    try:
        picam2.capture_file(filename)
        logging.info(f"Image saved as {filename}")
    except Exception as e:
        logging.error(f"Failed to capture image: {e}")

def init_dht():
    if not _DHT_AVAILABLE:
        logging.warning("adafruit-circuitpython-dht not available; running in simulation mode.")
        return None
    try:
        dht = adafruit_dht.DHT11(board.D4)
        logging.info("DHT11 initialized successfully.")
        return dht
    except Exception as e:
        logging.error(f"DHT11 initialization failed: {e}")
        return None

def read_temperature(dht):
    if dht is None:
        logging.warning("Simulating temperature reading...")
        return random.uniform(15.0, 35.0)
    try:
        temperature = dht.temperature
        if temperature is None:
            raise RuntimeError("Sensor returned None")
        logging.info(f"Temperature: {temperature:.2f} C")
        return temperature
    except Exception as e:
        logging.error(f"Failed to read temperature: {e}")
        return random.uniform(15.0, 35.0)

def listen_for_wake_word(recognizer, source):
    try:
        with sr.Microphone() as audio_source:
            recognizer.adjust_for_ambient_noise(audio_source)
            logging.info("Listening for 'Greenhouse'...")
            audio = recognizer.listen(audio_source, timeout=5)
    except sr.WaitTimeoutError:
        logging.warning("No speech detected within 5 seconds.")
        return None
    except Exception as e:
        logging.error(f"Microphone error: {e}")
        return None

    try:
        words = recognizer.recognize_google(audio)
        logging.info(f"Heard: {words}")
        return words.lower()
    except sr.UnknownValueError:
        logging.warning("Could not understand audio.")
        return None
    except sr.RequestError as e:
        logging.error(f"Speech recognition service error: {e}")
        return None

def process_voice_command(command):
    if not command:
        return
    if "turn on the lights" in command:
        GPIO.output(LIGHT_PIN, GPIO.HIGH)
        logging.info("Lights turned ON")
    elif "turn off the lights" in command:
        GPIO.output(LIGHT_PIN, GPIO.LOW)
        logging.info("Lights turned OFF")
    elif "what is the temperature" in command:
        temperature = read_temperature(None)
        print(f"Temperature: {temperature:.2f} C")
    elif "take a picture" in command:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = f"greenhouse_{timestamp}.jpg"
        capture_image(None, filename)
    else:
        print("Unknown command.")

def main():
    global _running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    gpio_ok = init_gpio()
    picam2 = init_camera()
    dht = init_dht()

    if not _SPEECH_RECOGNITION_AVAILABLE:
        logging.warning("speech_recognition not available; voice commands disabled.")

    recognizer = sr.Recognizer()
    try:
        mic = sr.Microphone()
    except Exception as e:
        logging.error(f"Microphone initialization failed: {e}")
        mic = None

    try:
        while _running:
            if mic is not None:
                command = listen_for_wake_word(recognizer, mic)
                if command:
                    process_voice_command(command)
            time.sleep(1)
    except Exception as e:
        logging.error(f"Unexpected error in main loop: {e}")
    finally:
        if picam2 is not None:
            try:
                picam2.stop()
                picam2.close()
            except Exception as e:
                logging.error(f"Error releasing camera: {e}")
        if dht is not None:
            try:
                dht.exit()
            except Exception:
                pass
        cleanup_gpio()
        logging.info("Program terminated.")

if __name__ == "__main__":
    main()

