import cv2
import time
import signal
import sys
import logging
import RPi.GPIO as GPIO

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

CAMERA_INDEX = 0
FRAME_RATE = 10
WINDOW_NAME = "Output Image"
GPIO_PIN = 17
ROI_START_X, ROI_START_Y, ROI_END_X, ROI_END_Y = 10, 40, 150, 280

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_camera(camera_index=CAMERA_INDEX, frame_rate=FRAME_RATE):
    try:
        cap = cv2.VideoCapture(camera_index)
        if not cap.isOpened():
            raise IOError(f"Cannot open camera at index {camera_index}")
        cap.set(cv2.CAP_PROP_FRAME_WIDTH, 640)
        cap.set(cv2.CAP_PROP_FRAME_HEIGHT, 480)
        cap.set(cv2.CAP_PROP_FPS, frame_rate)
        actual_fps = cap.get(cv2.CAP_PROP_FPS)
        logging.info(f"Camera initialized at {actual_fps:.1f} FPS")
        return cap
    except Exception as e:
        logging.error(f"Error initializing camera: {e}")
        return None

def process_frame(frame, start_x, start_y, end_x, end_y):
    try:
        roi = frame[start_y:end_y, start_x:end_x]
        return roi
    except Exception as e:
        logging.error(f"Error processing frame: {e}")
        return None

def display_image(window_name, image):
    try:
        cv2.imshow(window_name, image)
        key = cv2.waitKey(1) & 0xFF
        if key == 10:
            return False
        return True
    except Exception as e:
        logging.error(f"Error displaying image: {e}")
        return False

def cleanup(cap, gpio_pin):
    try:
        if cap is not None and cap.isOpened():
            cap.release()
            logging.info("Camera released.")
    except Exception as e:
        logging.error(f"Error releasing camera: {e}")
    try:
        cv2.destroyAllWindows()
        logging.info("Windows closed.")
    except Exception as e:
        logging.error(f"Error closing windows: {e}")
    try:
        GPIO.output(gpio_pin, GPIO.LOW)
        GPIO.cleanup(gpio_pin)
        logging.info(f"GPIO pin {gpio_pin} set to LOW and cleaned up.")
    except Exception as e:
        logging.error(f"Error cleaning up GPIO: {e}")

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    cap = initialize_camera()
    if cap is None:
        sys.exit(1)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(GPIO_PIN, GPIO.OUT, initial=GPIO.HIGH)
        logging.info(f"GPIO pin {GPIO_PIN} set to HIGH.")

        while _running:
            ret, frame = cap.read()
            if not ret:
                logging.error("Failed to grab frame")
                break

            processed_image = process_frame(frame, ROI_START_X, ROI_START_Y, ROI_END_X, ROI_END_Y)
            if processed_image is None:
                continue

            if not display_image(WINDOW_NAME, processed_image):
                break

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup(cap, GPIO_PIN)

if __name__ == "__main__":
    main()

