import signal
import sys
import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi environment.")
    sys.exit(1)

# --- Configuration -----------------------------------------------------------
INPUT_PINS = [4, 5, 6]
OUTPUT_PINS = [23, 24]
POLL_INTERVAL = 0.05

# --- Globals -----------------------------------------------------------------
_running = True
_output_states = {23: False, 24: False}


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def _cleanup():
    """Release GPIO resources safely."""
    try:
        GPIO.cleanup()
    except Exception:
        pass


def main():
    global _running

    # Register signal handlers for graceful termination
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Configure GPIO mode
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
    except Exception as e:
        print(f"Error: Failed to set GPIO mode: {e}")
        _cleanup()
        sys.exit(1)

    # Configure inputs with pull-up resistors (active-low)
    for pin in INPUT_PINS:
        try:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        except Exception as e:
            print(f"Error: Failed to configure input pin {pin}: {e}")
            _cleanup()
            sys.exit(1)

    # Configure outputs, initially LOW
    for pin in OUTPUT_PINS:
        try:
            GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
        except Exception as e:
            print(f"Error: Failed to configure output pin {pin}: {e}")
            _cleanup()
            sys.exit(1)

    print("GPIO initialized successfully. Monitoring inputs...")

    # Main polling loop
    try:
        while _running:
            # Read all inputs (LOW when active)
            active_inputs = [pin for pin in INPUT_PINS if GPIO.input(pin) == GPIO.LOW]

            # GPIO 4: set GPIO 23 HIGH
            if 4 in active_inputs:
                if not _output_states[23]:
                    GPIO.output(23, GPIO.HIGH)
                    _output_states[23] = True

            # GPIO 5: set GPIO 23 LOW
            if 5 in active_inputs:
                if _output_states[23]:
                    GPIO.output(23, GPIO.LOW)
                    _output_states[23] = False

            # GPIO 6: toggle GPIO 24
            if 6 in active_inputs:
                _output_states[24] = not _output_states[24]
                GPIO.output(24, GPIO.HIGH if _output_states[24] else GPIO.LOW)

            time.sleep(POLL_INTERVAL)

    except Exception as e:
        print(f"Runtime error: {e}")
    finally:
        _cleanup()
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

