        self.lock_pin = lock_pin
        self.button_pin = button_pin
        self.bus = None
        self.lock_state = False
        self.button_state = False
        self._setup_gpio()

    def _setup_gpio(self):
        if GPIO is None:
            raise RuntimeError("RPi.GPIO not available")
        GPIO.setwarnings(False)
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(self.lock_pin, GPIO.OUT, initial=GPIO.HIGH)
        GPIO.setup(self.button_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)

    def lock(self):
        if not self.lock_state:
            return
        if GPIO is not None:
            GPIO.output(self.lock_pin, GPIO.HIGH)
        self.lock_state = False

    def unlock(self):
        if self.lock_state:
            return
        if GPIO is not None:
            GPIO.output(self.lock_pin, GPIO.LOW)
        self.lock_state = True

    def is_button_up(self):
        if GPIO is None:
            return False
        return bool(GPIO.input(self.button_pin))

    def cleanup(self):
        if GPIO is not None:
            GPIO.cleanup()


class AudioSystem:
    def __init__(self, freq=48000, size=-16, channels=1, buff=1024):
