    def play_sound(self, sound_file, channel=0):
        audio_helper.play_sound(self.engine, sound_file, channel)

    def quit(self):
        audio_helper.quit(self.engine)


class Camera:
    def __init__(self, getter=None):
        self.getter = getter
        if self.getter is None:
            self.getter = self._default_getter

    def _default_getter(self):
        cap = cv2.VideoCapture(0)
        if not cap.isOpened():
            raise RuntimeError("Cannot open camera")
        try:
            ret, frame = cap.read()
            if not ret or frame is None:
