import sys
import signal
import serial

BLUETOOTH_DEVICE = "/dev/rfcomm4"
BLUETOOTH_BAUDRATE = 38400

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bluetooth = serial.Serial(
            port=BLUETOOTH_DEVICE,
            baudrate=BLUETOOTH_BAUDRATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            xonxoff=False,
            rtscts=False,
            dsrdtr=False,
            timeout=1.0,
        )
    except serial.SerialException as exc:
        print(f"Error: cannot open {BLUETOOTH_DEVICE}: {exc}", file=sys.stderr)
        return 1
    except OSError as exc:
        print(f"Error: device not available {BLUETOOTH_DEVICE}: {exc}", file=sys.stderr)
        return 1

    try:
        while _running:
            try:
                user_input = input("Enter data to send (or 'q' to quit): ")
            except EOFError:
                break

            if not _running:
                break

            if user_input.strip().lower() == "q":
                break

            data_to_send = f"X{user_input}"
            encoded_data = data_to_send.encode("utf-8")

            try:
                bytes_written = bluetooth.write(encoded_data)
                if bytes_written is not None:
                    print(f"Sent {bytes_written} bytes", file=sys.stderr)
            except serial.SerialException as exc:
                print(f"Error: write failed: {exc}", file=sys.stderr)
                break
    finally:
        try:
            bluetooth.close()
        except Exception:
            pass

    return 0

if __name__ == "__main__":
    sys.exit(main())

