import cv2
import pyzbar.pyzbar as pyzbar
import datetime
import csv
import os
import signal
import sys

CAMERA_INDEX = 0
LOG_FILE = "inventory_log.csv"
ERROR_LOG = "error_log.txt"
CAPTURE_INTERVAL = 0.2
CAMERA_IDENTIFIER = "Camera 1"

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def log_error(message):
    timestamp = datetime.datetime.now().isoformat()
    try:
        with open(ERROR_LOG, "a") as f:
            f.write(f"{timestamp} - {message}\n")
    except OSError as e:
        print(f"CRITICAL: Cannot write to error log: {e}", file=sys.stderr)

def init_camera(camera_index=CAMERA_INDEX):
    try:
        cap = cv2.VideoCapture(camera_index)
        if not cap.isOpened():
            log_error(f"Failed to open camera at index {camera_index}")
            return None
        return cap
    except Exception as e:
        log_error(f"Camera initialisation error: {e}")
        return None

def capture_frame(cap):
    try:
        ret, frame = cap.read()
        if not ret or frame is None:
            log_error("Failed to capture frame from camera")
            return None
        return frame
    except Exception as e:
        log_error(f"Frame capture error: {e}")
        return None

def decode_qr_code(frame):
    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        decoded_objects = pyzbar.decode(gray)
        if not decoded_objects:
            return None
        for obj in decoded_objects:
            try:
                data = obj.data.decode("utf-8")
                return data
            except Exception as e:
                log_error(f"QR code decode error: {e}")
                return None
        return None
    except Exception as e:
        log_error(f"QR code decoding error: {e}")
        return None

def validate_data(data):
    if not data:
        return False
    return all(c.isalnum() for c in data)

def log_inventory(item_id, camera_id, timestamp):
    try:
        file_exists = os.path.isfile(LOG_FILE) and os.path.getsize(LOG_FILE) > 0
        with open(LOG_FILE, "a", newline="") as csvfile:
            writer = csv.writer(csvfile)
            if not file_exists:
                writer.writerow(["Camera ID", "Item ID", "Timestamp"])
            writer.writerow([camera_id, item_id, timestamp])
    except OSError as e:
        log_error(f"File I/O error: {e}")

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    cap = init_camera()
    if cap is None:
        print("Camera initialisation failed. Exiting.", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            frame = capture_frame(cap)
            if frame is None:
                continue

            item_id = decode_qr_code(frame)
            if item_id is not None and validate_data(item_id):
                timestamp = datetime.datetime.now().isoformat()
                log_inventory(item_id, CAMERA_IDENTIFIER, timestamp)
                print(f"Scanned: {item_id}")

            cv2.waitKey(int(CAPTURE_INTERVAL * 1000))
    except Exception as e:
        log_error(f"Unexpected error in main loop: {e}")
    finally:
        if cap is not None:
            cap.release()
        cv2.destroyAllWindows()
        print("Program terminated gracefully.")

if __name__ == "__main__":
    main()

