import cv2
import numpy as np
import time
import signal
import sys
import serial
import atexit

try:
    import RPi.GPIO as GPIO
except ImportError:
    GPIO = None

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

SERVO_PIN_1 = 7
SERVO_PIN_2 = 13
SERVO_FREQ = 50
SERVO_CENTER_DUTY = 7.0
X_THRESHOLD = 24
MIN_OBJECT_AREA = 10

running = True


def signal_handler(sig, frame):
    global running
    running = False


signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)


class BallTracker:
    def __init__(self, camera_id=0, width=160, height=120, fps=16):
        self.width = width
        self.height = height
        self.fps = fps
        self.camera = None
        self.servo1 = None
        self.servo2 = None
        self.uart = None
        self.ball_x = None
        self.ball_y = None
        self.ball_area = None
        self.servo_lock = False
        self.uart_lock = False
        self.initialize_camera(camera_id)
        self.initialize_servos()
        self.initialize_uart()
        atexit.register(self.cleanup)

    def initialize_camera(self, camera_id):
        if Picamera2 is None:
            raise RuntimeError("picamera2 library not available")
        for attempt in range(3):
            try:
                self.camera = Picamera2(camera_id)
                config = self.camera.create_preview_configuration(
                    main={"size": (self.width, self.height), "format": "BGR888"}
                )
                self.camera.configure(config)
                self.camera.start()
                time.sleep(2)
                return
            except Exception as e:
                print(f"Camera init attempt {attempt + 1} failed: {e}")
                if self.camera:
                    try:
                        self.camera.close()
                    except Exception:
                        pass
                    self.camera = None
                time.sleep(5)
        raise RuntimeError("Camera initialization failed after 3 attempts")

    def initialize_servos(self):
        if GPIO is None:
            print("RPi.GPIO not available; servos disabled")
            return
        GPIO.setmode(GPIO.BOARD)
        GPIO.setup(SERVO_PIN_1, GPIO.OUT)
        GPIO.setup(SERVO_PIN_2, GPIO.OUT)
        pwm1 = GPIO.PWM(SERVO_PIN_1, SERVO_FREQ)
        pwm2 = GPIO.PWM(SERVO_PIN_2, SERVO_FREQ)
        pwm1.start(SERVO_CENTER_DUTY)
        pwm2.start(SERVO_CENTER_DUTY)
        self.servo1 = pwm1
        self.servo2 = pwm2

    def initialize_uart(self):
        try:
            self.uart = serial.Serial("/dev/serial0", 115200, timeout=1)
            time.sleep(2)
        except Exception as e:
            print(f"UART init failed: {e}")
            self.uart = None

    def segment_color(self, frame):
        hsv = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
        mask1 = cv2.inRange(hsv, np.array([160, 160, 10]), np.array([190, 255, 255]))
        ycr = cv2.cvtColor(frame, cv2.COLOR_BGR2YCrCb)
        mask2 = cv2.inRange(ycr, np.array([0, 165, 0]), np.array([255, 255, 255]))
        mask = mask1 | mask2
        mask = cv2.erode(mask, None, iterations=2)
        mask = cv2.dilate(mask, None, iterations=2)
        return mask

    def find_blob(self, mask):
        contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
        largest_contour = None
        largest_area = 0
        for contour in contours:
            area = cv2.contourArea(contour)
            if area > largest_area:
                largest_area = area
                largest_contour = contour
        if largest_contour is not None and largest_area > MIN_OBJECT_AREA:
            x, y, w, h = cv2.boundingRect(largest_contour)
            self.ball_x = x + w / 2
            self.ball_y = y + h / 2
            self.ball_area = largest_area
            return True
        return False

    def control_servos(self):
        if self.servo_lock:
            return
        self.servo_lock = True
        try:
            if self.ball_x is not None:
                if self.ball_x < self.width / 3:
                    self.servo1.ChangeDutyCycle(10)
                    self.servo2.ChangeDutyCycle(10)
                elif self.ball_x > self.width * 2 / 3:
                    self.servo1.ChangeDutyCycle(10)
                    self.servo2.ChangeDutyCycle(10)
                else:
                    self.servo1.ChangeDutyCycle(SERVO_CENTER_DUTY)
                    self.servo2.ChangeDutyCycle(SERVO_CENTER_DUTY)
