    sys.exit(1)

try:
    from torchvision.models import ResNet50_Weights
except ImportError:
    print("Error: torchvision 0.13.0+ is required for ResNet50_Weights.")
    sys.exit(1)


class GracefulKiller:
    """Handles SIGINT and SIGTERM for clean shutdown."""
    def __init__(self):
        self.kill_now = False
        signal.signal(signal.SIGINT, self._exit_gracefully)
        signal.signal(signal.SIGTERM, self._exit_gracefully)

    def _exit_gracefully(self, signum, frame):
        print(f"\nReceived signal {signum}, shutting down gracefully...")
        self.kill_now = True


class ImageClassifier:
    """
    A class to encapsulate image classification functionality.
    """

    def __init__(self, model_name="resnet50", weights=None, num_classes=1000,
                 image_size=224, top_k=3):
        self.model_name = model_name
        self.num_classes = num_classes
        self.image_size = image_size
        self.top_k = top_k
        self.transform = self._build_transform()
        self.device = self._get_device()
        self.model = self._load_model(weights)
        self.killer = GracefulKiller()

    def _get_device(self):
        """Determines the device to use for inference."""
        if torch.cuda.is_available():
            return torch.device("cuda")
        return torch.device("cpu")

    def _build_transform(self):
        """Builds the image transformation pipeline."""
        return transforms.Compose([
            transforms.Resize(self.image_size),
            transforms.CenterCrop(self.image_size),
            transforms.ToTensor(),
            transforms.Normalize(mean=[0.485, 0.456, 0.406],
                                 std=[0.229, 0.224, 0.225])
        ])

    def _load_model(self, weights):
        """Loads the pre-trained model."""
        try:
            if weights is not None:
                model = resnet50(weights=weights)
            else:
                model = resnet50(weights=ResNet50_Weights.DEFAULT)
            model.to(self.device)
            model.eval()
            return model
        except Exception as e:
            print(f"Error loading model: {e}")
            sys.exit(1)

    def preprocess_image(self, image_path):
        """Loads and preprocesses the image."""
        try:
            image = cv2.imread(image_path)
            if image is None:
                raise ValueError(f"Could not read image from {image_path}")

            # OpenCV reads in BGR format; convert to RGB for torchvision
            image = cv2.cvtColor(image, cv2.COLOR_BGR2RGB)
            return self.transform(image).unsqueeze(0).to(self.device)
        except Exception as e:
            print(f"Error preprocessing image: {e}")
            return None

    def predict(self, image_path):
        """Predicts the class of the image."""
        if self.killer.kill_now:
            return None

        try:
            input_tensor = self.preprocess_image(image_path)
            if input_tensor is None:
                return None

            with torch.no_grad():
                output = self.model(input_tensor)

            probabilities = torch.nn.functional.softmax(output[0], dim=0)
            top_k_probabilities, top_k_indices = probabilities.topk(self.top_k)

            return top_k_probabilities.tolist(), top_k_indices.tolist()
        except Exception as e:
            print(f"Error during prediction: {e}")
            return None

    def run(self, image_path):
        """Runs the image classification process."""
        if self.killer.kill_now:
            return

        probabilities, indices = self.predict(image_path)

        if probabilities is not None:
            print(f"Top {self.top_k} predictions:")
            for i, (prob, idx) in enumerate(zip(probabilities, indices)):
                print(f"  {i + 1}: class {idx:5d} ({prob:.4f})")
        else:
            print("Prediction failed.")


def main():
    """Main function to run the image classification."""
    classifier = ImageClassifier(
        model_name="resnet50",
        weights=ResNet50_Weights.DEFAULT,
        num_classes=1000,
        image_size=224,
        top_k=3
    )

    image_dir = "images"
    try:
        os.makedirs(image_dir, exist_ok=True)
    except OSError as e:
        print(f"Error creating directory {image_dir}: {e}")
        sys.exit(1)

    timestamp = int(time.time())
    image_path = os.path.join(image_dir, f"{timestamp}.jpg")

    cap = cv2.VideoCapture(0)
    if not cap.isOpened():
        print("Error: Could not open camera at index 0.")
        sys.exit(1)

    try:
        ret, frame = cap.read()
        if not ret:
            print("Error: Could not read frame from camera.")
            return

        if not cv2.imwrite(image_path, frame):
            print(f"Error: Could not write image to {image_path}")
            return

        print(f"Image saved to {image_path}")
        classifier.run(image_path)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        cap.release()
        print("Camera released.")


if __name__ == "__main__":
    main()

