            self._buffer.clear()

    def close(self) -> None:
        with self._lock:
            self._closed = True
            self._buffer.clear()


class MotionDetectionBuffer:
    """Thread-safe buffer that detects motion between two complete JPEG frames."""

    def __init__(self, motion_detection_callback: Callable[[bytes, bytes], None]) -> None:
        if not callable(motion_detection_callback):
            raise TypeError("motion_detection_callback must be callable")
        self._motion_detection_callback = motion_detection_callback
        self._lock = threading.Lock()
        self._buffer = bytearray()
        self._frame1: Optional[bytes] = None
        self._frame2: Optional[bytes] = None
        self._closed = False

    def write(self, data: bytes) -> int:
        with self._lock:
            if self._closed:
                return 0
            self._buffer.extend(data)
            return len(data)

    def _assemble_frame(self) -> Optional[bytes]:
        """Return the next complete JPEG frame from the buffer, or None if incomplete."""
        if not self._buffer:
            return None
        try:
            idx = self._buffer.index(0xFF, 1)
            if idx == -1:
                return None
            marker = self._buffer[idx:idx + 2]
            if marker[0] != 0xFF or marker[1] != 0xD8:
                return None
            frame = bytes(self._buffer[: idx + 2])
            self._buffer = self._buffer[idx + 2:]
            return frame
        except (IndexError, ValueError) as exc:
            logger.debug("Incomplete JPEG frame: %s", exc)
            return None

    def _process_frame(self, frame: bytes) -> None:
        with self._lock:
            self._frame2 = self._frame1
            self._frame1 = frame

        if self._frame1 is None or self._frame2 is None:
            return

        try:
            self._motion_detection_callback(self._frame1, self._frame2)
        except Exception as exc:
            logger.error("Motion detection callback raised an exception: %s", exc)

    def flush(self) -> None:
        with self._lock:
            self._buffer.clear()
            self._frame1 = None
            self._frame2 = None

    def close(self) -> None:
        with self._lock:
            self._closed = True
            self._buffer.clear()
            self._frame1 = None
            self._frame2 = None


def decode_jpeg(data: bytes) -> Optional[np.ndarray]:
    """Decode JPEG bytes into a NumPy array.

    Returns None if the data is not a complete JPEG image.
    """
    try:
        import cv2
    except ImportError:
        logger.error("OpenCV is required for JPEG decoding.")
        return None

    try:
        arr = cv2.imdecode(np.frombuffer(data, dtype=np.uint8), cv2.IMREAD_COLOR)
        if arr is None:
            logger.error("Failed to decode JPEG image.")
            return None
        return arr
    except Exception as exc:
        logger.error("Error decoding JPEG image: %s", exc)
        return None


def detect_motion(frame1: bytes, frame2: bytes) -> None:
    """Detect motion between two JPEG frames using OpenCV."""
    try:
        import cv2
    except ImportError:
        logger.error("OpenCV is required for motion detection.")
        return

    img1 = decode_jpeg(frame1)
    img2 = decode_jpeg(frame2)

    if img1 is None or img2 is None:
        return

    diff = cv2.absdiff(img1, img2)
    gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
    blur = cv2.GaussianBlur(gray, (5, 5), 0)
    _, thresh = cv2.threshold(blur, 20, 255, cv2.THRESH_BINARY)
    dilated = cv2.dilate(thresh, None, iterations=3)
    contours, _ = cv2.findContours(dilated, cv2.RETR_TREE, cv2.CHAIN_APPROX_SIMPLE)

    for contour in contours:
        if cv2.contourArea(contour) < 25:
            continue
        (x, y, w, h) = cv2.boundingRect(contour)
        logger.info("Motion detected: %d, %d, %d, %d", x, y, w, h)


def main() -> None:
    logging.basicConfig(level=logging.INFO)

    stream_buffer = CameraStreamBuffer()
    motion_buffer = MotionDetectionBuffer(detect_motion)

    stop_event = threading.Event()

    def signal_handler(signum, frame):
        logger.info("Signal %d received, shutting down...", signum)
        stop_event.set()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while not stop_event.is_set():
            frame = stream_buffer.get_frame()
            if frame:
                motion_buffer.write(frame)
                motion_buffer._process_frame(frame)
            time.sleep(0.01)
    except Exception as exc:
        logger.error("Unexpected error in main loop: %s", exc)
    finally:
        logger.info("Cleaning up resources...")
        stream_buffer.close()
        motion_buffer.close()
        stream_buffer.flush()
        motion_buffer.flush()
        logger.info("Shutdown complete.")


if __name__ == "__main__":
    main()

