import signal
import sys
import time
import threading

import config
import face
import helpers.audio as audio_helper
from helpers.mixer import Sound
from helpers import imutils

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

try:
    from gpiozero import Button
except ImportError:
    Button = None

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

try:
    from gpiozero import OutputDevice
except ImportError:
    OutputDevice = None


class Door:
    LOCK_PIN = 18
    BUTTON_PIN = 17

    def __init__(self):
        self.lock = None
        self.button = None
        self.camera = None
        self._lock_thread = None
        self._lock_thread_event = threading.Event()
        self._lock_thread_stop = threading.Event()
        self._lock_thread_locked = threading.Event()
        self._lock_thread_unlocked = threading.Event()
        self._lock_thread_error = None

        if Picamera2 is not None:
            try:
                self.camera = Picamera2()
                self.camera.configure(self.camera.create_preview_configuration(main={"format": "RGB888"}))
                self.camera.start()
            except Exception as e:
                print(f"[ERROR] Failed to initialize camera: {e}")
                self.camera = None
        else:
            print("[WARN] picamera2 not available; camera disabled.")

        if OutputDevice is not None:
            try:
                self.lock = OutputDevice(self.LOCK_PIN, active_high=True, initial_value=False)
            except Exception as e:
                print(f"[ERROR] Failed to initialize lock pin {self.LOCK_PIN}: {e}")
                self.lock = None
        else:
            print("[WARN] gpiozero not available; lock disabled.")

        if Button is not None:
            try:
                self.button = Button(self.BUTTON_PIN, pull_up=True)
            except Exception as e:
                print(f"[ERROR] Failed to initialize button pin {self.BUTTON_PIN}: {e}")
                self.button = None
        else:
            print("[WARN] gpiozero not available; button disabled.")

        self.sounds = {
            "welcome": Sound(config.WELCOME_SOUND, audio_helper.AUDIO_FREQ),
            "wait": Sound(config.WAIT_SOUND, audio_helper.AUDIO_FREQ),
            "later": Sound(config.LATER_SOUND, audio_helper.AUDIO_FREQ),
        }

        self.recognizer = None
        try:
            self.recognizer = cv2.face.EigenFaceRecognizer_create()
            self.recognizer.read(config.TRAINING_FILE)
        except Exception as e:
            print(f"[ERROR] Failed to load training data: {e}")
            self.recognizer = None

    def is_button_up(self):
        if self.button is None:
            return False
        try:
            return self.button.is_active
        except Exception:
            return False

    def _lock_thread_func(self):
        try:
            while not self._lock_thread_stop.is_set():
                if self._lock_thread_event.wait(timeout=1.0):
                    self._lock_thread_event.clear()
                    if self.lock is not None:
                        self.lock.on()
                    self._lock_thread_locked.set()
                    print("[INFO] Door locked.")
                elif self._lock_thread_stop.is_set():
                    break
        except Exception as e:
            self._lock_thread_error = e
            print(f"[ERROR] Lock thread error: {e}")
        finally:
            if self.lock is not None:
                try:
                    self.lock.off()
                except Exception:
                    pass
            self._lock_thread_unlocked.set()

    def lock_door(self):
        if self._lock_thread is None or not self._lock_thread.is_alive():
            self._lock_thread_stop.clear()
            self._lock_thread_locked.clear()
            self._lock_thread_unlocked.clear()
            self._lock_thread = threading.Thread(target=self._lock_thread_func, daemon=True)
            self._lock_thread.start()

    def unlock_door(self):
        if self._lock_thread is not None and self._lock_thread.is_alive():
            self._lock_thread_event.set()
            self._lock_thread_stop.set()
            self._lock_thread.join(timeout=2.0)
            if self._lock_thread.is_alive():
                print("[WARN] Lock thread did not stop cleanly.")

    def cleanup(self):
        self.unlock_door()
        if self.camera is not None:
            try:
                self.camera.stop()
            except Exception:
                pass
        if self.lock is not None:
            try:
                self.lock.close()
            except Exception:
                pass
        if self.button is not None:
            try:
                self.button.close()
            except Exception:
                pass


def main():
    door = Door()

    def signal_handler(signum, frame):
        print(f"[INFO] Signal {signum} received, shutting down.")
        door.cleanup()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while True:
            if door.is_button_up():
                if door.recognizer is not None:
                    try:
                        gray = face.prepare_image("test_image.jpg")
                        if gray is None:
                            print("[WARN] No face detected.")
                            door.sounds["later"].play()
                            time.sleep(0.5)
                            continue

                        label, confidence = door.recognizer.predict(gray)
                        print(f"[INFO] Predicted label: {label}, Confidence: {confidence}")

                        if label == config.POSITIVE_LABEL and confidence < config.POSITIVE_THRESHOLD:
                            print("[INFO] Recognized face! Unlocking Door.")
                            door.sounds["welcome"].play()
                            door.lock_door()
                            time.sleep(2.0)
                            door.unlock_door()
                        else:
                            print("[INFO] Unknown face!")
                            door.sounds["wait"].play()
                    except Exception as e:
                        print(f"[ERROR] Face recognition error: {e}")
                else:
                    print("[WARN] Recognizer not available.")
            time.sleep(0.1)
    except Exception as e:
        print(f"[ERROR] Main loop error: {e}")
    finally:
        door.cleanup()


if __name__ == "__main__":
    main()

