import time
import signal
import threading
import smbus
import RPi.GPIO as GPIO
from lcd import LCD

# --- Configuration -----------------------------------------------------------
I2C_BUS = 1
LCD_ADDR = 0x27
LED_PINS = [17, 18, 23, 27, 22]
UPDATE_INTERVAL = 1.0

# --- Globals -----------------------------------------------------------------
lcd = None
bus = None
running = True


def init_i2c():
    """Initialize the I2C bus; return the bus handle or None on failure."""
    try:
        return smbus.SMBus(I2C_BUS)
    except FileNotFoundError:
        print("Error: I2C bus 1 not found. Enable I2C with 'sudo raspi-config'.")
    except PermissionError:
        print("Error: Permission denied on I2C bus. Run as root or add user to 'i2c' group.")
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
    return None


def init_lcd(bus_handle):
    """Initialize the 16x2 LCD; return the LCD object or None on failure."""
    try:
        return LCD(bus_handle, LCD_ADDR)
    except Exception as e:
        print(f"Error initializing LCD at 0x{LCD_ADDR:02X}: {e}")
    return None


def init_gpio():
    """Configure GPIO pins for LED outputs; return True on success."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        for pin in LED_PINS:
            GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
        return True
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        return False


def activate_led(cls):
    """Turn on the LED corresponding to class index cls (0-4)."""
    if 0 <= cls < len(LED_PINS):
        GPIO.output(LED_PINS[cls], GPIO.HIGH)


def deactivate_led(cls):
    """Turn off the LED corresponding to class index cls (0-4)."""
    if 0 <= cls < len(LED_PINS):
        GPIO.output(LED_PINS[cls], GPIO.LOW)


def get_cpu_usage():
    """Read CPU usage from /proc/stat; return float percent or None on error."""
    try:
        with open('/proc/stat', 'r') as f:
            line = f.readline()
        parts = line.split()
        if len(parts) < 5:
            return None
        user, nice, system, idle, iowait = int(parts[1]), int(parts[2]), int(parts[3]), int(parts[4]), int(parts[5])
        total = user + nice + system + idle + iowait
        if total == 0:
            return 0.0
        return (system + user + nice) / total * 100.0
    except (IOError, ValueError) as e:
        print(f"Error reading CPU usage: {e}")
        return None


def get_cpu_temp():
    """Read CPU temperature from /sys/class/thermal/thermal_zone0/temp;
    return float Celsius or None on error."""
    try:
        with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
            return float(f.read().strip()) / 1000.0
    except (IOError, ValueError) as e:
        print(f"Error reading CPU temperature: {e}")
        return None


def update_lcd(cpu_usage, cpu_temp):
    """Update the LCD with CPU usage and temperature; return True on success."""
    if lcd is None:
        return False
    try:
        lcd.clear()
        lcd.write_string(f"CPU: {cpu_usage:5.1f}%  Temp: {cpu_temp:4.1f}C")
        return True
    except Exception as e:
        print(f"Error updating LCD: {e}")
        return False


def update_loop(cls):
    """Background thread: update LCD every UPDATE_INTERVAL while LED is active."""
    while running:
        cpu_usage = get_cpu_usage()
        cpu_temp = get_cpu_temp()
        if cpu_usage is not None and cpu_temp is not None:
            update_lcd(cpu_usage, cpu_temp)
        activate_led(cls)
        time.sleep(UPDATE_INTERVAL)
        deactivate_led(cls)


def cleanup():
    """Release all resources: clear LCD, turn off backlight, release GPIO."""
    global lcd, bus
    if lcd is not None:
        try:
            lcd.clear()
            lcd.backlight_off()
        except Exception:
            pass
    if bus is not None:
        try:
            bus.close()
        except Exception:
            pass
    GPIO.cleanup()


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    running = False


def main():
    global lcd, bus, running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    bus = init_i2c()
    if bus is None:
        return

    lcd = init_lcd(bus)
    if lcd is None:
        cleanup()
        return

    if not init_gpio():
        cleanup()
        return

    threads = []
    for cls in range(5):
        t = threading.Thread(target=update_loop, args=(cls,), daemon=True)
        t.start()
        threads.append(t)

    try:
        while running:
            time.sleep(0.5)
    except KeyboardInterrupt:
        running = False
    finally:
        running = False
        for t in threads:
            t.join(timeout=2.0)
        cleanup()


if __name__ == "__main__":
    main()

