        if cpu_usage is not None and cpu_temp is not None:
            update_lcd(cpu_usage, cpu_temp)
        activate_led(cls)
        time.sleep(UPDATE_INTERVAL)
        deactivate_led(cls)


def cleanup():
    """Release all resources: clear LCD, turn off backlight, release GPIO."""
    global lcd, bus
    if lcd is not None:
        try:
            lcd.clear()
            lcd.backlight_off()
        except Exception:
            pass
    if bus is not None:
        try:
            bus.close()
        except Exception:
            pass
    GPIO.cleanup()


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    running = False


def main():
    global lcd, bus, running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    bus = init_i2c()
    if bus is None:
        return

    lcd = init_lcd(bus)
    if lcd is None:
        cleanup()
        return

    if not init_gpio():
        cleanup()
        return

    threads = []
    for cls in range(5):
        t = threading.Thread(target=update_loop, args=(cls,), daemon=True)
        t.start()
        threads.append(t)

    try:
        while running:
            time.sleep(0.5)
    except KeyboardInterrupt:
        running = False
    finally:
        running = False
        for t in threads:
            t.join(timeout=2.0)
        cleanup()


if __name__ == "__main__":
    main()

