import signal
import sys
import time
import RPi.GPIO as GPIO

TRIG_PIN = 17
ECHO_PIN = 18
MIN_DISTANCE_CM = 2.0
MAX_DISTANCE_CM = 400.0
TANK_HEIGHT_CM = 50.0
SAMPLE_INTERVAL_S = 2.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(TRIG_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(ECHO_PIN, GPIO.IN)
    time.sleep(0.2)

def measure_distance():
    GPIO.output(TRIG_PIN, GPIO.HIGH)
    time.sleep(0.00001)
    GPIO.output(TRIG_PIN, GPIO.LOW)

    deadline = time.time() + 0.03
    while GPIO.input(ECHO_PIN) == GPIO.LOW:
        if time.time() > deadline:
            return None
    pulse_start = time.time()

    deadline = time.time() + 0.03
    while GPIO.input(ECHO_PIN) == GPIO.HIGH:
        if time.time() > deadline:
            return None
    pulse_end = time.time()

    pulse_duration = pulse_end - pulse_start
    distance = pulse_duration * 17150.0
    return distance

def calculate_water_level(distance_cm):
    if distance_cm is None:
        return None
    water_level = TANK_HEIGHT_CM - distance_cm
    return max(0.0, min(water_level, TANK_HEIGHT_CM))

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        setup_gpio()
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                distance = measure_distance()
            except Exception as e:
                print(f"I/O error during measurement: {e}", file=sys.stderr)
                time.sleep(SAMPLE_INTERVAL_S)
