            if distance is None:
                print("Error: ECHO pulse timed out (sensor not responding).", file=sys.stderr)
            elif distance < MIN_DISTANCE_CM or distance > MAX_DISTANCE_CM:
                print(f"Error: Distance {distance:.2f} cm out of valid range.", file=sys.stderr)
            else:
                water_level = calculate_water_level(distance)
                print(f"Distance: {distance:.2f} cm, Water Level: {water_level:.2f} cm")

            time.sleep(SAMPLE_INTERVAL_S)
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    main()

