import signal
import sys
import time

import smbus2

I2C_BUS = 1
PCF8574_ADDR = 0x20
POLL_INTERVAL = 0.1
RETRY_DELAY = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def read_sensor(bus, sensor_index):
    """Read a single active-low proximity sensor via the PCF8574 port expander.

    Returns True if the pin is LOW (obstacle detected), False if HIGH (no obstacle).
    Raises OSError on bus errors.
    """
    port = bus.read_byte(PCF8574_ADDR)
    return not bool(port & (1 << sensor_index))


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = smbus2.SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            for i in range(8):
                try:
                    if read_sensor(bus, i):
                        print(f"Obstacle detected by sensor {i}")
                except OSError as exc:
                    print(f"Error reading sensor {i}: {exc}", file=sys.stderr)
                    time.sleep(RETRY_DELAY)
                    break
            time.sleep(POLL_INTERVAL)
    finally:
        bus.close()
        print("I2C bus closed. Exiting.")


if __name__ == "__main__":
    main()

