#!/usr/bin/env python3
"""
Clean Energy Monitoring System (Simulated)

Simulates light and temperature sensors on GPIO17 (light) and GPIO4 (temp)
and reads the Raspberry Pi internal temperature via vcgencmd.
Logs data every 5 seconds with timestamps and warns on low light, high temp,
and high Pi temp.
"""

import time
import datetime
import subprocess
import random
import sys
import signal

# Constants
LOW_LIGHT_THRESHOLD = 300
HIGH_TEMP_THRESHOLD = 35
HIGH_PI_TEMP_THRESHOLD = 75
LIGHT_SENSOR_PIN = 17
TEMP_SENSOR_PIN = 4

# Global flag for graceful shutdown
_running = True


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False


def simulate_light_sensor(hour):
    """Simulate light sensor reading in lux.

    Daylight (6-18) yields 600-1000 lux, nighttime (18-6) yields 100-300 lux.
    """
    if 6 <= hour < 18:
        return random.randint(600, 1000)
    return random.randint(100, 300)


def simulate_temperature_sensor():
    """Simulate temperature sensor reading in °C."""
    return random.randint(20, 30)


def simulate_pi_temperature():
    """Read Raspberry Pi temperature via vcgencmd.

    Returns temperature in °C, or None on error.
    """
    try:
        result = subprocess.run(
            ["vcgencmd", "measure_temp"],
            capture_output=True,
            text=True,
            timeout=5,
            check=True,
        )
        # Output looks like: temp=48.3'C
        temp_str = result.stdout.strip()
        # Extract numeric value
        value = float(temp_str.split("=")[1].split("'")[0])
        return value
    except (subprocess.CalledProcessError, subprocess.TimeoutExpired,
            IndexError, ValueError, FileNotFoundError) as e:
        print(f"Warning: Failed to read Pi temperature: {e}", file=sys.stderr)
        return None


def calculate_voltage(light_level):
    """Calculate voltage based on light level."""
    if light_level > 300:
        return random.uniform(11.5, 12.5)
    return random.uniform(10.0, 11.0)


def calculate_current(light_level):
    """Calculate current based on light level."""
    if light_level > 300:
        return random.uniform(1.5, 2.5)
    return random.uniform(0.5, 1.0)


def log_data(light, temperature, voltage, current, pi_temperature):
    """Log sensor data with timestamp."""
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    print(
        f"{timestamp} - Light: {light} lux, Temperature: {temperature}°C, "
        f"Voltage: {voltage:.2f}V, Current: {current:.2f}A, "
        f"Pi Temperature: {pi_temperature if pi_temperature is not None else 'N/A'}°C"
    )


def setup_signal_handlers():
    """Register signal handlers for graceful shutdown."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)


def main():
    """Main loop: simulate sensors, log data, warn on thresholds."""
    setup_signal_handlers()

    try:
        while _running:
            now = datetime.datetime.now()
            hour = now.hour
            light = simulate_light_sensor(hour)
            temperature = simulate_temperature_sensor()
            voltage = calculate_voltage(light)
            current = calculate_current(light)
            pi_temperature = simulate_pi_temperature()

            log_data(light, temperature, voltage, current, pi_temperature)

            # Warnings
            if light < LOW_LIGHT_THRESHOLD:
                print(f"Warning: Low light level ({light} lux) detected!")
            if temperature > HIGH_TEMP_THRESHOLD:
                print(f"Warning: High temperature ({temperature}°C) detected!")
            if pi_temperature is not None and pi_temperature > HIGH_PI_TEMP_THRESHOLD:
                print(f"Warning: High Pi temperature ({pi_temperature}°C) detected!")

            # Sleep in small increments to allow responsive shutdown
            for _ in range(50):
                if not _running:
                    break
                time.sleep(0.1)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        print("Program terminated gracefully.")


if __name__ == "__main__":
    main()

