import json
import random
import time
import threading
import paho.mqtt.client as mqtt

BROKER = "test.mosquitto.org"
PORT = 1883
TOPIC = "classroom/temperature"
KEEPALIVE = 60
READINGS = 5
RETRY_DELAY = 2
MAX_RETRIES = 3


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        print("Connected to MQTT Broker!")
    else:
        print(f"Failed to connect, return code {reason_code}")


def on_publish(client, userdata, mid, reason_code, properties):
    if reason_code == 0:
        print(f"Message {mid} published successfully")
    else:
        print(f"Failed to publish message {mid}, return code {reason_code}")


def generate_reading():
    return {
        "temperature": round(random.uniform(19.00, 26.00), 2),
        "index": random.randint(1, 100),
    }


def publish_reading(client, index):
    payload = generate_reading()
    payload["index"] = index
    json_payload = json.dumps(payload)
    result = client.publish(TOPIC, json_payload, qos=1)
    if result.rc != mqtt.MQTT_ERR_SUCCESS:
        print(f"Publish failed for index {index} with code {result.rc}")
        return False
    result.wait_for_publish(timeout=5)
    return True


