ERROR_FILE = os.path.join(DATA_DIR, "error.log")
CSV_HEADER = ["Timestamp", "Temperature_C"]

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def ensure_dir(path):
    try:
        os.makedirs(path, exist_ok=True)
    except OSError as exc:
        log_error(f"Failed to create directory {path}: {exc}")
        raise


def log_error(message):
    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    try:
        with open(ERROR_FILE, "a", encoding="utf-8") as fh:
            fh.write(f"{ts} - {message}\n")
    except OSError as exc:
        print(f"Error writing to {ERROR_FILE}: {exc}", file=sys.stderr)


def log_data(temperature):
    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    try:
        with open(DATA_FILE, "a", newline="", encoding="utf-8") as fh:
            writer = csv.writer(fh)
            writer.writerow([ts, f"{temperature:.2f}"])
    except OSError as exc:
        log_error(f"Error writing to {DATA_FILE}: {exc}")


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    ensure_dir(DATA_DIR)

    try:
        sensor = adafruit_dht.DHT22(board.D4, use_pulseio=False)
    except Exception as exc:
        log_error(f"Failed to initialize DHT22 on GPIO4: {exc}")
        sys.exit(1)

    try:
        with open(DATA_FILE, "w", newline="", encoding="utf-8") as fh:
            csv.writer(fh).writerow(CSV_HEADER)
    except OSError as exc:
        log_error(f"Error initializing CSV file: {exc}")
        sys.exit(1)

    try:
        while _running:
            try:
                temperature = sensor.temperature
                if temperature is None:
                    raise RuntimeError("Sensor returned None")
                log_data(temperature)
                print(f"Temperature: {temperature:.2f} C")
            except RuntimeError as exc:
                log_error(f"DHT22 read error: {exc}")
            except Exception as exc:
                log_error(f"Unexpected error: {exc}")

            for _ in range(60):
                if not _running:
                    break
                time.sleep(1)
    finally:
        try:
            sensor.exit()
        except Exception:
            pass


if __name__ == "__main__":
    main()

