import time
import logging
import signal
import sys

try:
    import smbus2 as smbus
except ImportError:
    import smbus

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class DHT20:
    """Driver for the DHT20 temperature/humidity sensor over I2C."""

    # DHT20 constants
    I2C_ADDRESS = 0x5B
    I2C_BUS = 1
    POWER_UP_DELAY = 0.5
    READ_INTERVAL = 0.01
    MAX_RETRIES = 5
    RETRY_DELAY = 2.0
    TIMEOUT = 0.1
    STATUS_REG = 0x71
    STATUS_MASK = 0x80
    DATA_REG = 0x71
    DATA_LEN = 7
    CRC_POLYNOMIAL = 0x31
    CRC_INIT = 0xFF

    def __init__(self, bus_num=I2C_BUS, address=I2C_ADDRESS):
        self.address = address
        self.bus = None
        self._closed = False
        try:
            self.bus = smbus.SMBus(bus_num)
            logging.info(f"I2C bus {bus_num} opened successfully.")
        except Exception as e:
            logging.error(f"Failed to open I2C bus {bus_num}: {e}")
            raise

        # Wait for sensor to power up
        time.sleep(self.POWER_UP_DELAY)

        # Verify sensor presence by reading the status register
        try:
            status = self._read_register(self.STATUS_REG, 1)[0]
            if (status & self.STATUS_MASK) != self.STATUS_MASK:
                logging.error(f"DHT20 status register check failed: 0x{status:02X}")
                self.close()
                raise RuntimeError("DHT20 not detected or not ready")
            logging.info("DHT20 detected and ready.")
        except Exception as e:
            logging.error(f"Error during DHT20 initialization: {e}")
            self.close()
            raise

    def _read_register(self, register, length):
        """Reads data from the specified register."""
        if self.bus is None:
            raise RuntimeError("I2C bus is not initialized.")
        try:
            return self.bus.read_i2c_block_data(self.address, register, length)
        except Exception as e:
            logging.error(f"Error reading from register 0x{register:02X}: {e}")
            raise

    def _calculate_crc(self, data):
        """Calculates CRC-8 checksum."""
        crc = self.CRC_INIT
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ self.CRC_POLYNOMIAL) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def _read_data(self):
        """Reads raw data from the sensor."""
        data = self._read_register(self.DATA_REG, self.DATA_LEN)
        if len(data) != self.DATA_LEN:
            raise RuntimeError(f"Expected {self.DATA_LEN} bytes, got {len(data)}")
        return data

    def _convert_data(self, data):
        """Converts raw data to temperature and humidity."""
        crc_error = False
        crc = self._calculate_crc(data[:self.DATA_LEN - 1])
        if crc != data[self.DATA_LEN - 1]:
            logging.warning(f"CRC mismatch: calculated 0x{crc:02X}, received 0x{data[self.DATA_LEN - 1]:02X}")
            crc_error = True

        # Humidity: bytes 1-3, 20-bit
        humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
        humidity = (humidity_raw / 0x100000) * 100.0

        # Temperature: bytes 3-5, 20-bit, shared nibble with humidity
        temp_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF
        temperature = (temp_raw / 0x100000) * 200.0 - 50.0

        return temperature, humidity, crc_error

    def read(self):
        """Reads temperature and humidity with retries."""
        if self.bus is None:
            logging.error("I2C bus is not initialized.")
            return None, None, True

        for attempt in range(self.MAX_RETRIES):
            try:
                # Wait for sensor to be ready
                status = self._read_register(self.STATUS_REG, 1)[0]
                if (status & self.STATUS_MASK) == self.STATUS_MASK:
                    time.sleep(self.READ_INTERVAL)
                else:
                    break

                # Poll status until bit 7 clears or timeout
                start_time = time.time()
                while (status & self.STATUS_MASK) == self.STATUS_MASK:
                    if time.time() - start_time > self.TIMEOUT:
                        raise TimeoutError("Timeout waiting for sensor to be ready")
                    time.sleep(self.READ_INTERVAL)
                    status = self._read_register(self.STATUS_REG, 1)[0]

                data = self._read_data()
                temperature, humidity, crc_error = self._convert_data(data)

                if crc_error:
                    logging.warning(f"CRC error on attempt {attempt + 1}.")
                    if attempt < self.MAX_RETRIES - 1:
                        time.sleep(self.RETRY_DELAY)
                    continue

                return temperature, humidity, crc_error

            except Exception as e:
                logging.error(f"Error reading DHT20 on attempt {attempt + 1}: {e}")
                if attempt < self.MAX_RETRIES - 1:
                    time.sleep(self.RETRY_DELAY)

        logging.error("Failed to read DHT20 after multiple retries.")
        return None, None, True

    def close(self):
        """Closes the I2C bus connection."""
        if self.bus is not None and not self._closed:
            try:
                self.bus.close()
                self._closed = True
                logging.info("I2C bus closed.")
            except Exception as e:
                logging.error(f"Error closing I2C bus: {e}")

    def __del__(self):
        self.close()


def main():
    sensor = None
    def signal_handler(sig, frame):
        logging.info("Exiting program.")
        if sensor:
            sensor.close()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        sensor = DHT20()
        temperature, humidity, crc_error = sensor.read()
        if crc_error:
            logging.error("CRC error detected.")
        else:
            print(f"Temperature: {temperature:.2f} °C")
            print(f"Humidity: {humidity:.2f} %")
    except Exception as e:
        logging.error(f"Fatal error: {e}")
    finally:
        if sensor:
            sensor.close()


if __name__ == "__main__":
    main()

