import asyncio
import json
import logging
import logging.handlers
import signal
import sys
from typing import Dict, List, Tuple, Optional

import gpiozero

DEFAULT_CONFIG = {
    "gpio_transmitter_pin": 17,
    "gpio_dht22_pin": 4,
    "dht22_read_interval": 300,
    "log_file": "greenhouse.log",
    "outlet_configurations": [
        {"name": "outlet1", "system_code": "10101", "unit_code": "1"},
        {"name": "outlet2", "system_code": "10101", "unit_code": "2"},
        {"name": "outlet3", "system_code": "10101", "unit_code": "3"},
    ],
}


class GreenhouseController:
    def __init__(self, config_file: str = "greenhouse_config.json"):
        self.config_file = config_file
        self.config = self._load_config()
        self.outlets: Dict[str, gpiozero.OutputDevice] = {}
        self.dht22: Optional[gpiozero.DHT22] = None
        self.running = True
        self.logger = logging.getLogger(__name__)
        self._setup_logging()
        self._setup_gpio()

    def _setup_logging(self) -> None:
        log_file = self.config.get("log_file", DEFAULT_CONFIG["log_file"])
        handler = logging.handlers.RotatingFileHandler(
            log_file, maxBytes=1024 * 1024, backupCount=5
        )
        formatter = logging.Formatter(
            "%(asctime)s - %(levelname)s - %(message)s"
        )
        handler.setFormatter(formatter)
        self.logger.addHandler(handler)
        self.logger.setLevel(logging.INFO)

    def _setup_gpio(self) -> None:
        tx_pin = self.config.get("gpio_transmitter_pin", DEFAULT_CONFIG["gpio_transmitter_pin"])
        dht_pin = self.config.get("gpio_dht22_pin", DEFAULT_CONFIG["gpio_dht22_pin"])
        try:
            self.dht22 = gpiozero.DHT22(dht_pin)
            self.logger.info(f"DHT22 initialized on GPIO{dht_pin}")
        except Exception as e:
            self.logger.error(f"Failed to initialize DHT22 on GPIO{dht_pin}: {e}")
            self.dht22 = None
        try:
            self.outlets = {
                cfg["name"]: gpiozero.OutputDevice(tx_pin)
                for cfg in self.config.get("outlet_configurations", [])
            }
            self.logger.info(f"Outlets initialized on GPIO{tx_pin}")
        except Exception as e:
            self.logger.error(f"Failed to initialize outlets on GPIO{tx_pin}: {e}")
            self.outlets = {}

    def _load_config(self) -> Dict:
        try:
            with open(self.config_file, "r") as f:
                cfg = json.load(f)
            if not isinstance(cfg, dict):
                self.logger.error("Config file is not a JSON object.")
                return DEFAULT_CONFIG
            return cfg
        except FileNotFoundError:
            self.logger.warning(f"Config file {self.config_file} not found. Using defaults.")
            return DEFAULT_CONFIG
        except json.JSONDecodeError as e:
