import smbus
import time
import logging
import signal
import sys

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
logger = logging.getLogger(__name__)

DHT20_I2C_ADDR = 0x5A
DHT20_STATUS_REG = 0x77
DHT20_MEASURE_REG = 0xAC
DHT20_STATUS_BUSY = 0x80
DHT20_STATUS_READY = 0x40
DHT20_MEASURE_TIMEOUT = 0.1
DHT20_POLL_INTERVAL = 0.01


class DHT20:
    def __init__(self, bus_id=1):
        self.bus = None
        self.address = DHT20_I2C_ADDR
        try:
            self.bus = smbus.SMBus(bus_id)
        except OSError as e:
            logger.error("Failed to open I2C bus %d: %s", bus_id, e)
            self.bus = None
            return

        if not self._verify_sensor():
            logger.error("DHT20 sensor not found at address 0x%02X", self.address)
            self._close_bus()
            self.bus = None

    def _verify_sensor(self):
        if self.bus is None:
            return False
        try:
            status = self.bus.read_byte_data(self.address, DHT20_STATUS_REG)
            if status != (DHT20_STATUS_BUSY | DHT20_STATUS_READY):
                logger.debug("Status register = 0x%02X", status)
                return False
            return True
        except OSError as e:
            logger.debug("Verify read failed: %s", e)
            return False

    def _close_bus(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except OSError:
                pass
            self.bus = None

    def measure(self):
        if self.bus is None:
            logger.error("I2C bus not initialized")
            return None, None, True

        try:
            self.bus.write_byte(self.address, DHT20_MEASURE_REG)
        except OSError as e:
            logger.error("Failed to write measure command: %s", e)
            return None, None, True

        deadline = time.monotonic() + DHT20_MEASURE_TIMEOUT
        while time.monotonic() < deadline:
            try:
                status = self.bus.read_byte_data(self.address, DHT20_STATUS_REG)
            except OSError as e:
                logger.error("Failed to read status: %s", e)
                return None, None, True
            if status & DHT20_STATUS_READY:
                break
            time.sleep(DHT20_POLL_INTERVAL)
        else:
            logger.error("Measurement timed out")
            return None, None, True

        try:
            data = self.bus.read_i2c_block_data(self.address, 0x00, 7)
        except OSError as e:
            logger.error("Failed to read measurement data: %s", e)
            return None, None, True

        if len(data) < 7:
            logger.error("Short read: expected 7 bytes, got %d", len(data))
            return None, None, True

        crc_poly = 0x31
        crc = 0xFF
        for byte in data[:6]:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ crc_poly) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        if crc != data[6]:
            logger.error("CRC mismatch: computed 0x%02X, received 0x%02X", crc, data[6])
            return None, None, True

        humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
        temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF

        humidity = humidity_raw * 100.0 / (1 << 20)
        temperature = temperature_raw * 200.0 / (1 << 20) - 50.0
        return temperature, humidity, False

    def close(self):
        self._close_bus()


_sensor = None


def _signal_handler(signum, frame):
    logger.info("Signal %d received, shutting down", signum)
    if _sensor is not None:
        _sensor.close()
    sys.exit(0)


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _sensor = DHT20(bus_id=1)
    if _sensor.bus is None:
        sys.exit(1)

    try:
        temp, hum, err = _sensor.measure()
        if err:
            logger.error("Measurement failed")
        else:
            logger.info("Temperature: %.2f C  Humidity: %.2f %%", temp, hum)
    finally:
        _sensor.close()

