import RPi.GPIO as GPIO
import time
import datetime
import signal
import sys
import board
import adafruit_dht

# Constants
VENT_PIN = 17
LIMIT_SWITCH_PINS = [5, 6, 12, 13, 16, 20, 21, 26]
DHT22_PINS = [4, 23]
ACTUATION_DURATION = 5
POLL_INTERVAL = 60
MAX_TEMP = 30
MIN_HUMIDITY = 60
HYSTERESIS = 2

# Global state
last_temp = None
last_humidity = None
running = True

def log_message(message):
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    try:
        with open("greenhouse.log", "a") as f:
            f.write(f"{timestamp} - {message}\n")
    except Exception as e:
        print(f"Error writing to log file: {e}")

def signal_handler(sig, frame):
    global running
    running = False
    log_message(f"Received signal {sig}, shutting down gracefully...")

def setup_gpio():
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(VENT_PIN, GPIO.OUT, initial=GPIO.LOW)
        for pin in LIMIT_SWITCH_PINS:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        for pin in DHT22_PINS:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        log_message("GPIO setup complete.")
    except Exception as e:
        log_message(f"GPIO setup failed: {e}")
        raise

def read_dht22(pin):
    try:
        dht_device = adafruit_dht.DHT22(getattr(board, f"D{pin}"))
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        dht_device.exit()
        if temperature is not None and humidity is not None:
            return temperature, humidity
        else:
            return None, None
    except Exception as e:
        log_message(f"DHT22 read error on pin {pin}: {e}")
        return None, None

def read_sensors():
    global last_temp, last_humidity
    for pin in DHT22_PINS:
        temp, hum = read_dht22(pin)
        if temp is not None and hum is not None:
            last_temp = temp
            last_humidity = hum
            log_message(f"Sensor reading: Temp={temp:.1f}C, Humidity={hum:.1f}%")
        else:
