import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# --- Configuration ---
I2C_SCL_PIN = board.SCL   # BCM 3
I2C_SDA_PIN = board.SDA   # BCM 2
MULTIPLEXER_ADDRESS = 0x70
BME280_ADDRESS = 0x77
TSL2591_ADDRESS = 0x29
READ_INTERVAL_SECONDS = 2


def initialize_i2c_bus():
    """Initialize the I2C bus on board.SCL / board.SDA."""
    try:
        i2c_bus = busio.I2C(I2C_SCL_PIN, I2C_SDA_PIN)
        # Force a brief delay for the bus to settle after power-up.
        time.sleep(0.1)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def initialize_multiplexer(i2c_bus):
    """Initialize the TCA9548A I2C multiplexer at address 0x70."""
    try:
        multiplexer = adafruit_tca9548a.TCA9548A(i2c_bus, address=MULTIPLEXER_ADDRESS)
        # Verify the multiplexer is present by reading its configuration register.
        _ = multiplexer.tcs[0]
        return multiplexer
    except ValueError as e:
        print(f"Error: TCA9548A not found at address 0x{MULTIPLEXER_ADDRESS:02X}: {e}")
        return None
    except Exception as e:
        print(f"Error initializing TCA9548A multiplexer: {e}")
        return None


def initialize_sensors(multiplexer):
    """Initialize the BME280 and TSL2591 sensors via the multiplexer."""
    bme280 = None
    tsl2591 = None

    try:
        bme280 = adafruit_bme280.Adafruit_BME280_I2C(multiplexer, address=BME280_ADDRESS)
        # Verify the BME280 is present by reading a register.
        _ = bme280.temperature
    except ValueError as e:
        print(f"Error: BME280 not found at address 0x{BME280_ADDRESS:02X}: {e}")
        bme280 = None
    except Exception as e:
        print(f"Error initializing BME280: {e}")
        bme280 = None

    try:
        tsl2591 = adafruit_tsl2591.TSL2591(multiplexer, address=TSL2591_ADDRESS)
        # Verify the TSL2591 is present by reading a register.
        _ = tsl2591.lux
    except ValueError as e:
        print(f"Error: TSL2591 not found at address 0x{TSL2591_ADDRESS:02X}: {e}")
        tsl2591 = None
    except Exception as e:
        print(f"Error initializing TSL2591: {e}")
        tsl2591 = None

    return bme280, tsl2591


def read_sensor_data(bme280, tsl2591):
    """Read temperature, humidity, and light intensity from sensors."""
    temperature = None
    humidity = None
    light_intensity = None

    if bme280 is not None:
        try:
            temperature = bme280.temperature
            humidity = bme280.humidity
        except Exception as e:
            print(f"Error reading BME280 data: {e}")
    else:
        print("BME280 sensor not initialized.")

    if tsl2591 is not None:
        try:
            light_intensity = tsl2591.lux
        except Exception as e:
            print(f"Error reading TSL2591 data: {e}")
    else:
        print("TSL2591 sensor not initialized.")

    return temperature, humidity, light_intensity


def print_sensor_data(temperature, humidity, light_intensity):
    """Print the sensor readings to the console."""
    print("--- Sensor Readings ---")
    if temperature is not None:
        print(f"Temperature: {temperature:.2f} °C")
    if humidity is not None:
        print(f"Humidity: {humidity:.2f} %")
    if light_intensity is not None:
        print(f"Light Intensity: {light_intensity:.2f} lux")
    print("--- ---")


def main():
    """Main function to read and print sensor data."""
    i2c_bus = initialize_i2c_bus()
    if i2c_bus is None:
        return

    multiplexer = initialize_multiplexer(i2c_bus)
    if multiplexer is None:
        return

    bme280, tsl2591 = initialize_sensors(multiplexer)

    try:
        while True:
            temperature, humidity, light_intensity = read_sensor_data(bme280, tsl2591)
            print_sensor_data(temperature, humidity, light_intensity)
            time.sleep(READ_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        print("Exiting program.")


if __name__ == "__main__":
    main()

