import argparse
import json
import socket
import signal
import sys
import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or be run on a Raspberry Pi.")
    sys.exit(1)

DEFAULT_RELAY_PIN = 17
DEFAULT_DHT_PIN = 4
DEFAULT_PORT = 12345
DEFAULT_ALLOWED_IP = "192.168.1.100"
DEFAULT_LOG_FILE = "hydroponics.log"


class HydroponicsController:
    def __init__(self, relay_pin, dht_pin, port, allowed_ip, log_file):
        self.relay_pin = relay_pin
        self.dht_pin = dht_pin
        self.port = port
        self.allowed_ip = allowed_ip
        self.log_file = log_file
        self.pump_state = False
        self.server_socket = None
        self.running = True

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.relay_pin, GPIO.OUT, initial=GPIO.LOW)
            print(f"Relay pin {self.relay_pin} initialized as output, default LOW.")
        except Exception as e:
            print(f"Error setting up relay pin {self.relay_pin}: {e}")
            sys.exit(1)

    def pump_on(self):
        try:
            GPIO.output(self.relay_pin, GPIO.HIGH)
            self.pump_state = True
            self.log_event("Pump turned ON")
        except Exception as e:
            self.log_event(f"Error turning pump ON: {e}")

    def pump_off(self):
        try:
            GPIO.output(self.relay_pin, GPIO.LOW)
            self.pump_state = False
            self.log_event("Pump turned OFF")
        except Exception as e:
            self.log_event(f"Error turning pump OFF: {e}")

    def get_temperature(self):
        return 25.0

    def get_status(self):
        return {
            "pump_state": "on" if self.pump_state else "off",
            "temperature": self.get_temperature(),
        }

    def log_event(self, message):
        timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
        try:
            with open(self.log_file, "a") as f:
                f.write(f"{timestamp} - {message}\n")
        except Exception as e:
            print(f"Error writing to log file: {e}")

    def handle_client(self, client_socket):
        try:
            data = client_socket.recv(1024).decode("utf-8")
            if not data:
                return
            command = json.loads(data)
            if not isinstance(command, dict):
                client_socket.sendall(b'{"error": "Invalid JSON format"}\n')
                return
            if "command" not in command:
                client_socket.sendall(b'{"error": "Missing command field"}\n')
                return
            if command["command"] == "pump_on":
                self.pump_on()
                client_socket.sendall(b'{"status": "Pump turned ON"}\n')
            elif command["command"] == "pump_off":
                self.pump_off()
                client_socket.sendall(b'{"status": "Pump turned OFF"}\n')
            elif command["command"] == "get_status":
                status = json.dumps(self.get_status())
                client_socket.sendall(f"{status}\n".encode("utf-8"))
            else:
                client_socket.sendall(b'{"error": "Invalid command"}\n')
        except json.JSONDecodeError:
            client_socket.sendall(b'{"error": "Invalid JSON format"}\n')
        except Exception as e:
            self.log_event(f"Error handling client: {e}")
            client_socket.sendall(b'{"error": "Internal server error"}\n')
        finally:
            client_socket.close()

    def start_server(self):
        try:
            self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            self.server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            self.server_socket.bind(("0.0.0.0", self.port))
            self.server_socket.listen(5)
            self.server_socket.settimeout(1.0)
            print(f"Listening on port {self.port}...")
            self.log_event(f"Server started on port {self.port}")
        except Exception as e:
            print(f"Error starting server: {e}")
            self.log_event(f"Server start failed: {e}")
            self.cleanup()
            sys.exit(1)

        while self.running:
            try:
                client_socket, address = self.server_socket.accept()
                client_ip = address[0]
                if client_ip != self.allowed_ip:
                    print(f"Connection from {client_ip} rejected (allowed: {self.allowed_ip})")
                    self.log_event(f"Connection from {client_ip} rejected")
                    client_socket.close()
                    continue
                print(f"Connection from {client_ip}")
                self.log_event(f"Connection from {client_ip} accepted")
                self.handle_client(client_socket)
            except socket.timeout:
                continue
            except Exception as e:
                print(f"Error accepting connection: {e}")
                self.log_event(f"Connection error: {e}")
                time.sleep(1)

    def cleanup(self):
        print("Cleaning up resources...")
        if self.server_socket:
            try:
                self.server_socket.close()
            except Exception:
                pass
        try:
            GPIO.output(self.relay_pin, GPIO.LOW)
            GPIO.cleanup()
        except Exception:
            pass
        self.log_event("Server stopped")

    def signal_handler(self, signum, frame):
        print(f"Signal {signum} received, shutting down...")
        self.running = False


def main():
    parser = argparse.ArgumentParser(description="Hydroponics Controller")
    parser.add_argument("--relay_pin", type=int, default=DEFAULT_RELAY_PIN, help="GPIO pin for relay (BCM)")
    parser.add_argument("--dht_pin", type=int, default=DEFAULT_DHT_PIN, help="GPIO pin for DHT11 (BCM)")
    parser.add_argument("--port", type=int, default=DEFAULT_PORT, help="TCP port for commands")
    parser.add_argument("--allowed_ip", type=str, default=DEFAULT_ALLOWED_IP, help="Allowed IP address")
    parser.add_argument("--log_file", type=str, default=DEFAULT_LOG_FILE, help="Path to log file")
    args = parser.parse_args()

    controller = HydroponicsController(args.relay_pin, args.dht_pin, args.port, args.allowed_ip, args.log_file)
    signal.signal(signal.SIGINT, controller.signal_handler)
    signal.signal(signal.SIGTERM, controller.signal_handler)

    try:
        controller.start_server()
    except KeyboardInterrupt:
        print("KeyboardInterrupt received, shutting down...")
    finally:
        controller.cleanup()


if __name__ == "__main__":
    main()

