import serial
import signal
import sys
import time
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

TEMP_MIN, TEMP_MAX = -40.0, 85.0
HUM_MIN, HUM_MAX = 0.0, 100.0
PRES_MIN, PRES_MAX = 800.0, 1200.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def validate_reading(line: str):
    parts = line.split(',')
    if len(parts) != 3:
        return None, None, None
    try:
        temperature = float(parts[0])
        humidity = float(parts[1])
        pressure = float(parts[2])
    except ValueError:
        return None, None, None
    if not (TEMP_MIN <= temperature <= TEMP_MAX):
        return None, None, None
    if not (HUM_MIN <= humidity <= HUM_MAX):
        return None, None, None
    if not (PRES_MIN <= pressure <= PRES_MAX):
        return None, None, None
    return temperature, humidity, pressure


def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f'Error opening serial port {SERIAL_PORT}: {exc}', file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f'Serial read error: {exc}', file=sys.stderr)
                break

            if not raw:
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            temperature, humidity, pressure = validate_reading(line)
            if temperature is None:
                print(f'Warning: malformed data (not CSV): {line!r}', file=sys.stderr)
                continue

            timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
            print(f'[{timestamp}] Temp: {temperature:.1f}C  Humidity: {humidity:.1f}%  Pressure: {pressure:.1f}hPa')

    finally:
        try:
            ser.close()
        except Exception:
            pass


if __name__ == '__main__':
    main()

