#!/usr/bin/env python3
"""
Raspberry Pi 4 Model B CPU Temperature Reader

Reads the on-board CPU temperature every 5 seconds and prints it.
Uses a lazily-created CPUTemperature object so that missing thermal files
(e.g., on a Pi without a thermal zone) do not crash the program.
"""

import time
import sys


class CPUTemperature:
    """Lazily-initialized CPU temperature reader."""

    def __init__(self):
        self._thermal_path = "/sys/class/thermal/thermal_zone0/temp"
        self._temp_c = None

    @property
    def temperature_c(self):
        """Return the current CPU temperature in Celsius."""
        if self._temp_c is None:
            self._temp_c = self._read_temperature()
        return self._temp_c

    def _read_temperature(self):
        """Read the raw temperature value from the thermal zone file."""
        with open(self._thermal_path, "r") as f:
            raw = f.read().strip()
        return float(raw) / 1000.0


def get_cpu_temperature(cpu):
    """
    Read the CPU temperature.

    Returns the temperature in Celsius, or None if the file is missing
    (e.g., on a Pi without thermal support).
    """
    try:
        return cpu.temperature_c
    except FileNotFoundError:
        print("Error: CPU temperature file not found. "
              "Check that thermal support is enabled on this board.")
        return None
    except Exception as e:
        print(f"Error reading CPU temperature: {e}")
        return None


def main():
    cpu = CPUTemperature()
    try:
        while True:
            temp = get_cpu_temperature(cpu)
            if temp is not None:
                print(f"CPU Temperature: {temp:.2f} °C")
            time.sleep(5)
    except KeyboardInterrupt:
        print("Program terminated")
        sys.exit(0)


if __name__ == "__main__":
    main()

