import serial
import time
import sys
import os

PORT = '/dev/ttyACM0'
BAUD = 115200
LOG_FILE = 'temperature_log.csv'


def celsius_to_fahrenheit(celsius):
    """Convert Celsius to Fahrenheit, returning None on invalid input."""
    try:
        return (celsius * 9.0 / 5.0) + 32.0
    except (TypeError, ValueError):
        return None


def log_temperature(celsius, fahrenheit, log_file):
    """Append a timestamped temperature reading to the CSV log file."""
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    line = f'{timestamp},{celsius},{fahrenheit}\n'
    try:
        with open(log_file, 'a', encoding='utf-8') as fh:
            fh.write(line)
    except OSError as exc:
        print(f'Error writing to log file: {exc}', file=sys.stderr)


def main():
    # Create the log file with a header if it does not already exist.
    if not os.path.exists(LOG_FILE):
        try:
            with open(LOG_FILE, 'w', encoding='utf-8') as fh:
                fh.write('Timestamp,Temperature_Celsius,Temperature_Fahrenheit\n')
        except OSError as exc:
            print(f'Error creating log file: {exc}', file=sys.stderr)
            sys.exit(1)

    # Open the UART port with explicit 8N1 settings.
    try:
        ser = serial.Serial(
            port=PORT,
            baudrate=BAUD,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=1.0,
        )
    except serial.SerialException as exc:
        print(f'Error opening serial port {PORT}: {exc}', file=sys.stderr)
        sys.exit(1)
    except OSError as exc:
        print(f'Error opening serial port {PORT}: {exc}', file=sys.stderr)
        sys.exit(1)

    print(f'Logging temperature to {LOG_FILE}. Press Ctrl+C to stop.')

    try:
        while True:
            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f'Serial read error: {exc}', file=sys.stderr)
                break

            if not raw:
                # Timeout elapsed with no data; loop and retry.
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            try:
                celsius = float(line)
            except ValueError:
                print(f'Warning: malformed data (not a number): {line!r}',
                      file=sys.stderr)
                continue

            fahrenheit = celsius_to_fahrenheit(celsius)
            if fahrenheit is None:
                print(f'Warning: could not convert {celsius} to Fahrenheit.',
                      file=sys.stderr)
                continue

            log_temperature(celsius, fahrenheit, LOG_FILE)
            print(f'Celsius: {celsius:.2f}°C  Fahrenheit: {fahrenheit:.2f}°F')

    except KeyboardInterrupt:
        print('\nProgram terminated by user.')
    finally:
        try:
            ser.close()
        except Exception:
            pass


if __name__ == '__main__':
    main()

