import time
import json
import random
import signal
import sys
import urllib.request
import urllib.error
from collections import deque

try:
    import board
    import adafruit_dht
except ImportError:
    print("Missing dependencies. Install with:")
    print("  pip install adafruit-circuitpython-dht")
    print("  sudo apt-get install libgpiod2")
    sys.exit(1)

CONFIG_FILE = "config.json"

running = True

def signal_handler(signum, frame):
    global running
    running = False

def load_config(path):
    try:
        with open(path, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"Error: Configuration file '{path}' not found.")
        return None
    except json.JSONDecodeError as e:
        print(f"Error: Invalid JSON in '{path}': {e}")
        return None

def validate_reading(temp, hum):
    if not (-40.0 <= temp <= 80.0):
        print(f"Warning: Temperature out of range: {temp}")
        return False
    if not (0.0 <= hum <= 100.0):
        print(f"Warning: Humidity out of range: {hum}")
        return False
    return True

def simulate_reading():
    temp = random.uniform(20.0, 30.0)
    hum = random.uniform(60.0, 80.0)
    return temp, hum

def send_webhook(url, data):
    try:
        req = urllib.request.Request(
            url,
            data=data.encode("utf-8"),
            method="POST",
            headers={"Content-Type": "application/json"},
        )
        with urllib.request.urlopen(req, timeout=10) as resp:
            if 200 <= resp.status < 300:
                print(f"Webhook sent successfully (HTTP {resp.status})")
                return True
            else:
                print(f"Webhook returned HTTP {resp.status}")
                return False
    except urllib.error.URLError as e:
        print(f"Webhook request failed: {e}")
        return False
    except Exception as e:
        print(f"Unexpected webhook error: {e}")
        return False

def main():
    global running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    config = load_config(CONFIG_FILE)
    if config is None:
        sys.exit(1)

    webhook_url = config.get("webhook_url")
    if not webhook_url:
        print("Error: 'webhook_url' is missing in config.json")
        sys.exit(1)

    dht_pin = config.get("dht_pin", 4)
    if dht_pin not in (4, 17, 18, 27, 22, 23, 24, 25):
        print(f"Error: Unsupported DHT22 pin: {dht_pin}")
        sys.exit(1)

    try:
        dht_device = adafruit_dht.DHT22(getattr(board, f"D{dht_pin}"))
    except Exception as e:
        print(f"Failed to initialize DHT22 on BCM pin {dht_pin}: {e}")
        sys.exit(1)

    temp_history = deque(maxlen=5)
    webhook_failures = 0
    pause_until = 0.0

    try:
        while running:
            now = time.monotonic()
            if pause_until > now:
                time.sleep(min(0.5, pause_until - now))
                continue

            try:
                temp = dht_device.temperature
                hum = dht_device.humidity
                if temp is None or hum is None:
                    raise RuntimeError("Sensor returned None")

                if not validate_reading(temp, hum):
                    print("Warning: Invalid reading, simulating...")
                    temp, hum = simulate_reading()

                temp_history.append(temp)
                avg_temp = sum(temp_history) / len(temp_history)

                data = {
                    "temperature": round(avg_temp, 2),
                    "humidity": round(hum, 2),
                    "timestamp": time.strftime("%Y-%m-%dT%H:%M:%S%z"),
                }
                payload = json.dumps(data).encode("utf-8")

                if send_webhook(webhook_url, payload):
                    webhook_failures = 0
                else:
                    webhook_failures += 1

                if webhook_failures >= 3:
                    print("Three consecutive webhook failures! Pausing for 300s.")
                    pause_until = time.monotonic() + 300.0
                    continue

            except RuntimeError as e:
                print(f"Sensor read error: {e}")
                print("Simulating...")
                temp, hum = simulate_reading()
                temp_history.append(temp)
                avg_temp = sum(temp_history) / len(temp_history)

                data = {
                    "temperature": round(avg_temp, 2),
                    "humidity": round(hum, 2),
                    "timestamp": time.strftime("%Y-%m-%dT%H:%M:%S%z"),
                }
                payload = json.dumps(data).encode("utf-8")

                if send_webhook(webhook_url, payload):
                    webhook_failures = 0
                else:
                    webhook_failures += 1

                if webhook_failures >= 3:
                    print("Three consecutive webhook failures! Pausing for 300s.")
                    pause_until = time.monotonic() + 300.0
                    continue

            except Exception as e:
                print(f"Unexpected error: {e}")
                print("Simulating...")
                temp, hum = simulate_reading()
                temp_history.append(temp)
                avg_temp = sum(temp_history) / len(temp_history)

                data = {
                    "temperature": round(avg_temp, 2),
                    "humidity": round(hum, 2),
                    "timestamp": time.strftime("%Y-%m-%dT%H:%M:%S%z"),
                }
                payload = json.dumps(data).encode("utf-8")

                if send_webhook(webhook_url, payload):
                    webhook_failures = 0
                else:
                    webhook_failures += 1

                if webhook_failures >= 3:
                    print("Three consecutive webhook failures! Pausing for 300s.")
                    pause_until = time.monotonic() + 300.0
                    continue

            time.sleep(60)

    finally:
        try:
            dht_device.exit()
        except Exception:
            pass
        print("Program terminated.")

if __name__ == "__main__":
    main()

