import signal
import sys
import threading
import time
import logging
import numpy as np
import matplotlib
matplotlib.use('TkAgg')
import matplotlib.pyplot as plt
import matplotlib.animation as animation
from matplotlib import cm

try:
    from smbus2 import SMBus
except ImportError:
    SMBus = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class ThermalSensorReader:
    """Reads thermal data from a UART thermal sensor via smbus2."""

    def __init__(self, port='/dev/ttyS0', baudrate=9600, timeout=1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.bus = None
        self._open()

    def _open(self):
        if SMBus is None:
            raise RuntimeError('smbus2 library not installed')
        try:
            self.bus = SMBus(self.port)
            logging.info(f'UART sensor opened on {self.port}')
        except Exception as e:
            logging.error(f'Failed to open UART sensor: {e}')
            self.bus = None
            raise

    def read_frame(self):
        if self.bus is None:
            raise RuntimeError('Sensor not initialized')
        try:
            data = self.bus.read_i2c_block_data(0x00, 0x00, 768)
            return np.array(data, dtype=np.int16).reshape((24, 32))
        except Exception as e:
            logging.error(f'Error reading sensor data: {e}')
            return None

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except Exception:
                pass
            self.bus = None


class ThermalImageProcessor:
    """Processes thermal data and updates the heatmap."""

    def __init__(self, sensor_reader, frame_queue):
        self.sensor_reader = sensor_reader
        self.frame_queue = frame_queue
        self.fig, self.ax = plt.subplots()
        self.im = self.ax.imshow(np.zeros((24, 32)), cmap=cm.inferno, interpolation='nearest', vmin=0, vmax=100)
        self.cbar = self.fig.colorbar(self.im, ax=self.ax)
        self.cbar.set_label('Temperature (C)')
        self.ax.set_title('Thermal Camera Array')
        self.ax.set_xlabel('X Pixels')
        self.ax.set_ylabel('Y Pixels')
        self.fig.tight_layout()
        self.current_frame = np.zeros((24, 32), dtype=np.int16)
        self.animation_interval = 100
        self.animation_event = threading.Event()
        self.animation_thread = threading.Thread(target=self._animate, daemon=True)
        self.animation_thread.start()

    def _animate(self):
        while not self.animation_event.is_set():
            try:
                frame = self.frame_queue.get(timeout=self.animation_interval / 1000.0)
                self.current_frame = frame
            except Exception as e:
                logging.warning(f'Animation thread timeout: {e}')
                continue
            self.im.set_data(self.current_frame)
            self.im.set_clim(vmin=self.current_frame.min(), vmax=self.current_frame.max())
            self.fig.canvas.draw_idle()
            self.fig.canvas.flush_events()

    def start(self):
        self.animation_event.set()

    def stop(self):
        self.animation_event.clear()
        if self.animation_thread.is_alive():
            self.animation_thread.join(timeout=1.0)

    def close(self):
        self.stop()
        plt.close(self.fig)


def main():
    sensor_reader = None
    processor = None
    stop_event = threading.Event()

    def signal_handler(sig, frame):
        logging.info('Signal received, shutting down...')
        stop_event.set()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    frame_queue = threading.Queue(maxsize=1)

    def sensor_reading_thread():
        while not stop_event.is_set():
            try:
                frame = sensor_reader.read_frame()
                if frame is not None:
                    try:
                        frame_queue.put(frame, timeout=1.0)
                    except Exception as e:
                        logging.warning(f'Frame queue full: {e}')
            except Exception as e:
                logging.error(f'Error in sensor reading thread: {e}')
                stop_event.set()
                break
            time.sleep(0.01)

    try:
        sensor_reader = ThermalSensorReader()
        processor = ThermalImageProcessor(sensor_reader, frame_queue)
        processor.start()

        reading_thread = threading.Thread(target=sensor_reading_thread, daemon=True)
        reading_thread.start()

        while not stop_event.is_set():
            time.sleep(0.1)

    except Exception as e:
        logging.error(f'Fatal error: {e}')
    finally:
        stop_event.set()
        if processor:
            processor.close()
        if sensor_reader:
            sensor_reader.close()
        logging.info('Program finished.')


if __name__ == '__main__':
    main()

