import time
import signal
import sys
import adafruit_dht
from board import D22

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_dht22(sensor, retries=2, retry_delay=0.1):
    """
    Reads temperature and humidity from a DHT22 sensor with retries.

    Args:
        sensor: An initialised adafruit_dht.DHT22 object.
        retries (int): Number of read attempts before giving up.
        retry_delay (float): Delay in seconds between retries.

    Returns:
        tuple: (temperature, humidity) as floats, or (None, None) on failure.
    """
    for attempt in range(1, retries + 1):
        try:
            temperature = sensor.temperature
            humidity = sensor.humidity

            # Validate readings are within plausible ranges
            if temperature is not None and humidity is not None:
                if -40 <= temperature <= 80 and 0 <= humidity <= 100:
                    return temperature, humidity
                else:
                    print(f"Warning: Out-of-range reading (attempt {attempt}/{retries}): "
                          f"T={temperature}, H={humidity}")
            else:
                print(f"Warning: None reading (attempt {attempt}/{retries})")

        except RuntimeError as e:
            # Common DHT22 transient errors: checksum mismatch, timeout, etc.
            print(f"RuntimeError reading DHT22 (attempt {attempt}/{retries}): {e}")
        except Exception as e:
            # Catch-all for unexpected errors
            print(f"Unexpected error reading DHT22 (attempt {attempt}/{retries}): {e}")

        if attempt < retries:
            time.sleep(retry_delay)

    return None, None

def main():
    global _running

    # Register signal handler for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize the DHT22 sensor on BCM pin 22
    try:
        dht_device = adafruit_dht.DHT22(D22, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT22 sensor: {e}")
        sys.exit(1)

    # Allow sensor to stabilise
    time.sleep(1)

    try:
        while _running:
            temperature, humidity = read_dht22(dht_device)

            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
            else:
                print("Failed to read from DHT22 after retries.")

            # Sleep in small increments to allow prompt response to signals
            for _ in range(30):
                if not _running:
                    break
                time.sleep(0.1)

    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        # Clean resource release on all exit paths
        try:
            dht_device.exit()
        except Exception:
            pass
        print("Program terminated.")

if __name__ == "__main__":
    main()

