import time
import board
import busio
import adafruit_ahtx0

# Constants for temperature and humidity ranges
TEMP_MIN, TEMP_MAX = -40.0, 85.0
HUM_MIN, HUM_MAX = 0.0, 100.0


def init_sensor():
    """Initialize the I2C bus and AHT20 sensor with error handling."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - Failed to initialize I2C bus: {exc}")
        return None, None

    try:
        sensor = adafruit_ahtx0.AHTx0(i2c)
    except Exception as exc:
        print(f"{time.strftime('%Y-%m-%d %H:%M:%S')} - Failed to initialize AHT20 sensor: {exc}")
        try:
            i2c.deinit()
