import time
import datetime
import csv
import os
import fcntl
import random
import signal
import sys
import RPi.GPIO as GPIO

# Configuration
DHT22_PIN_1 = 17
DHT22_PIN_2 = 27
HIGH_HUMIDITY_THRESHOLD = 75.0
LOW_HUMIDITY_THRESHOLD = 45.0
HUMIDITY_ALERT_INTERVAL = 30 * 60  # 30 minutes in seconds
HUMIDITY_ALERT_READINGS = 3
TEMPERATURE_ALERT_INTERVAL = 30 * 60  # 30 minutes in seconds
TEMPERATURE_ALERT_READINGS = 3
READ_INTERVAL = 60  # 60 seconds
RETRY_DELAY = 2  # 2 seconds
MAX_RETRIES = 3

# Global state
last_high_humidity_alert_time = None
last_low_humidity_alert_time = None
last_high_temperature_alert_time = None
last_low_temperature_alert_time = None
running = True

def signal_handler(sig, frame):
    global running
    running = False

def log_error(message):
    try:
        with open("error.log", "a") as f:
            f.write(f"{datetime.datetime.now()} - ERROR: {message}\n")
    except Exception as e:
        print(f"Failed to log error: {e}")

def log_alert(message):
    try:
        with open("retail_alerts.log", "a") as f:
            f.write(f"{datetime.datetime.now()} - ALERT: {message}\n")
    except Exception as e:
        log_error(f"Failed to log alert: {e}")

def log_cloud(message):
    try:
        with open("cloud_log.log", "a") as f:
            f.write(f"{datetime.datetime.now()} - CLOUD: {message}\n")
    except Exception as e:
        log_error(f"Failed to log cloud log: {e}")

def simulate_cloud_push(data):
    if random.random() < 0.8:
        log_cloud(f"Simulated cloud push: {data}")
    else:
        log_cloud(f"Simulated cloud push failed: {data}")

def read_dht22(pin):
    """Reads temperature and humidity from a DHT22 sensor using a single-wire protocol."""
    # Send start signal
    GPIO.setup(pin, GPIO.OUT)
    GPIO.output(pin, GPIO.LOW)
    time.sleep(0.018)  # 18ms
    GPIO.output(pin, GPIO.HIGH)
    time.sleep(0.00004)  # 40us
    GPIO.setup(pin, GPIO.IN)

    # Wait for sensor response
    timeout = time.time() + 0.1
    while GPIO.input(pin) == GPIO.HIGH:
        if time.time() > timeout:
            return None, None

    timeout = time.time() + 0.1
    while GPIO.input(pin) == GPIO.LOW:
        if time.time() > timeout:
            return None, None

    timeout = time.time() + 0.1
    while GPIO.input(pin) == GPIO.HIGH:
        if time.time() > timeout:
            return None, None

    # Read 40 bits
    data = []
    for _ in range(40):
        timeout = time.time() + 0.1
        while GPIO.input(pin) == GPIO.LOW:
            if time.time() > timeout:
                return None, None
        start = time.time()
        timeout = time.time() + 0.1
        while GPIO.input(pin) == GPIO.HIGH:
            if time.time() > timeout:
                return None, None
        duration = time.time() - start
        data.append(1 if duration > 0.00005 else 0)

    # Convert to bytes
    humidity_raw = (data[0] << 7) | (data[1] << 6) | (data[2] << 5) | (data[3] << 4) | (data[4] << 3) | (data[5] << 2) | (data[6] << 1) | data[7]
    temperature_raw = ((data[8] << 7) | (data[9] << 6) | (data[10] << 5) | (data[11] << 4) | (data[12] << 3) | (data[13] << 2) | (data[14] << 1) | data[15])
    humidity_dec = (data[16] << 7) | (data[17] << 6) | (data[18] << 5) | (data[19] << 4) | (data[20] << 3) | (data[21] << 2) | (data[22] << 1) | data[23]
    temperature_dec = ((data[24] << 7) | (data[25] << 6) | (data[26] << 5) | (data[27] << 4) | (data[28] << 3) | (data[29] << 2) | (data[30] << 1) | data[31])

    humidity = humidity_raw + (humidity_dec / 10.0)
    temperature = temperature_raw + (temperature_dec / 10.0)

    if humidity > 100 or temperature > 55:
        return None, None

    return temperature, humidity

def validate_data(temperature, humidity):
    if temperature is None or humidity is None:
        return False
    if not (0 <= humidity <= 100):
        return False
    if not (-20 <= temperature <= 50):
        return False
    return True

def log_data(temperature1, humidity1, temperature2, humidity2):
    """Logs sensor data to a CSV file with file locking."""
    today = datetime.date.today()
    filename = f"retail_data_{today.year}-{today.month:02d}-{today.day:02d}.csv"
    file_exists = os.path.isfile(filename)

    try:
        with open(filename, "a") as f:
            fcntl.flock(f.fileno(), fcntl.LOCK_EX)
            writer = csv.writer(f)
            if not file_exists:
                writer.writerow(["Timestamp", "Sensor1_Temperature_C", "Sensor1_Humidity_%", "Sensor2_Temperature_C", "Sensor2_Humidity_%"])
            writer.writerow([datetime.datetime.now(), temperature1, humidity1, temperature2, humidity2])
            fcntl.flock(f.fileno(), fcntl.LOCK_UN)
    except Exception as e:
        log_error(f"Failed to log data: {e}")

def check_high_humidity(humidity, sensor_id):
    global last_high_humidity_alert_time
    if humidity is None:
        return
    if humidity > HIGH_HUMIDITY_THRESHOLD:
        now = datetime.datetime.now()
        if last_high_humidity_alert_time is None or (now - last_high_humidity_alert_time).total_seconds() > HUMIDITY_ALERT_INTERVAL:
            log_alert(f"High Humidity Alert: Sensor {sensor_id} - Humidity: {humidity:.2f}%")
            simulate_cloud_push(f"High Humidity Alert: Sensor {sensor_id} - Humidity: {humidity:.2f}%")
            last_high_humidity_alert_time = now

def check_low_humidity(humidity, sensor_id):
    global last_low_humidity_alert_time
    if humidity is None:
        return
    if humidity < LOW_HUMIDITY_THRESHOLD:
        now = datetime.datetime.now()
        if last_low_humidity_alert_time is None or (now - last_low_humidity_alert_time).total_seconds() > HUMIDITY_ALERT_INTERVAL:
            log_alert(f"Low Humidity Alert: Sensor {sensor_id} - Humidity: {humidity:.2f}%")
            simulate_cloud_push(f"Low Humidity Alert: Sensor {sensor_id} - Humidity: {humidity:.2f}%")
            last_low_humidity_alert_time = now

def check_high_temperature(temperature, sensor_id):
    global last_high_temperature_alert_time
    if temperature is None:
        return
    if temperature > 35:
        now = datetime.datetime.now()
        if last_high_temperature_alert_time is None or (now - last_high_temperature_alert_time).total_seconds() > TEMPERATURE_ALERT_INTERVAL:
            log_alert(f"High Temperature Alert: Sensor {sensor_id} - Temperature: {temperature:.2f}°C")
            simulate_cloud_push(f"High Temperature Alert: Sensor {sensor_id} - Temperature: {temperature:.2f}°C")
            last_high_temperature_alert_time = now

def check_low_temperature(temperature, sensor_id):
    global last_low_temperature_alert_time
    if temperature is None:
        return
    if temperature < 0:
        now = datetime.datetime.now()
        if last_low_temperature_alert_time is None or (now - last_low_temperature_alert_time).total_seconds() > TEMPERATURE_ALERT_INTERVAL:
            log_alert(f"Low Temperature Alert: Sensor {sensor_id} - Temperature: {temperature:.2f}°C")
            simulate_cloud_push(f"Low Temperature Alert: Sensor {sensor_id} - Temperature: {temperature:.2f}°C")
            last_low_temperature_alert_time = now

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)

    try:
        while running:
            temperature1, humidity1 = None, None
            temperature2, humidity2 = None, None

            for attempt in range(MAX_RETRIES):
                if not running:
                    break
                temperature1, humidity1 = read_dht22(DHT22_PIN_1)
                temperature2, humidity2 = read_dht22(DHT22_PIN_2)

                if validate_data(temperature1, humidity1):
                    check_high_humidity(humidity1, 1)
                    check_low_humidity(humidity1, 1)
                    check_high_temperature(temperature1, 1)
                    check_low_temperature(temperature1, 1)
                else:
                    log_error(f"Invalid data from sensor 1 on attempt {attempt + 1}")

                if validate_data(temperature2, humidity2):
                    check_high_humidity(humidity2, 2)
                    check_low_humidity(humidity2, 2)
                    check_high_temperature(temperature2, 2)
                    check_low_temperature(temperature2, 2)
                else:
                    log_error(f"Invalid data from sensor 2 on attempt {attempt + 1}")

                if validate_data(temperature1, humidity1) and validate_data(temperature2, humidity2):
                    break
                else:
                    if attempt < MAX_RETRIES - 1:
                        time.sleep(RETRY_DELAY)

            log_data(temperature1, humidity1, temperature2, humidity2)

            # Wait for next interval, but check running flag every second
            for _ in range(READ_INTERVAL):
                if not running:
                    break
                time.sleep(1)

    except Exception as e:
        log_error(f"Unexpected error: {e}")
    finally:
        GPIO.cleanup()
        print("GPIO cleaned up. Exiting.")

if __name__ == "__main__":
    main()

