import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TEMP_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0

running = True

def signal_handler(signum, frame):
    global running
    running = False

def read_sensor_data(serial_port):
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if not line:
            return None, None
        parts = line.split(',')
        if len(parts) != 2:
            return None, None
        temperature = float(parts[0])
        humidity = float(parts[1])
        return temperature, humidity
    except ValueError:
        return None, None
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None, None

def check_thresholds(temperature, humidity):
    if temperature is not None and temperature > TEMP_THRESHOLD:
        print(f"Alert: Temperature exceeds threshold: {temperature:.1f}C")
    if humidity is not None and humidity > HUMIDITY_THRESHOLD:
        print(f"Alert: Humidity exceeds threshold: {humidity:.1f}%")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    serial_port = None
    try:
        serial_port = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
        print(f"Opened {SERIAL_PORT} at {BAUD_RATE} baud.")

        while running:
            temperature, humidity = read_sensor_data(serial_port)
            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f}C, Humidity: {humidity:.1f}%")
                check_thresholds(temperature, humidity)
            else:
                print("Failed to read sensor data.")
            time.sleep(1)

    except serial.SerialException as e:
        print(f"Error opening serial port: {e}", file=sys.stderr)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if serial_port is not None and serial_port.is_open:
            serial_port.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

