import signal
import sys
import time

import smbus2

# MCP23017 register addresses
IODIRA = 0x00
IODIRB = 0x01
GPPUA = 0x0C
GPPUB = 0x0D
GPIOA = 0x12
GPIOB = 0x13
OLATA = 0x14
OLATB = 0x15

# Pin definitions
LED_PIN = 0       # GPA0
SWITCH_PIN = 7    # GPB7

I2C_BUS = 1
I2C_ADDR = 0x20
DEBOUNCE_MS = 20

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _write_reg(bus, reg, value):
    bus.write_byte_data(I2C_ADDR, reg, value)


def _read_reg(bus, reg):
    return bus.read_byte_data(I2C_ADDR, reg)


def _set_bit(value, bit):
    return value | (1 << bit)


def _clear_bit(value, bit):
    return value & ~(1 << bit)


def _toggle_bit(value, bit):
    return value ^ (1 << bit)


def _init_mcp23017(bus):
    # Port A: all inputs (bit 0 = input)
    _write_reg(bus, IODIRA, 0xFF)
    # Port B: bit 7 input, others outputs
    _write_reg(bus, IODIRB, _set_bit(_read_reg(bus, IODIRB), SWITCH_PIN))
    # Enable internal pull-up on switch pin
    _write_reg(bus, GPPUA, _set_bit(_read_reg(bus, GPPUA), SWITCH_PIN))
    # Ensure LED starts LOW
    _write_reg(bus, OLATA, 0x00)


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)

    try:
        bus = smbus2.SMBus(I2C_BUS)
    except FileNotFoundError:
        print(f"Error: I2C bus /dev/i2c-{I2C_BUS} not found. Enable I2C with 'sudo raspi-config'.")
        sys.exit(1)
    except PermissionError:
        print(f"Error: Permission denied opening /dev/i2c-{I2C_BUS}. Run as root or add user to 'i2c' group.")
        sys.exit(1)
    except OSError as e:
        print(f"Error: Failed to open I2C bus {I2C_BUS}: {e}")
        sys.exit(1)

    try:
        _init_mcp23017(bus)
    except OSError as e:
        print(f"Error: MCP23017 not found at address 0x{I2C_ADDR:02X} on bus {I2C_BUS}: {e}")
        bus.close()
        sys.exit(1)

    led_state = False
    switch_state = False
    switch_last_state = False
    switch_stable_count = 0
    last_switch_time = 0.0

    try:
        while _running:
            try:
                port_b = _read_reg(bus, GPIOB)
            except OSError as e:
                print(f"Warning: I2C read error on GPIOB: {e}")
                time.sleep(0.1)
                continue

            current_switch = bool(port_b & (1 << SWITCH_PIN))

            now = time.monotonic()
            if current_switch != switch_last_state:
                last_switch_time = now
                switch_stable_count = 0
            elif (now - last_switch_time) * 1000 >= DEBOUNCE_MS:
                switch_stable_count += 1
                if switch_stable_count >= 2 and current_switch != switch_state:
                    switch_state = current_switch
                    print(f"Switch state changed to: {switch_state}")

            if switch_state:
                if not led_state:
                    try:
                        _write_reg(bus, OLATA, _set_bit(_read_reg(bus, OLATA), LED_PIN))
                    except OSError as e:
                        print(f"Warning: I2C write error to OLATA: {e}")
                    led_state = True
                    print("LED ON")
            else:
                if led_state:
                    try:
                        _write_reg(bus, OLATA, _clear_bit(_read_reg(bus, OLATA), LED_PIN))
                    except OSError as e:
                        print(f"Warning: I2C write error to OLATA: {e}")
                    led_state = False
                    print("LED OFF")

            switch_last_state = current_switch
            time.sleep(0.01)

    finally:
        if led_state:
            try:
                _write_reg(bus, OLATA, _clear_bit(_read_reg(bus, OLATA), LED_PIN))
            except OSError:
                pass
        bus.close()
        print("Program terminated. I2C bus closed.")


if __name__ == "__main__":
    main()

