import logging
import signal
import sys
import time

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

PULSE_PIN = 17
HIGH_TIME = 0.2
LOW_TIME = 0.2

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def setup_gpio(pin):
    try:
        import RPi.GPIO as GPIO
    except ImportError:
        logging.error("RPi.GPIO library is not installed. Install with: pip install RPi.GPIO")
        sys.exit(1)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
        logging.info(f"GPIO {pin} configured as output (initial LOW).")
        return GPIO
    except Exception as e:
        logging.error(f"Failed to initialize GPIO {pin}: {e}")
        sys.exit(1)


def generate_pulses(gpio, pin, high_time, low_time):
    global _running
    while _running:
        try:
            gpio.output(pin, gpio.HIGH)
            logging.info(f"GPIO {pin} set HIGH ({high_time}s).")
            time.sleep(high_time)
            if not _running:
                break
            gpio.output(pin, gpio.LOW)
            logging.info(f"GPIO {pin} set LOW ({low_time}s).")
            time.sleep(low_time)
        except Exception as e:
            logging.error(f"Error during pulse generation: {e}")
            break


def cleanup_gpio(gpio, pin):
    try:
        gpio.output(pin, gpio.LOW)
        gpio.cleanup(pin)
        logging.info(f"GPIO {pin} cleaned up (set LOW).")
    except Exception as e:
        logging.error(f"Error during GPIO cleanup: {e}")


def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    gpio = None
    try:
        gpio = setup_gpio(PULSE_PIN)
        generate_pulses(gpio, PULSE_PIN, HIGH_TIME, LOW_TIME)
    except KeyboardInterrupt:
        logging.info("Program interrupted by user (KeyboardInterrupt).")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        if gpio is not None:
            cleanup_gpio(gpio, PULSE_PIN)
        logging.info("Exiting program.")


if __name__ == "__main__":
    main()

