import sys
import time
import signal
import threading
import DOG

# Global state
running = True
log_file = None
receive_thread = None


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global running
    print(f"\nReceived signal {signum}, shutting down...")
    running = False


def help_command(command=None):
    """Display help information for a specific command, or all commands if None."""
    commands = {
        "help": "Displays help information. Usage: help [command]",
        "start": "Starts logging data to a file. Usage: start <filename>",
        "stop": "Stops logging data. Usage: stop",
        "display": "Displays the contents of the log file. Usage: display",
        "send": "Sends data via DOG. Usage: send <data>",
        "write": "Writes data directly to the log file. Usage: write <data>",
        "exit": "Exits the program. Usage: exit",
    }
    if command:
        print(commands.get(command, f"No help found for '{command}'"))
    else:
        print("Available commands:")
        for cmd in sorted(commands):
            print(f"  {cmd}: {commands[cmd]}")


def start_logging(filename):
    """Starts the data logging thread."""
    global log_file, receive_thread
    try:
        log_file = open(filename, "a")
        print(f"Logging data to {filename}...")

        def receive_data():
            """Continuously receive data from DOG and write to file."""
            while running:
                try:
                    data = DOG.receive()
                    if data is not None:
                        log_file.write(str(data) + "\n")
                        log_file.flush()
                except Exception as e:
                    print(f"Error receiving data: {e}")
                time.sleep(0.1)

        receive_thread = threading.Thread(target=receive_data, daemon=True)
        receive_thread.start()
    except Exception as e:
        print(f"Error starting logging: {e}")


def stop_logging():
    """Stops the data logging thread and closes the log file."""
    global running, receive_thread, log_file
    running = False
    if receive_thread is not None and receive_thread.is_alive():
        receive_thread.join(timeout=2.0)
        if receive_thread.is_alive():
            print("Warning: receive thread did not stop cleanly.")
    if log_file is not None:
        try:
            log_file.close()
        except Exception as e:
            print(f"Error closing log file: {e}")
        log_file = None
    print("Logging stopped.")


def display_log():
    """Displays the contents of the log file."""
    if log_file is None:
        print("No log file opened. Use 'start <filename>' first.")
        return
    try:
        log_file.seek(0)
        print(log_file.read())
    except Exception as e:
        print(f"Error displaying log: {e}")


def send_data(data):
    """Sends data via DOG."""
    try:
        DOG.send(data)
        print(f"Sent: {data}")
    except Exception as e:
        print(f"Error sending data: {e}")


def write_data(data):
    """Writes data directly to the log file."""
    if log_file is None:
        print("No log file opened. Use 'start <filename>' first.")
        return
    try:
        log_file.write(str(data) + "\n")
        log_file.flush()
        print(f"Wrote: {data}")
    except Exception as e:
        print(f"Error writing to log: {e}")


def exit_program():
    """Stops the library's API call and exits."""
    global running
    running = False
    try:
        DOG.stop()
    except Exception as e:
        print(f"Error stopping DOG: {e}")
    print("Program exited.")
    sys.exit(0)


def main():
    """Main function to handle user input and commands."""
    global running

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize DOG library
    try:
        DOG.start()
    except Exception as e:
        print(f"Error initializing DOG: {e}")
        sys.exit(1)

    print("DOG logging system ready. Type 'help' for commands.")

    while running:
        try:
            command = input("> ").strip()
        except EOFError:
            print("\nEOF received, exiting.")
            break

        if not command:
            continue

        parts = command.split()
        cmd = parts[0].lower()

        if cmd == "help":
            if len(parts) > 1:
                help_command(parts[1])
            else:
                help_command()

        elif cmd == "start":
            if len(parts) < 2:
                print("Error: Missing filename. Usage: start <filename>")
            else:
                start_logging(parts[1])

        elif cmd == "stop":
            stop_logging()

        elif cmd == "display":
            display_log()

        elif cmd == "send":
            if len(parts) < 2:
                print("Error: Missing data. Usage: send <data>")
            else:
                send_data(" ".join(parts[1:]))

        elif cmd == "write":
            if len(parts) < 2:
                print("Error: Missing data. Usage: write <data>")
            else:
                write_data(" ".join(parts[1:]))

        elif cmd == "exit":
            exit_program()

        else:
            print(f"Unknown command: {cmd}")
            help_command()


if __name__ == "__main__":
    main()

