import sys
import time
import atexit

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("Error: RPi.GPIO library not found. Install with: pip install RPi.GPIO", file=sys.stderr)
    sys.exit(1)

# Hard-coded VADER lexicon (20 words, scores -1.0..1.0)
VADER_LEXICON = {
    "good": 0.5, "great": 0.7, "excellent": 0.9, "awesome": 0.8,
    "best": 0.6, "love": 0.7, "hate": -0.6, "terrible": -0.9,
    "worst": -0.5, "awful": -0.8, "terribly": -0.9, "worse": -0.6,
    "bad": -0.4, "sucks": -0.7, "poor": -0.3, "nothing": -0.1,
    "goodbye": -0.2, "fuck": -0.8,
}

# GPIO pins (BCM numbering)
LED_GREEN = 17
LED_RED = 18

# Timing
LED_DURATION = 2.0

# Global flag for cleanup
_gpio_initialized = False


def cleanup_gpio():
    """Turn off both LEDs and release GPIO resources."""
    global _gpio_initialized
    if _gpio_initialized:
        try:
            GPIO.output(LED_GREEN, GPIO.LOW)
            GPIO.output(LED_RED, GPIO.LOW)
        except Exception:
            pass
        try:
            GPIO.cleanup()
        except Exception:
            pass
        _gpio_initialized = False


def setup_gpio():
    """Initialize GPIO mode, LEDs, and register cleanup."""
    global _gpio_initialized
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LED_GREEN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(LED_RED, GPIO.OUT, initial=GPIO.LOW)
    _gpio_initialized = True
    atexit.register(cleanup_gpio)


def tokenize_text(text):
    """Tokenize text by lower-casing and splitting on whitespace."""
    return text.lower().split()


def analyze_sentiment(text):
    """
    Compute average sentiment score for each token in the text.
    Unknown words get a default score of 0.0.
    """
    tokens = tokenize_text(text)
    scores = [VADER_LEXICON.get(token, 0.0) for token in tokens]
    if not scores:
        return 0.0
    return sum(scores) / len(scores)


def classify_sentiment(average_score):
    """Classify sentiment based on average score."""
    if average_score > 0.2:
        return "Positive"
    elif average_score < -0.2:
        return "Negative"
    else:
        return "Neutral"


def light_led(color):
    """Light a single LED for LED_DURATION seconds, then turn it off."""
    if not _gpio_initialized:
        print("Error: GPIO not initialized.", file=sys.stderr)
        return
    try:
        if color == "Green":
            GPIO.output(LED_GREEN, GPIO.HIGH)
            GPIO.output(LED_RED, GPIO.LOW)
        elif color == "Red":
            GPIO.output(LED_RED, GPIO.HIGH)
            GPIO.output(LED_GREEN, GPIO.LOW)
        else:
            GPIO.output(LED_GREEN, GPIO.LOW)
            GPIO.output(LED_RED, GPIO.LOW)
        time.sleep(LED_DURATION)
    except Exception as e:
        print(f"Error controlling LED: {e}", file=sys.stderr)
    finally:
        GPIO.output(LED_GREEN, GPIO.LOW)
        GPIO.output(LED_RED, GPIO.LOW)


def main():
    """Main function to read text, analyze sentiment, and light LEDs."""
    try:
        setup_gpio()
        user_text = input("Enter text to analyze: ")
        average_score = analyze_sentiment(user_text)
        sentiment = classify_sentiment(average_score)
        print(f"Sentiment: {sentiment}")
        if sentiment == "Positive":
            light_led("Green")
        elif sentiment == "Negative":
            light_led("Red")
        else:
            light_led("Neutral")
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    except Exception as e:
        print(f"An error occurred: {e}", file=sys.stderr)
    finally:
        cleanup_gpio()


if __name__ == "__main__":
    main()

