import signal
import sys
import time

import smbus2

I2C_BUS = 1
BH1750_ADDR = 0x23
BH1750_CMD_ONCE_HIRES_1 = 0x20
MEASURE_DELAY_S = 0.12
LOOP_INTERVAL_S = 3.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _probe_sensor(bus):
    try:
        bus.read_byte(BH1750_ADDR)
        return True
    except OSError:
        return False


def _trigger_measurement(bus):
    bus.write_byte(BH1750_ADDR, BH1750_CMD_ONCE_HIRES_1)


def _read_illuminance(bus):
    _trigger_measurement(bus)
    time.sleep(MEASURE_DELAY_S)
    data = bus.read_i2c_block_data(BH1750_ADDR, 0x00, 2)
    raw = (data[0] << 8) | data[1]
    return raw / 1.2


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = smbus2.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        if not _probe_sensor(bus):
            print(
                f"Error: no device acknowledged at I2C 0x{BH1750_ADDR:02X} on bus {I2C_BUS}.",
                file=sys.stderr,
            )
            sys.exit(1)
    except OSError as e:
        print(f"Error: I2C bus probe failed: {e}", file=sys.stderr)
        sys.exit(1)

    print("BH1750 illuminance monitor started (one-shot, high-res, 120 ms delay).")
    print("Press Ctrl+C to stop.\n")

    try:
        while _running:
            try:
                illuminance = _read_illuminance(bus)
                print(f"Illuminance: {illuminance:.2f} lux")
            except OSError as e:
                print(f"Error: I2C communication failed: {e}", file=sys.stderr)
            except Exception as e:
                print(f"Error: unexpected runtime failure: {e}", file=sys.stderr)

            for _ in range(int(LOOP_INTERVAL_S * 10)):
                if not _running:
                    break
                time.sleep(0.1)
    finally:
        bus.close()
        print("\nI2C bus released. Exiting.")


if __name__ == "__main__":
    main()

