import time
import logging
import signal
import zmq
import threading

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    GPIO = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class PIDHandler:
    """
    Manages PID error output signals and a ZeroMQ watchdog on a Raspberry Pi.

    Provides PWM (physical pin 12, BCM 18) or digital (physical pin 10, BCM 15)
    error output based on the ``pwm`` flag.  A 20-second watchdog timeout
    enforces a ``set_error_output(True)`` when no data is received for that
    period.
    """

    def __init__(self, pwm_pin: int = 12, digital_pin: int = 10, pwm: bool = True,
                 watchdog_timeout: float = 20.0):
        self.pwm_pin = pwm_pin
        self.digital_pin = digital_pin
        self.pwm = pwm
        self.watchdog_timeout = watchdog_timeout
        self.last_msg = time.time()
        self.global_err_state = False
        self.subscriptions = []
        self.zmq_socket = None
        self.zmq_context = None
        self.error_output_device = None
        self.error_output_pwm = None
        self._shutdown = threading.Event()
        self._lock = threading.Lock()

        if GPIO is not None:
            try:
                GPIO.setmode(GPIO.BOARD)
                GPIO.setwarnings(False)
            except Exception as exc:
                logging.error(f"Failed to set GPIO mode: {exc}")
                raise

        self._init_error_output()

    def _init_error_output(self):
        """Initialize the error output device; tolerate non-Pi environments."""
        if GPIO is None:
            logging.warning("RPi.GPIO not available; error output disabled.")
            return

        try:
            if self.pwm:
                GPIO.setup(self.pwm_pin, GPIO.OUT)
                self.error_output_pwm = GPIO.PWM(self.pwm_pin, 1000)
                self.error_output_pwm.start(0.0)
                logging.info(f"PWM error output initialized on BOARD pin {self.pwm_pin} "
                             f"at 1000 Hz, duty 0.0%.")
            else:
                GPIO.setup(self.digital_pin, GPIO.OUT)
                GPIO.output(self.digital_pin, GPIO.LOW)
                logging.info(f"Digital error output initialized on BOARD pin {self.digital_pin}.")
        except Exception as exc:
            logging.error(f"Error initializing error output: {exc}")
            self.cleanup()
            raise

    def set_error_output(self, state: bool):
        """Directly set the error output state."""
        with self._lock:
            self.global_err_state = state
            if self.error_output_pwm is not None:
                duty = float(state) * 100.0
                try:
                    self.error_output_pwm.ChangeDutyCycle(duty)
                except Exception as exc:
                    logging.error(f"Failed to change PWM duty cycle: {exc}")
            elif self.error_output_device is not None:
                try:
                    GPIO.output(self.error_output_device, GPIO.HIGH if state else GPIO.LOW)
                except Exception as exc:
                    logging.error(f"Failed to set digital output: {exc}")

    def update_error_output(self):
        """Pull the current error state from the instance variable."""
        with self._lock:
            self.set_error_output(self.global_err_state)

    def subscribe(self, callback):
        """Register a callback for ZeroMQ messages."""
        with self._lock:
            self.subscriptions.append(callback)

    def _signal_handler(self, signum, frame):
        logging.info(f"Signal {signum} received; shutting down.")
        self._shutdown.set()
        self.cleanup()

    def cleanup(self):
        """Release all GPIO resources."""
        if GPIO is not None:
            try:
                if self.error_output_pwm is not None:
                    self.error_output_pwm.stop()
                if self.pwm:
                    GPIO.output(self.pwm_pin, GPIO.LOW)
                else:
                    GPIO.output(self.digital_pin, GPIO.LOW)
            except Exception as exc:
                logging.error(f"Error during GPIO cleanup: {exc}")
            try:
                GPIO.cleanup()
            except Exception as exc:
                logging.error(f"Error during GPIO.cleanup(): {exc}")

    def handle_message(self, message):
        """Process a ZeroMQ message; enforce the watchdog."""
        if self._shutdown.is_set():
            return

        self.last_msg = time.time()
        with self._lock:
            for callback in self.subscriptions:
                try:
                    callback(message)
                except Exception as exc:
                    logging.error(f"Error in subscription callback: {exc}")

        if time.time() - self.last_msg > self.watchdog_timeout:
            logging.warning("Watchdog timeout reached; setting error output high.")
            self.set_error_output(True)

    def run_watchdog(self):
        """Background thread: periodically check the watchdog and update output."""
        while not self._shutdown.is_set():
            if time.time() - self.last_msg > self.watchdog_timeout:
                logging.warning("Watchdog timeout reached; setting error output high.")
                self.set_error_output(True)
            self._shutdown.wait(1.0)


def main():
    handler = PIDHandler(pwm_pin=12, digital_pin=10, pwm=True, watchdog_timeout=20.0)

    signal.signal(signal.SIGINT, handler._signal_handler)
    signal.signal(signal.SIGTERM, handler._signal_handler)

    context = zmq.Context.instance()
    handler.zmq_socket = context.socket(zmq.SUB)
    handler.zmq_socket.setsockopt_string(zmq.SUBSCRIBE, "")
    handler.zmq_socket.connect('tcp://localhost:5555')
    handler.zmq_context = context

    watchdog_thread = threading.Thread(target=handler.run_watchdog, daemon=True)
    watchdog_thread.start()

    try:
        while not handler._shutdown.is_set():
            try:
                message = handler.zmq_socket.recv(flags=zmq.NOBLOCK)
            except zmq.Again:
                pass
            except Exception as exc:
                logging.error(f"ZMQ receive error: {exc}")
                break
            else:
                if message:
                    handler.handle_message(message)
    finally:
        handler._shutdown.set()
        watchdog_thread.join(timeout=2.0)
        handler.cleanup()


if __name__ == '__main__':
    main()

