            elif self.error_output_device is not None:
                try:
                    GPIO.output(self.error_output_device, GPIO.HIGH if state else GPIO.LOW)
                except Exception as exc:
                    logging.error(f"Failed to set digital output: {exc}")

    def update_error_output(self):
        """Pull the current error state from the instance variable."""
        with self._lock:
            self.set_error_output(self.global_err_state)

    def subscribe(self, callback):
        """Register a callback for ZeroMQ messages."""
        with self._lock:
            self.subscriptions.append(callback)

    def _signal_handler(self, signum, frame):
        logging.info(f"Signal {signum} received; shutting down.")
        self._shutdown.set()
        self.cleanup()

    def cleanup(self):
        """Release all GPIO resources."""
        if GPIO is not None:
            try:
                if self.error_output_pwm is not None:
                    self.error_output_pwm.stop()
                if self.pwm:
                    GPIO.output(self.pwm_pin, GPIO.LOW)
                else:
                    GPIO.output(self.digital_pin, GPIO.LOW)
            except Exception as exc:
                logging.error(f"Error during GPIO cleanup: {exc}")
            try:
                GPIO.cleanup()
            except Exception as exc:
                logging.error(f"Error during GPIO.cleanup(): {exc}")

    def handle_message(self, message):
        """Process a ZeroMQ message; enforce the watchdog."""
        if self._shutdown.is_set():
            return

        self.last_msg = time.time()
        with self._lock:
            for callback in self.subscriptions:
                try:
                    callback(message)
                except Exception as exc:
                    logging.error(f"Error in subscription callback: {exc}")

        if time.time() - self.last_msg > self.watchdog_timeout:
            logging.warning("Watchdog timeout reached; setting error output high.")
            self.set_error_output(True)

    def run_watchdog(self):
        """Background thread: periodically check the watchdog and update output."""
        while not self._shutdown.is_set():
            if time.time() - self.last_msg > self.watchdog_timeout:
                logging.warning("Watchdog timeout reached; setting error output high.")
                self.set_error_output(True)
            self._shutdown.wait(1.0)


def main():
    handler = PIDHandler(pwm_pin=12, digital_pin=10, pwm=True, watchdog_timeout=20.0)

    signal.signal(signal.SIGINT, handler._signal_handler)
    signal.signal(signal.SIGTERM, handler._signal_handler)

    context = zmq.Context.instance()
    handler.zmq_socket = context.socket(zmq.SUB)
    handler.zmq_socket.setsockopt_string(zmq.SUBSCRIBE, "")
    handler.zmq_socket.connect('tcp://localhost:5555')
    handler.zmq_context = context

    watchdog_thread = threading.Thread(target=handler.run_watchdog, daemon=True)
    watchdog_thread.start()

    try:
        while not handler._shutdown.is_set():
            try:
                message = handler.zmq_socket.recv(flags=zmq.NOBLOCK)
            except zmq.Again:
                pass
            except Exception as exc:
                logging.error(f"ZMQ receive error: {exc}")
                break
            else:
                if message:
                    handler.handle_message(message)
    finally:
        handler._shutdown.set()
        watchdog_thread.join(timeout=2.0)
        handler.cleanup()


if __name__ == '__main__':
    main()

