import sys
import signal

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("Error: RPi.GPIO library not found. Install with: sudo apt install python3-rpi.gpio")
    sys.exit(1)

FAN_PIN = 12
PWM_FREQ = 25000

_running = True
_pwm = None

def _cleanup(signum=None, frame=None):
    global _running, _pwm
    _running = False
    if _pwm is not None:
        try:
            _pwm.ChangeDutyCycle(0)
        except Exception:
            pass
        try:
            _pwm.stop()
        except Exception:
            pass
        _pwm = None
    try:
        GPIO.cleanup()
    except Exception:
        pass
    if signum is not None:
        sys.exit(0)

def main():
    global _pwm
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    try:
        GPIO.setup(FAN_PIN, GPIO.OUT)
    except Exception as e:
        print(f"Error: Failed to initialize GPIO pin {FAN_PIN}: {e}")
        GPIO.cleanup()
        sys.exit(1)
    try:
        _pwm = GPIO.PWM(FAN_PIN, PWM_FREQ)
        _pwm.start(0)
    except Exception as e:
        print(f"Warning: Hardware PWM unavailable ({e}); falling back to software PWM.")
        try:
            _pwm = GPIO.PWM(FAN_PIN, PWM_FREQ)
            _pwm.start(0)
        except Exception as e2:
            print(f"Error: Software PWM initialization failed: {e2}")
            GPIO.cleanup()
            sys.exit(1)
    print("Fan control ready. Enter a speed (0-100) or 'q' to quit.")
    while _running:
        try:
            raw = input("Fan Speed (0-100, q to quit): ").strip()
        except EOFError:
            break
        if raw.lower() == 'q':
            break
        if not raw:
            continue
        try:
            speed = float(raw)
        except ValueError:
            print("Invalid input. Please enter a number between 0 and 100.")
            continue
        if not (0 <= speed <= 100):
            print("Invalid input. Please enter a number between 0 and 100.")
            continue
        try:
            _pwm.ChangeDutyCycle(speed)
        except Exception as e:
            print(f"Warning: Failed to set duty cycle: {e}")
    _cleanup()

if __name__ == "__main__":
    signal.signal(signal.SIGINT, _cleanup)
    signal.signal(signal.SIGTERM, _cleanup)
    main()

