import RPi.GPIO as GPIO
import time
import threading


class RotaryEncoder:
    """
    RotaryEncoder class for a KY-040 rotary encoder on a Raspberry Pi.

    Uses GPIO17 (CLK) and GPIO18 (DT) with internal pull-ups.
    Debounce interval is 0.005 seconds.
    """

    def __init__(self, clk_pin, dt_pin, callback=None, debounce_time=0.005):
        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.callback = callback
        self.debounce_time = debounce_time
        self.counter = 0
        self.last_clk_state = None
        self._lock = threading.Lock()
        self._running = True

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setwarnings(False)
            GPIO.setup(self.clk_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
            GPIO.setup(self.dt_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)

            # Initialise state
            self.last_clk_state = GPIO.input(self.clk_pin)

            # Register edge callbacks
            GPIO.add_event_detect(
                self.clk_pin, GPIO.BOTH, callback=self._on_clk_change
            )

            if self.callback is not None:
                if not callable(self.callback):
                    raise TypeError("callback must be callable or None")

        except Exception as e:
            GPIO.cleanup()
            raise RuntimeError(f"Failed to initialise RotaryEncoder: {e}") from e

    def _on_clk_change(self, channel):
        """Internal callback for CLK pin state changes."""
        if not self._running:
            return

        try:
            current_clk_state = GPIO.input(self.clk_pin)

            with self._lock:
                if self.last_clk_state is None:
                    self.last_clk_state = current_clk_state
                    return

                if current_clk_state != self.last_clk_state:
                    dt_state = GPIO.input(self.dt_pin)

                    if dt_state != current_clk_state:
                        self.counter += 1
                    else:
                        self.counter -= 1

                    if self.callback is not None:
                        try:
                            self.callback(self.counter)
                        except Exception as e:
                            print(f"Error in callback: {e}")

                    self.last_clk_state = current_clk_state

        except Exception as e:
            print(f"Error in _on_clk_change: {e}")

    def get_counter(self):
        """Returns the current counter value."""
        with self._lock:
            return self.counter

    def cleanup(self):
        """Stops the encoder and releases GPIO resources."""
        with self._lock:
            self._running = False

        try:
            GPIO.remove_event_detect(self.clk_pin)
        except Exception:
            pass

        GPIO.cleanup()


if __name__ == "__main__":
    CLK_PIN = 17
    DT_PIN = 18

    def encoder_callback(counter_value):
        print(f"Counter: {counter_value}")

    encoder = None
    try:
        encoder = RotaryEncoder(CLK_PIN, DT_PIN, callback=encoder_callback)
        print("Rotary encoder ready. Rotate to change value. Press Ctrl+C to exit.")

        while True:
            time.sleep(0.1)

    except KeyboardInterrupt:
        print("\nExiting...")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        if encoder is not None:
            encoder.cleanup()

