            try:
                display_bus.close()
            except Exception:
                pass
    except Exception:
        pass


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global running
    running = False


def init_hardware():
    """Initialize all hardware peripherals; degrade gracefully if unavailable."""
    global display_bus, apa102, green_led, blue_led, buzzer

    if _HAT_AVAILABLE:
        try:
            display.clear()
            display.show()
        except Exception as e:
            print(f"Warning: display init failed: {e}", file=sys.stderr)
    else:
        print("Warning: rainbowhat library not available; display disabled.", file=sys.stderr)

