        try:
            apa102 = APA102(num_leds=1, data_pin=APA102_DATA_PIN, clock_pin=APA102_CLOCK_PIN)
            apa102.clear_strip()
        except Exception as e:
            print(f"Warning: APA102 init failed: {e}", file=sys.stderr)
            apa102 = None
    else:
        print("Warning: rainbowhat.apa102 not available; APA102 disabled.", file=sys.stderr)

