        try:
            green_led = LED(GREEN_LED_PIN)
            blue_led = LED(BLUE_LED_PIN)
            buzzer = LED(BUZZER_PIN)
        except Exception as e:
            print(f"Warning: GPIO init failed: {e}", file=sys.stderr)
            green_led = blue_led = buzzer = None
    else:
        print("Warning: gpiozero library not available; LEDs/buzzer disabled.", file=sys.stderr)


