    """Drive the APA102 strip: 0 -> dim white, 7 -> all white, else single pixel at index."""
    if apa102 is None:
        return
    try:
        if value == 0:
            apa102.set_pixel(0, 255, 255, 255)
        elif value == 7:
            for i in range(14):
                apa102.set_pixel(i, 255, 255, 255)
        else:
            apa102.set_pixel(value, 255, 0, 0)
            apa102.set_pixel(value + 7, 0, 255, 0)
            apa102.set_pixel(value + 14, 0, 0, 255)
        apa102.show()
    except Exception as e:
        print(f"Error updating APA102: {e}", file=sys.stderr)


def update_leds(value):
    """Drive the discrete LEDs based on bit states."""
    if green_led is not None:
        try:
            green_led.on() if bit_states[0] else green_led.off()
        except Exception as e:
            print(f"Error updating green LED: {e}", file=sys.stderr)
    if blue_led is not None:
        try:
            blue_led.on() if bit_states[1] else blue_led.off()
        except Exception as e:
            print(f"Error updating blue LED: {e}", file=sys.stderr)


