    """Sound a 0.5 s tone when value changes."""
    if buzzer is not None:
        try:
            buzzer.on()
            time.sleep(0.5)
            buzzer.off()
        except Exception as e:
            print(f"Error updating buzzer: {e}", file=sys.stderr)


def handle_touch(channel):
    """Toggle the corresponding bit and update all outputs."""
    global bit_states
    if channel == TOUCH_A_PIN:
        bit_states[0] = 1 - bit_states[0]
    elif channel == TOUCH_B_PIN:
        bit_states[1] = 1 - bit_states[1]
    elif channel == TOUCH_C_PIN:
        bit_states[2] = 1 - bit_states[2]
    else:
        return

    value = (bit_states[0] << 2) | (bit_states[1] << 1) | bit_states[2]
    update_display(value)
    update_apa102(value)
    update_leds(value)
    update_buzzer(value)


def main():
    global running
    init_hardware()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if _GPIOZERO_AVAILABLE:
        try:
            touch_a = Button(TOUCH_A_PIN, pull_up=True)
            touch_b = Button(TOUCH_B_PIN, pull_up=True)
            touch_c = Button(TOUCH_C_PIN, pull_up=True)
            touch_a.when_pressed = lambda: handle_touch(TOUCH_A_PIN)
            touch_b.when_pressed = lambda: handle_touch(TOUCH_B_PIN)
            touch_c.when_pressed = lambda: handle_touch(TOUCH_C_PIN)
        except Exception as e:
            print(f"Warning: touch event init failed: {e}", file=sys.stderr)
    else:
        print("Warning: gpiozero not available; touch events disabled.", file=sys.stderr)

    print("Rainbow HAT binary counter running. Press Ctrl+C to exit.")
    try:
        while running:
            time.sleep(0.1)
    except Exception as e:
        print(f"Fatal error in main loop: {e}", file=sys.stderr)
    finally:
        cleanup()
        print("Exited cleanly.")


if __name__ == "__main__":
    main()

