#!/usr/bin/env python3
"""
LED Blink Program for Raspberry Pi 3 Model B+

Blinks an LED on GPIO17 (BCM) at 1 Hz, keeping the LED on for 1 s and off for 1 s.
Uses gpiozero for modern, robust GPIO control.
"""

import sys
import time

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, BadPinFactory
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(0)

LED_PIN = 17


def main():
    led = None
    try:
        # Attempt to create the LED object; gpiozero will raise an exception
        # if the pin factory is unavailable (e.g., not running on a Pi).
        led = LED(LED_PIN)

        # Blink the LED at 1 Hz, keeping it on for 1 s and off for 1 s.
        # background=False keeps the loop responsive to KeyboardInterrupt.
        led.blink(on_time=1, off_time=1, background=False)

        # Keep the program running until interrupted.
        while True:
            time.sleep(1)

    except KeyboardInterrupt:
        print("\nProgram stopped by user.")

    except (GPIOZeroError, BadPinFactory) as e:
        print(f"GPIO error: {e}", file=sys.stderr)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)

    finally:
        # Ensure the LED is turned off and resources are released.
        if led is not None:
            try:
                led.close()
            except Exception:
                pass
        print("GPIO cleanup done.")


if __name__ == "__main__":
    main()

