import sys

LED_PIN = 18

def setup_gpio():
    """Initialize GPIO mode and set LED pin as output."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        sys.exit(1)

def cleanup_gpio():
    """Safely reset GPIO pins."""
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
        GPIO.cleanup()
    except Exception:
        pass

def main():
