import json
import random
import sys

# Simulate a voice recognition system for smart agriculture on Raspberry Pi 4.
# The system generates six simulated audio frames, each assigned a random energy level,
# and maps each keyword to a farm action.

# Keywords recognized by the voice recognition system
KEYWORDS = ["water", "stop", "status"]

# Farm actions corresponding to recognized keywords
ACTIONS = {
    "water": "open_valve",
    "stop": "close_valve",
    "status": "report",
}

# Number of simulated audio frames to process
NUM_FRAMES = 6


def generate_energy_level():
    """Generate a random energy level for a simulated audio frame (0-9)."""
    return random.randint(0, 9)


def recognize_keyword(energy_level):
    """
    Simulate keyword recognition based on the energy level.
    Returns the recognized keyword or None if no keyword is detected.
    """
    if energy_level < 3:
        return None
    if energy_level < 6:
        return random.choice(KEYWORDS)
    return None


def map_keyword_to_action(keyword):
    """Map a recognized keyword to a farm action."""
    return ACTIONS.get(keyword, "unknown")


def main():
    """Main function to simulate voice recognition and execute farm actions."""
    actions_taken = []

    try:
        for frame_index in range(NUM_FRAMES):
            energy_level = generate_energy_level()
            keyword = recognize_keyword(energy_level)

            if keyword:
                action = map_keyword_to_action(keyword)
                actions_taken.append(action)
                print(f"Frame {frame_index}: Keyword={keyword}, Action={action}")
            else:
                print(f"Frame {frame_index}: No keyword detected (energy={energy_level})")

    except Exception as e:
        print(f"Error during simulation: {e}", file=sys.stderr)
        sys.exit(1)

    finally:
        # Write the list of actions taken to a JSON file
        try:
            with open("voice_actions.json", "w") as f:
                json.dump(actions_taken, f, indent=2)
            print(f"Actions written to voice_actions.json ({len(actions_taken)} actions)")
        except IOError as e:
            print(f"Error writing actions to file: {e}", file=sys.stderr)
            sys.exit(1)


if __name__ == "__main__":
    main()

