    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class Fuchikoma:
    SERVO_MIN_ANGLE = -77
    SERVO_MAX_ANGLE = 77
    SERVO_MIN_PULSE = 150
    SERVO_MAX_PULSE = 600
    SERVO_FREQ = 60
    SERVO_CHANNELS = {
        "claw": 0,
        "lock": 1,
        "water_gun": 2,
    }

    def __init__(self, channels=None, delay=0.029, i2c_bus=None):
        self.delay = delay
        self.channels = channels if channels else self.SERVO_CHANNELS
        self.kit = None
        self._bus = None
        self._initialized = False

        if i2c_bus is not None:
            try:
                self.kit = ServoKit(channels=len(self.channels), address=0x40, i2c=i2c_bus)
                self.kit.servo.frequency = self.SERVO_FREQ
                self._bus = i2c_bus
                self._initialized = True
                logging.info("ServoKit initialized successfully.")
            except (ValueError, OSError) as e:
                logging.error(f"Failed to initialize ServoKit on I2C bus {i2c_bus}: {e}")
                raise
        else:
            try:
                self.kit = ServoKit(channels=len(self.channels), address=0x40)
                self.kit.servo.frequency = self.SERVO_FREQ
                self._bus = None
                self._initialized = True
                logging.info("ServoKit initialized successfully (I2C auto-detected).")
            except (ValueError, OSError) as e:
                logging.error(f"Failed to initialize ServoKit: {e}")
                raise

        atexit.register(self.cleanup)

    def cleanup(self):
        if not self._initialized:
            return
        logging.info("Cleaning up servo channels...")
        for name, channel in self.channels.items():
            try:
                self.kit.servo[channel].angle = None
            except Exception as e:
                logging.warning(f"Error clearing channel {channel} ({name}): {e}")
        if self._bus is not None:
            try:
                self._bus.deinit()
            except Exception as e:
                logging.warning(f"Error deinitializing I2C bus: {e}")
        self._initialized = False

    def _validate_channel(self, servo_name):
        if servo_name not in self.channels:
            raise ValueError(f"Invalid servo name: {servo_name}. Must be one of {list(self.channels.keys())}")

    def _validate_angle(self, angle):
        if not (self.SERVO_MIN_ANGLE <= angle <= self.SERVO_MAX_ANGLE):
            raise ValueError(f"Angle {angle} out of range. Must be between {self.SERVO_MIN_ANGLE} and {self.SERVO_MAX_ANGLE}")

    def _calculate_pulse(self, angle):
        pulse_range = self.SERVO_MAX_PULSE - self.SERVO_MIN_PULSE
        pulse = self.SERVO_MIN_PULSE + (pulse_range * (angle + self.SERVO_MAX_ANGLE) / (self.SERVO_MAX_ANGLE - self.SERVO_MIN_ANGLE))
        return int(pulse)

    def move_servo(self, servo_name, angle):
        self._validate_channel(servo_name)
        self._validate_angle(angle)
        channel = self.channels[servo_name]
        pulse = self._calculate_pulse(angle)
        try:
            self.kit.servo[channel].angle = angle
            time.sleep(self.delay)
            self.kit.servo[channel].angle = None
        except Exception as e:
            logging.error(f"Error moving servo {servo_name} on channel {channel}: {e}")
            raise

    def bite(self):
        self.move_servo("claw", -75)

    def open_claw(self):
        self.move_servo("claw", 75)

    def lock(self):
        self.move_servo("lock", 75)

    def unlock(self):
        self.move_servo("lock", -75)

    def shoot(self):
        self.move_servo("water_gun", -75)
        time.sleep(0.15)
        self.load_water()

    def load_water(self):
        self.move_servo("water_gun", 75)


def main():
    fuchikoma = None
    try:
        fuchikoma = Fuchikoma()
        fuchikoma.bite()
        fuchikoma.open_claw()
        fuchikoma.lock()
        fuchikoma.unlock()
        fuchikoma.shoot()
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        if fuchikoma is not None:
            fuchikoma.cleanup()


if __name__ == "__main__":
    main()

