import random
import time
import signal
import sys

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO could not be imported. This must be run on a Raspberry Pi.")
    sys.exit(1)

LED_PIN = 18
READ_INTERVAL = 2
SENSOR_FAILURE_PROBABILITY = 0.1

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)

def cleanup_gpio():
    try:
        GPIO.output(LED_PIN, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()

def simulate_water_quality_reading():
    if random.random() < SENSOR_FAILURE_PROBABILITY:
        return None
    return random.randint(0, 100)

def control_led(water_quality):
    if water_quality is None:
        print("Sensor read failed. Retrying...")
        return
    if water_quality < 50:
        GPIO.output(LED_PIN, GPIO.HIGH)
        print(f"Water quality: {water_quality}% - LED ON (Alert)")
    else:
        GPIO.output(LED_PIN, GPIO.LOW)
        print(f"Water quality: {water_quality}% - LED OFF (Normal)")

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        setup_gpio()
        print("Water quality monitoring started. Press Ctrl+C to stop.")
        while _running:
            water_quality = simulate_water_quality_reading()
            if water_quality is None:
                water_quality = simulate_water_quality_reading()
                if water_quality is None:
                    print("Sensor read failed after retry. Skipping this reading.")
                    time.sleep(READ_INTERVAL)
                    continue
            control_led(water_quality)
            time.sleep(READ_INTERVAL)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        cleanup_gpio()
        print("GPIO cleanup completed. Exiting.")

if __name__ == "__main__":
    main()

