        for i in range(NUM_READINGS):
            if not _running:
                break
            moisture = read_moisture_level()
            pump_state = control_water_pump(moisture, WATER_PUMP_PIN)
            reason = "moisture below threshold" if pump_state == "ON" else "moisture adequate"
