import smbus
import time
import logging
import threading
import signal
import sys

try:
    from gpiozero import PWMOutputDevice
except ImportError:
    print("gpiozero is required: pip install gpiozero")
    sys.exit(1)

logging.basicConfig(
    filename='log.txt',
    level=logging.INFO,
    format='%(asctime)s - %(message)s'
)

MPU6050_ADDR = 0x68
PWR_MGMT_1 = 0x6B
GYRO_XOUT_H = 0x43
GYRO_YOUT_H = 0x45
GYRO_ZOUT_H = 0x47
SMPLRT_DIV = 0x19
CONFIG = 0x1A
INT_ENABLE = 0x38

bus = None
pwm_devices = []
kp = {'x': 1.0, 'y': 1.0, 'z': 1.0}
running = True


def init_mpu6050():
    global bus
    try:
        bus = smbus.SMBus(1)
        bus.write_byte_data(MPU6050_ADDR, SMPLRT_DIV, 7)
        bus.write_byte_data(MPU6050_ADDR, CONFIG, 0)
        bus.write_byte_data(MPU6050_ADDR, INT_ENABLE, 0)
        bus.write_byte_data(MPU6050_ADDR, PWR_MGMT_1, 0)
        time.sleep(0.1)
        logging.info("MPU6050 initialized.")
    except IOError as e:
        logging.error(f"MPU6050 init failed: {e}")
        bus = None


def read_gyro():
    if bus is None:
        return None, None, None
    try:
        data = bus.read_i2c_block_data(MPU6050_ADDR, GYRO_XOUT_H, 6)
        x = (data[0] << 8 | data[1]) / 131.0
        y = (data[2] << 8 | data[3]) / 131.0
        z = (data[4] << 8 | data[5]) / 131.0
        return x, y, z
    except IOError as e:
        logging.error(f"Gyro read error: {e}")
        return None, None, None


def set_pwm(axis, duty):
    if axis == 'x':
        dev = pwm_devices[0]
    elif axis == 'y':
        dev = pwm_devices[1]
    elif axis == 'z':
        dev = pwm_devices[2]
    else:
        return
    try:
        dev.value = abs(duty) / 100.0
    except Exception as e:
        logging.error(f"PWM set error on {axis}: {e}")


def control_loop():
    global running
    integral = {'x': 0.0, 'y': 0.0, 'z': 0.0}
    last_time = time.time()
    while running:
        now = time.time()
        dt = now - last_time
        last_time = now
        if dt <= 0:
            continue
        gx, gy, gz = read_gyro()
        if gx is None:
            time.sleep(0.01)
            continue
        integral['x'] += gx * dt
        integral['y'] += gy * dt
        integral['z'] += gz * dt
        pwm_x = integral['x'] * kp['x']
        pwm_y = integral['y'] * kp['y']
        pwm_z = integral['z'] * kp['z']
        set_pwm('x', pwm_x)
        set_pwm('y', pwm_y)
        set_pwm('z', pwm_z)
        logging.info(f"Angular Displacement: X={integral['x']:.2f}, Y={integral['y']:.2f}, Z={integral['z']:.2f}")
        logging.info(f"PWM Output: X={pwm_x:.2f}, Y={pwm_y:.2f}, Z={pwm_z:.2f}")
        time.sleep(0.01)


def command_loop():
    global running
    while running:
        try:
            cmd = input()
        except EOFError:
            break
        if not running:
            break
        if cmd.lower() == 'quit':
            running = False
            break
        parts = cmd.split()
        if len(parts) != 3:
            print("Usage: <axis>kp <value> (e.g., xkp 1.0)")
            continue
        axis = parts[0].lower()
        try:
            val = float(parts[2])
        except ValueError:
            print("Value must be a number.")
            continue
        if axis in kp:
            kp[axis] = val
            print(f"{axis.upper()} Kp set to {val}")
        else:
            print("Invalid axis.")


def cleanup():
    global running
    running = False
    for dev in pwm_devices:
        try:
            dev.value = 0
            dev.close()
        except Exception:
            pass
    try:
        if bus is not None:
            bus.close()
    except Exception:
        pass
    logging.info("Program terminated.")


def signal_handler(signum, frame):
    global running
    running = False


def main():
    global pwm_devices
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        pwm_devices = [
            PWMOutputDevice(17, frequency=50, initial_value=0),
            PWMOutputDevice(18, frequency=50, initial_value=0),
            PWMOutputDevice(27, frequency=50, initial_value=0),
        ]
    except Exception as e:
        logging.error(f"GPIO init failed: {e}")
        sys.exit(1)
    init_mpu6050()
    t_control = threading.Thread(target=control_loop, daemon=True)
    t_command = threading.Thread(target=command_loop, daemon=True)
    t_control.start()
    t_command.start()
    try:
        while running:
            time.sleep(0.1)
    except KeyboardInterrupt:
        pass
    finally:
        cleanup()


if __name__ == '__main__':
    main()

