        integral['y'] += gy * dt
        integral['z'] += gz * dt
        pwm_x = integral['x'] * kp['x']
        pwm_y = integral['y'] * kp['y']
        pwm_z = integral['z'] * kp['z']
        set_pwm('x', pwm_x)
        set_pwm('y', pwm_y)
        set_pwm('z', pwm_z)
        logging.info(f"Angular Displacement: X={integral['x']:.2f}, Y={integral['y']:.2f}, Z={integral['z']:.2f}")
        logging.info(f"PWM Output: X={pwm_x:.2f}, Y={pwm_y:.2f}, Z={pwm_z:.2f}")
        time.sleep(0.01)


def command_loop():
    global running
    while running:
        try:
            cmd = input()
        except EOFError:
            break
        if not running:
            break
        if cmd.lower() == 'quit':
            running = False
            break
        parts = cmd.split()
        if len(parts) != 3:
            print("Usage: <axis>kp <value> (e.g., xkp 1.0)")
            continue
        axis = parts[0].lower()
        try:
            val = float(parts[2])
        except ValueError:
            print("Value must be a number.")
            continue
        if axis in kp:
            kp[axis] = val
            print(f"{axis.upper()} Kp set to {val}")
        else:
            print("Invalid axis.")


def cleanup():
    global running
    running = False
    for dev in pwm_devices:
        try:
            dev.value = 0
            dev.close()
        except Exception:
            pass
    try:
        if bus is not None:
            bus.close()
    except Exception:
        pass
    logging.info("Program terminated.")


def signal_handler(signum, frame):
    global running
    running = False


def main():
    global pwm_devices
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    try:
        pwm_devices = [
            PWMOutputDevice(17, frequency=50, initial_value=0),
            PWMOutputDevice(18, frequency=50, initial_value=0),
            PWMOutputDevice(27, frequency=50, initial_value=0),
        ]
    except Exception as e:
        logging.error(f"GPIO init failed: {e}")
        sys.exit(1)
    init_mpu6050()
    t_control = threading.Thread(target=control_loop, daemon=True)
    t_command = threading.Thread(target=command_loop, daemon=True)
    t_control.start()
    t_command.start()
    try:
        while running:
            time.sleep(0.1)
    except KeyboardInterrupt:
        pass
    finally:
        cleanup()


if __name__ == '__main__':
    main()

