import RPi.GPIO as GPIO
import time
import datetime
import sys

# Configuration
PIR_PIN = 4
DEBOUNCE_SECONDS = 60
FEEDING_START_TIME = "07:00"
FEEDING_END_TIME = "18:00"
LAST_FEEDING_TIME_FILE = "last_feeding_time.txt"

def setup_gpio():
    """Initialize GPIO mode and PIR pin with internal pull-down."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PIR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)

def is_feeding_time(now):
    """Return True if current time is within feeding hours."""
    try:
        start_time = datetime.datetime.strptime(FEEDING_START_TIME, "%H:%M").time()
        end_time = datetime.datetime.strptime(FEEDING_END_TIME, "%H:%M").time()
        return start_time <= now.time() <= end_time
    except Exception as e:
        print(f"Time check error: {e}")
        return False

def load_last_feeding_time():
    """Load last feeding time from file, or return None if file missing."""
    try:
        with open(LAST_FEEDING_TIME_FILE, "r") as f:
            return f.read().strip()
    except FileNotFoundError:
        return None
    except Exception as e:
        print(f"Error loading last feeding time: {e}")
        return None

def save_last_feeding_time(timestamp):
    """Save last feeding time to file."""
    try:
        with open(LAST_FEEDING_TIME_FILE, "w") as f:
            f.write(timestamp)
    except Exception as e:
        print(f"Error saving last feeding time: {e}")

def feeder_on():
    """Simulate feeder activation."""
    print("Feeder activated")

def main():
    setup_gpio()
    last_feeding_time = load_last_feeding_time()
    last_feeding_time_obj = None
    if last_feeding_time:
        try:
            last_feeding_time_obj = datetime.datetime.strptime(last_feeding_time, "%Y-%m-%d %H:%M:%S")
        except Exception as e:
            print(f"Invalid last feeding time format: {e}")
            last_feeding_time_obj = None

    try:
        while True:
            try:
                motion_detected = GPIO.input(PIR_PIN)
            except Exception as e:
                print(f"GPIO read error: {e}")
                time.sleep(1)
                continue

            if motion_detected:
                timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                print(f"Motion detected at {timestamp}")

                if is_feeding_time(datetime.datetime.now()):
                    if last_feeding_time_obj is None or (datetime.datetime.now() - last_feeding_time_obj).total_seconds() >= DEBOUNCE_SECONDS:
                        print("Feeding initiated at", timestamp)
                        feeder_on()
                        save_last_feeding_time(timestamp)
                        last_feeding_time_obj = datetime.datetime.now()
                    else:
                        print("Not feeding time or recently fed.")
                else:
                    print("Not feeding time.")

            time.sleep(1)

    except KeyboardInterrupt:
        print("Exiting program...")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        GPIO.cleanup()
        print("GPIO cleaned up.")

if __name__ == "__main__":
    main()

