#!/usr/bin/python3
"""
Raspberry Pi driver for the Adafruit DC Motor HAT (PCA9685) over I2C.

Uses the Adafruit_MotorHAT_SG90 library (adafruit_motorhat_sg90).
"""

import atexit
import signal
import sys
import time

try:
    from adafruit_motorhat_sg90 import AdafruitMotorHat as _AdafruitMotorHat
except ImportError as exc:
    print(f"Failed to import adafruit_motorhat_sg90: {exc}", file=sys.stderr)
    sys.exit(1)


class DCMotorHATExtra:
    """Extended AdafruitMotorHat wrapper with motor-level control."""

    MOTOR_NUMBERS = frozenset(range(1, 5))

    def __init__(self, i2c_bus=1, i2c_address=0x60, pwm_frequency=60):
        self._motors = {}
        self._closed = False
        self._pwm_frequency = pwm_frequency
        self._hat = None

        try:
            self._hat = _AdafruitMotorHat(
                i2c_bus=i2c_bus,
                i2c_address=i2c_address,
                pwm_frequency=pwm_frequency,
            )
        except Exception as exc:
            print(f"Error initializing AdafruitMotorHat at 0x{i2c_address:02X}: {exc}", file=sys.stderr)
            raise

        atexit.register(self.close)

    def get_status(self, motor_number):
        """Return the current status of a motor."""
        if motor_number not in self._motors:
            return None
        motor = self._motors[motor_number]
        return {
            "motor_number": motor_number,
            "pwm_frequency": motor.get_pwm_freq(),
            "invert": motor.invert,
            "last_duty_cycle": motor._last_duty_cycle,
        }

    def get_pwm_freq(self, motor_number):
        """Return the current PWM frequency for a motor."""
        if motor_number not in self._motors:
            return None
        return self._motors[motor_number].get_pwm_freq()

    def set_pwm_freq(self, motor_number, frequency):
        """Set the PWM frequency for a motor."""
        if motor_number not in self._motors:
            return None
        try:
            self._motors[motor_number].set_pwm_freq(frequency)
            return self._motors[motor_number].get_pwm_freq()
        except Exception as exc:
            print(f"Error setting PWM frequency for motor {motor_number}: {exc}", file=sys.stderr)
            return None

    def get_motor(self, motor_number):
        """Return the DCMotor instance for the given motor number."""
        if motor_number not in self._motors:
            raise ValueError(f"Invalid motor number: {motor_number}. Must be one of {sorted(self.MOTOR_NUMBERS)}.")
        return self._motors[motor_number]

    def close(self):
        """Release all motors and close the I2C interface."""
        if self._closed:
            return
        self._closed = True
        for motor_number in list(self._motors):
            try:
                self._motors[motor_number].stop()
            except Exception as exc:
                print(f"Error stopping motor {motor_number}: {exc}", file=sys.stderr)
            del self._motors[motor_number]
        if self._hat is not None:
            try:
                self._hat.close()
            except Exception as exc:
                print(f"Error closing AdafruitMotorHat: {exc}", file=sys.stderr)


class DCMotor:
    """Single DC motor driver with configurable frequency and direction."""

    def __init__(self, motor_hat, motor_number, pwm_frequency=60, invert=False):
        if motor_number not in motor_hat.MOTOR_NUMBERS:
            raise ValueError(f"Invalid motor number: {motor_number}. Must be one of {sorted(motor_hat.MOTOR_NUMBERS)}.")
        self._motor_hat = motor_hat
        self._motor_number = motor_number
        self._invert = invert
        self._pwm_frequency = pwm_frequency
        self._last_duty_cycle = 0
        self._motor = None

        try:
            self._motor = motor_hat.get_motor(motor_number)
            self._motor.set_pwm_freq(pwm_frequency)
        except Exception as exc:
            print(f"Error initializing motor {motor_number}: {exc}", file=sys.stderr)
            raise

    @property
    def invert(self):
        return self._invert

    @property
    def pwm_frequency(self):
        return self._pwm_frequency

    def set_pwm_freq(self, frequency):
        """Set the PWM frequency and return the new value."""
        self._pwm_frequency = frequency
        try:
            self._motor.set_pwm_freq(frequency)
            return self._motor.get_pwm_freq()
        except Exception as exc:
            print(f"Error setting PWM frequency for motor {self._motor_number}: {exc}", file=sys.stderr)
            return None

    def get_pwm_freq(self):
        """Return the current PWM frequency."""
        return self._motor.get_pwm_freq()

    def set_dc(self, duty_cycle):
        """
        Set the motor duty cycle.

        Args:
            duty_cycle: -255 (full reverse) to 255 (full forward).
                        Values outside this range are clamped.
        """
        if duty_cycle is None:
            return

        duty_cycle = max(-255, min(255, int(duty_cycle)))

        if duty_cycle == self._last_duty_cycle:
            return

        try:
            if duty_cycle == 0:
                self._motor.stop()
            else:
                direction = 1 if (duty_cycle > 0) ^ self._invert else -1
                self._motor.set_duty_cycle(direction, abs(duty_cycle))
            self._last_duty_cycle = duty_cycle
        except Exception as exc:
            print(f"Error setting duty cycle for motor {self._motor_number}: {exc}", file=sys.stderr)

    def stop(self):
        """Stop the motor immediately."""
        try:
            self._motor.stop()
            self._last_duty_cycle = 0
        except Exception as exc:
            print(f"Error stopping motor {self._motor_number}: {exc}", file=sys.stderr)


_hat = None


def _signal_handler(signum, frame):
    print(f"\nReceived signal {signum}, shutting down...", file=sys.stderr)
    if _hat is not None:
        _hat.close()
    sys.exit(0)


def main():
    global _hat
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _hat = DCMotorHATExtra(i2c_bus=1, i2c_address=0x60, pwm_frequency=60)
    except Exception as exc:
        print(f"Failed to initialize Motor HAT: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        motor = DCMotor(_hat, 1, pwm_frequency=60, invert=False)
    except Exception as exc:
        print(f"Failed to initialize motor 1: {exc}", file=sys.stderr)
        _hat.close()
        sys.exit(1)

    try:
        print("Ramping motor 1 forward...")
        for dc in range(0, 256, 5):
            motor.set_dc(dc)
            time.sleep(0.05)

        print("Ramping motor 1 backward...")
        for dc in range(0, -256, -5):
            motor.set_dc(dc)
            time.sleep(0.05)

        print("Stopping motor 1...")
        motor.stop()
    except Exception as exc:
        print(f"Runtime error: {exc}", file=sys.stderr)
    finally:
        _hat.close()


if __name__ == "__main__":
    main()

