            raise ValueError(f"Invalid motor number: {motor_number}. Must be one of {sorted(motor_hat.MOTOR_NUMBERS)}.")
        self._motor_hat = motor_hat
        self._motor_number = motor_number
        self._invert = invert
        self._pwm_frequency = pwm_frequency
        self._last_duty_cycle = 0
        self._motor = None

        try:
            self._motor = motor_hat.get_motor(motor_number)
            self._motor.set_pwm_freq(pwm_frequency)
        except Exception as exc:
            print(f"Error initializing motor {motor_number}: {exc}", file=sys.stderr)
            raise

    @property
    def invert(self):
        return self._invert

    @property
    def pwm_frequency(self):
        return self._pwm_frequency

    def set_pwm_freq(self, frequency):
        """Set the PWM frequency and return the new value."""
        self._pwm_frequency = frequency
        try:
            self._motor.set_pwm_freq(frequency)
            return self._motor.get_pwm_freq()
        except Exception as exc:
            print(f"Error setting PWM frequency for motor {self._motor_number}: {exc}", file=sys.stderr)
            return None

    def get_pwm_freq(self):
        """Return the current PWM frequency."""
        return self._motor.get_pwm_freq()

    def set_dc(self, duty_cycle):
        """
        Set the motor duty cycle.

        Args:
            duty_cycle: -255 (full reverse) to 255 (full forward).
                        Values outside this range are clamped.
        """
        if duty_cycle is None:
            return

        duty_cycle = max(-255, min(255, int(duty_cycle)))

        if duty_cycle == self._last_duty_cycle:
            return

        try:
            if duty_cycle == 0:
                self._motor.stop()
            else:
                direction = 1 if (duty_cycle > 0) ^ self._invert else -1
                self._motor.set_duty_cycle(direction, abs(duty_cycle))
            self._last_duty_cycle = duty_cycle
        except Exception as exc:
            print(f"Error setting duty cycle for motor {self._motor_number}: {exc}", file=sys.stderr)

    def stop(self):
        """Stop the motor immediately."""
        try:
            self._motor.stop()
            self._last_duty_cycle = 0
        except Exception as exc:
            print(f"Error stopping motor {self._motor_number}: {exc}", file=sys.stderr)


_hat = None


def _signal_handler(signum, frame):
    print(f"\nReceived signal {signum}, shutting down...", file=sys.stderr)
    if _hat is not None:
        _hat.close()
    sys.exit(0)


def main():
    global _hat
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _hat = DCMotorHATExtra(i2c_bus=1, i2c_address=0x60, pwm_frequency=60)
    except Exception as exc:
        print(f"Failed to initialize Motor HAT: {exc}", file=sys.stderr)
        sys.exit(1)

