import atexit


class MotorError(Exception):
    """Custom exception for motor-related errors."""
    pass


class Motor:
    """
    A class to control a DC motor via a PWM pin on a Raspberry Pi.

    The driver library is expected to expose:
        - set_PWM_dutycycle(pin, duty)  -> returns 0 on success
        - set_PWM_frequency(pin, freq) -> returns 0 on success
    """

    def __init__(self, driver, pin, frequency=1000):
        """
        Initialise the motor.

        Args:
            driver:      A connected driver library.pi instance.
            pin:         BCM pin number connected to the motor driver PWM input.
            frequency:   PWM frequency in Hz (default 1000).

        Raises:
            MotorError: If the driver library is invalid or the pin cannot be set.
        """
        if driver is None:
            raise MotorError("Driver library instance is None.")
        if not hasattr(driver, 'set_PWM_dutycycle') or not callable(getattr(driver, 'set_PWM_dutycycle')):
            raise MotorError("Driver library does not expose set_PWM_dutycycle().")
        if not hasattr(driver, 'set_PWM_frequency') or not callable(getattr(driver, 'set_PWM_frequency')):
            raise MotorError("Driver library does not expose set_PWM_frequency().")

        self.driver = driver
        self.pin = pin
        self.frequency = frequency
        self.duty_cycle = 0
        self._closed = False

        try:
            self.driver.set_PWM_frequency(self.pin, self.frequency)
            self.set_duty_cycle(0)
        except Exception as e:
            raise MotorError(f"Failed to initialise PWM on pin {self.pin}: {e}") from e

        atexit.register(self.stop)

    def set_frequency(self, frequency):
        """
        Set the PWM frequency.

        Args:
            frequency: Frequency in Hz.

        Raises:
            MotorError: If the frequency cannot be set or is invalid.
        """
        if self._closed:
            raise MotorError("Motor has been closed; cannot set frequency.")
        try:
            result = self.driver.set_PWM_frequency(self.pin, frequency)
            if result != 0:
                raise MotorError(f"set_PWM_frequency returned error code {result}.")
            self.frequency = frequency
        except Exception as e:
            raise MotorError(f"Failed to set frequency to {frequency} Hz: {e}") from e

    def set_duty_cycle(self, duty_cycle):
        """
        Set the PWM duty cycle.

        Args:
            duty_cycle: Duty cycle as an integer 0-255.

        Raises:
            MotorError: If the duty cycle is out of bounds or cannot be set.
        """
        if self._closed:
            raise MotorError("Motor has been closed; cannot set duty cycle.")
        if not isinstance(duty_cycle, int):
            raise MotorError("Duty cycle must be an integer.")
        if not 0 <= duty_cycle <= 255:
            raise MotorError("Duty cycle must be between 0 and 255.")

        try:
            result = self.driver.set_PWM_dutycycle(self.pin, duty_cycle)
            if result != 0:
                raise MotorError(f"set_PWM_dutycycle returned error code {result}.")
            self.duty_cycle = duty_cycle
        except Exception as e:
            raise MotorError(f"Failed to set duty cycle to {duty_cycle}: {e}") from e

    def stop(self):
        """Stop the motor by setting duty cycle to 0."""
        if self._closed:
            return
        try:
            self.set_duty_cycle(0)
        except MotorError:
            pass

    def close(self):
        """Explicitly stop the motor and release resources."""
        if self._closed:
            return
        self.stop()
        self._closed = True

    def __del__(self):
        """Ensure stop() is called on object destruction."""
        try:
            self.stop()
        except Exception:
            pass

