import signal
import sys
import json
from http.server import BaseHTTPRequestHandler, HTTPServer

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or a Raspberry Pi environment.")
    sys.exit(1)

RELAY_PIN = 23
HOST_NAME = "0.0.0.0"
PORT_NUMBER = 5000

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(RELAY_PIN, GPIO.OUT, initial=GPIO.LOW)


def cleanup_gpio():
    try:
        GPIO.output(RELAY_PIN, GPIO.LOW)
    except Exception:
        pass
    GPIO.cleanup()


class RelayHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        if self.path != "/relay":
            self.send_error(404, "Not Found")
            return

        content_length = int(self.headers.get("Content-Length", 0))
        if content_length == 0:
            self.send_error(400, "Invalid request: empty body")
            return

        try:
            body = self.rfile.read(content_length).decode("utf-8")
            data = json.loads(body)
        except (json.JSONDecodeError, UnicodeDecodeError):
            self.send_error(400, "Invalid request: invalid JSON")
            return

        if "state" not in data:
            self.send_error(400, "Invalid request: missing 'state' key")
            return

        state = data["state"]
        if state not in ("on", "off"):
            self.send_error(400, "Invalid request: 'state' must be 'on' or 'off'")
            return

        try:
            GPIO.output(RELAY_PIN, GPIO.HIGH if state == "on" else GPIO.LOW)
        except Exception as e:
            self.send_error(500, f"GPIO error: {e}")
            return

        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.end_headers()
        self.wfile.write(json.dumps({"status": "Relay state changed"}).encode("utf-8"))

    def send_error(self, code, message):
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.end_headers()
        self.wfile.write(json.dumps({"error": message}).encode("utf-8"))

    def log_message(self, format, *args):
        sys.stderr.write("%s - %s\n" % (self.client_address[0], format % args))


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        setup_gpio()
    except Exception as e:
        print(f"GPIO initialization failed: {e}")
        sys.exit(1)

    server = HTTPServer((HOST_NAME, PORT_NUMBER), RelayHandler)
    print(f"Server running on http://{HOST_NAME}:{PORT_NUMBER}/relay")

    try:
        while _running:
            server.handle_request()
    finally:
        server.server_close()
        cleanup_gpio()
        print("Server stopped.")


if __name__ == "__main__":
    main()

