import sys
from typing import Dict, List, Optional

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

PUMP_PIN = 20
LIGHT_PIN = 21


class ActuatorController:
    """Controls a nutrient pump and grow light via GPIO outputs."""

    def __init__(self, pump_pin: int, light_pin: int):
        self.pump: Optional[OutputDevice] = None
        self.light: Optional[OutputDevice] = None
        try:
            self.pump = OutputDevice(pump_pin)
            self.light = OutputDevice(light_pin)
            self.pump.off()
            self.light.off()
            logging.info("ActuatorController initialized on pump=BCM%d, light=BCM%d", pump_pin, light_pin)
        except GPIOZeroError as exc:
            logging.error("Failed to initialize GPIO devices: %s", exc)
            self.close()
            raise

    def turn_pump_on(self) -> None:
        if self.pump is not None:
            self.pump.on()
            logging.info("Pump turned ON")

    def turn_pump_off(self) -> None:
        if self.pump is not None:
            self.pump.off()
            logging.info("Pump turned OFF")

    def toggle_light(self) -> None:
        if self.light is not None:
            self.light.toggle()
            state = "ON" if self.light.is_active else "OFF"
            logging.info("Light toggled to %s", state)

    def close(self) -> None:
        """Safely turn off both actuators and release resources."""
        for name, dev in (("pump", self.pump), ("light", self.light)):
            if dev is not None:
                try:
                    dev.off()
                    dev.close()
