import signal
import sys
import time

import RPi.GPIO as GPIO

LED_PIN = 14
SERVO_PIN = 18
BUTTON_PIN = 15

PWM_FREQ = 50
DEBOUNCE_DELAY = 0.1
ANGLE_INCREMENT = 20

led_pwm = None
servo_pwm = None


def cleanup(signum=None, frame=None):
    """Release all GPIO and PWM resources on exit."""
    global led_pwm, servo_pwm
    if led_pwm is not None:
        try:
            led_pwm.stop()
        except Exception:
            pass
        led_pwm = None
    if servo_pwm is not None:
        try:
            servo_pwm.stop()
        except Exception:
            pass
        servo_pwm = None
    try:
        GPIO.cleanup()
    except Exception:
        pass
    if signum is not None:
        sys.exit(0)


def angle_to_duty(angle):
    """Map a servo angle (0–180) to a PWM duty cycle for the SG90/MG996R."""
    return 2.5 + (angle / 18.0)


def main():
    global led_pwm, servo_pwm

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)

    GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(BUTTON_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)

    try:
        led_pwm = GPIO.PWM(LED_PIN, PWM_FREQ)
        led_pwm.start(0)
    except Exception as exc:
        print(f"Failed to initialize LED PWM on GPIO{LED_PIN}: {exc}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    try:
        servo_pwm = GPIO.PWM(SERVO_PIN, PWM_FREQ)
        servo_pwm.start(0)
    except Exception as exc:
        print(f"Failed to initialize servo PWM on GPIO{SERVO_PIN}: {exc}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    current_angle = 5
    servo_pwm.ChangeDutyCycle(angle_to_duty(current_angle))

    button_pressed = False

    try:
        while True:
            if GPIO.input(BUTTON_PIN) == GPIO.LOW:
                if not button_pressed:
                    button_pressed = True
                    print("Button pressed")
                    GPIO.output(LED_PIN, GPIO.HIGH)
                    time.sleep(DEBOUNCE_DELAY)

                    current_angle += ANGLE_INCREMENT
                    if current_angle > 180:
                        current_angle = 5
                    servo_pwm.ChangeDutyCycle(angle_to_duty(current_angle))
            else:
                if button_pressed:
                    button_pressed = False
                    GPIO.output(LED_PIN, GPIO.LOW)
                    print("Button released")

            time.sleep(0.02)
    except KeyboardInterrupt:
        pass
    finally:
        cleanup()


if __name__ == "__main__":
    signal.signal(signal.SIGTERM, cleanup)
    main()

