SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
READ_INTERVAL = 1
ALARM_PIN = 18
RADIATION_THRESHOLD = 50.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_gpio(pin):
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)

def read_radiation_level(ser):
    try:
        raw = ser.readline()
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None
    if not raw:
        return None
    line = raw.decode('ascii', errors='replace').strip()
    if not line:
        return None
    try:
        return float(line)
    except ValueError:
        print(f"Non-numeric data received: {line!r}", file=sys.stderr)
        return None

def control_alarm(pin, level, threshold):
    if level > threshold:
        GPIO.output(pin, GPIO.HIGH)
        return True
    GPIO.output(pin, GPIO.LOW)
    return False

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    initialize_gpio(ALARM_PIN)
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        GPIO.cleanup()
        sys.exit(1)
    alarm_active = False
    try:
        while _running:
            level = read_radiation_level(ser)
            if level is not None:
                print(f"Radiation Level: {level:.2f} µSv/h")
                new_alarm = control_alarm(ALARM_PIN, level, RADIATION_THRESHOLD)
                if new_alarm != alarm_active:
                    print("Alarm triggered!" if new_alarm else "Alarm cleared.")
                    alarm_active = new_alarm
            time.sleep(READ_INTERVAL)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        try:
            ser.close()
        except Exception:
            pass
        GPIO.cleanup()
        print("GPIO cleaned up. Exiting.")

if __name__ == "__main__":
    main()

