import serial
import time
import signal
import sys

# Constants for GPS module
GPS_PORT = "/dev/serial0"
GPS_BAUDRATE = 9600
GPS_TIMEOUT = 1  # seconds

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False

def _open_gps_port():
    """Open the GPS serial port with error handling."""
    try:
        return serial.Serial(
            port=GPS_PORT,
            baudrate=GPS_BAUDRATE,
            timeout=GPS_TIMEOUT,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
        )
    except serial.SerialException as e:
        print(f"Error opening GPS port {GPS_PORT}: {e}", file=sys.stderr)
        return None
    except OSError as e:
        print(f"OS error opening GPS port {GPS_PORT}: {e}", file=sys.stderr)
        return None

def _parse_gprmc(data):
    """
    Parse a $GPRMC sentence.
    Returns (latitude, longitude) as floats, or (None, None) if invalid.
    """
    if not data.startswith("$GPRMC"):
        return None, None

    fields = data.split(",")
    if len(fields) < 10:
        return None, None

    # $GPRMC,<time>,<status>,<lat>,<N/S>,<lon>,<E/W>,<speed>,<course>,<date>,<magvar>,<E/W>
    status = fields[2]
    if status != "A":
        return None, None

    lat_raw, lat_dir = fields[3], fields[4]
    lon_raw, lon_dir = fields[5], fields[6]

    if not lat_raw or not lon_raw:
        return None, None

    try:
        lat = _decode_coordinate(lat_raw, lat_dir)
        lon = _decode_coordinate(lon_raw, lon_dir)
    except ValueError:
        return None, None

    return lat, lon

def _decode_coordinate(raw, direction):
    """Convert ddmm.mmmm to decimal degrees."""
    if not raw or not direction:
        raise ValueError("Empty coordinate or direction")
    dot = raw.find(".")
    if dot == -1:
        raise ValueError("Coordinate format invalid")
    deg_len = dot - 2
    if deg_len < 1:
        raise ValueError("Coordinate format invalid")
    degrees = int(raw[:deg_len])
    minutes = float(raw[deg_len:])
    decimal = degrees + minutes / 60.0
    if direction in ("S", "W"):
        decimal = -decimal
    return decimal

def main():
    """Main loop: open port, read GPRMC sentences, print coordinates."""
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    gps_serial = _open_gps_port()
    if gps_serial is None:
        sys.exit(1)

    try:
        while _running:
            try:
                raw_line = gps_serial.readline()
            except serial.SerialException as e:
                print(f"Serial read error: {e}", file=sys.stderr)
                time.sleep(1)
                continue

            if not raw_line:
                # Timeout with no data
                continue

            try:
                line = raw_line.decode("utf-8", errors="ignore").strip()
            except Exception as e:
                print(f"Decode error: {e}", file=sys.stderr)
                continue

            if not line:
                continue

            lat, lon = _parse_gprmc(line)
            if lat is not None and lon is not None:
                print(f"Latitude: {lat:.6f}, Longitude: {lon:.6f}")

            time.sleep(1)

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if gps_serial and gps_serial.is_open:
            gps_serial.close()
            print("GPS port closed.")

if __name__ == "__main__":
    main()

