import serial
import time
import threading
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'water_flow_log.txt'

stop_event = threading.Event()


def read_flow_rate(ser):
    """Read one line from the serial port and return a float flow rate in L/min."""
    raw = ser.readline()
    if not raw:
        return None
    text = raw.decode('ascii', errors='replace').strip()
    if not text:
        return None
    return float(text)


def log_flow_rate(flow_rate):
    """Append a timestamped flow-rate line to the log file."""
    timestamp = datetime.now().isoformat(timespec='seconds')
    line = f"{timestamp} - Flow Rate: {flow_rate} L/min\n"
    try:
        with open(LOG_FILE, 'a', encoding='utf-8') as f:
            f.write(line)
    except OSError as exc:
        print(f"Error writing to log file: {exc}", file=sys.stderr)


def serial_reader(ser):
    """Continuously read flow rates until stop_event is set."""
    while not stop_event.is_set():
        try:
            flow_rate = read_flow_rate(ser)
            if flow_rate is not None:
                print(f"Flow Rate: {flow_rate} L/min")
                log_flow_rate(flow_rate)
            stop_event.wait(1.0)
        except ValueError:
            print("Invalid data received from sensor (non-numeric). Skipping...", file=sys.stderr)
            stop_event.wait(1.0)
        except OSError as exc:
            print(f"Serial I/O error: {exc}", file=sys.stderr)
            stop_event.set()


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM by setting the stop event."""
    print(f"\nReceived signal {signum}, shutting down...")
    stop_event.set()


def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    except serial.SerialException as exc:
        print(f"Failed to open serial port {SERIAL_PORT}: {exc}", file=sys.stderr)
        sys.exit(1)

    reader_thread = threading.Thread(target=serial_reader, args=(ser,), daemon=True)
    reader_thread.start()

    try:
        while not stop_event.is_set():
            stop_event.wait(0.5)
    except KeyboardInterrupt:
        stop_event.set()
    finally:
        stop_event.set()
        reader_thread.join(timeout=2.0)
        ser.close()
        print("Serial port closed. Exiting.")


if __name__ == '__main__':
    main()

