import serial
import time
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'health_readings_log.txt'
READ_INTERVAL = 5

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def log_data(hr, spo2, log_file):
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - Heart Rate: {hr} bpm, SpO2: {spo2} %'
    try:
        with open(log_file, 'a', encoding='utf-8') as f:
            f.write(log_entry + '\n')
    except OSError as e:
        print(f'Error writing to log file: {e}', file=sys.stderr)

def main():
    global _running
    signal.signal(signal.SIGTERM, _handle_signal)
    signal.signal(signal.SIGINT, _handle_signal)

    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
    except serial.SerialException as e:
        print(f'Error opening serial port: {e}', file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                raw = ser.readline()
                if not raw:
                    print('No data received (timeout).', file=sys.stderr)
                else:
                    data = raw.decode('ascii', errors='replace').strip()
                    if not data:
                        print('Empty line received.', file=sys.stderr)
                        continue
                    parts = data.split(',')
                    if len(parts) != 2:
                        print(f'Invalid data format: {data!r}', file=sys.stderr)
                        log_data(data, 'INVALID', LOG_FILE)
