import serial
import signal
import sys
import logging
from dataclasses import dataclass
from typing import Optional

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)


@dataclass
class GPSReading:
    latitude: Optional[float] = None
    longitude: Optional[float] = None
    altitude: Optional[float] = None
    satellite_count: Optional[int] = None


class GPSReader:
    def __init__(self, port: str = "/dev/serial0", baudrate: int = 9600, timeout: float = 1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial_connection: Optional[serial.Serial] = None
        self._running = False

    def connect(self) -> bool:
        try:
            self.serial_connection = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout,
            )
            logger.info(
                "Connected to GPS on %s at %d baud (8N1, timeout %.1fs)",
                self.port, self.baudrate, self.timeout,
            )
            return True
        except serial.SerialException as e:
            logger.error("Failed to open serial port %s: %s", self.port, e)
            self.serial_connection = None
            return False
        except Exception as e:
            logger.error("Unexpected error opening %s: %s", self.port, e)
            self.serial_connection = None
            return False

    def disconnect(self) -> None:
        if self.serial_connection is not None:
            try:
                if self.serial_connection.is_open:
                    self.serial_connection.close()
                    logger.info("Serial port %s closed.", self.port)
            except serial.SerialException as e:
                logger.error("Error closing serial port %s: %s", self.port, e)
            except Exception as e:
                logger.error("Unexpected error closing %s: %s", self.port, e)
            finally:
                self.serial_connection = None

    def _verify_checksum(self, sentence: str) -> bool:
        if "*" not in sentence:
            return False
        try:
            body, _, csum = sentence.partition("*")
            if not body.startswith("$"):
                return False
            expected = int(csum[:2], 16)
            calculated = 0
            for ch in body[1:]:
                calculated ^= ord(ch)
            return calculated == expected
        except (ValueError, IndexError):
            return False

    def _parse_gga(self, sentence: str) -> Optional[GPSReading]:
        if not sentence.startswith("$GPGGA"):
            return None
        if not self._verify_checksum(sentence):
            logger.warning("Checksum verification failed for sentence: %s", sentence)
            return None
        fields = sentence.split(",")
        if len(fields) < 15:
            logger.warning("Incomplete GPGGA sentence (expected >=15 fields): %s", sentence)
            return None
        try:
            utc_time = fields[1]
            lat_raw = fields[2]
            lat_dir = fields[3]
            lon_raw = fields[4]
            lon_dir = fields[5]
            fix_quality = int(fields[6])
            sat_count = int(fields[7])
            altitude = float(fields[9]) if fields[9] else None
            if fix_quality < 1 or sat_count < 0:
                logger.warning("Invalid fix quality (%d) or satellite count (%d): %s", fix_quality, sat_count, sentence)
                return None
            if not lat_raw or not lon_raw:
                logger.warning("Empty latitude or longitude field in GPGGA: %s", sentence)
                return None
            latitude = self._convert_to_decimal(lat_raw, lat_dir)
            longitude = self._convert_to_decimal(lon_raw, lon_dir)
            if latitude is None or longitude is None:
                logger.warning("Failed to convert coordinates in GPGGA: %s", sentence)
                return None
            return GPSReading(latitude=latitude, longitude=longitude, altitude=altitude, satellite_count=sat_count)
        except (ValueError, IndexError) as e:
            logger.error("Error parsing GPGGA sentence: %s - %s", sentence, e)
            return None

    @staticmethod
    def _convert_to_decimal(raw: str, direction: str) -> Optional[float]:
        if not raw:
            return None
        try:
            degrees = int(float(raw) // 100)
            minutes = float(raw) - (degrees * 100)
            decimal = degrees + (minutes / 60.0)
            if direction in ("S", "W"):
                decimal = -decimal
            return decimal
        except (ValueError, TypeError) as e:
            logger.error("Error converting coordinates: %s - %s", raw, e)
            return None

    def read_gps_data(self) -> Optional[GPSReading]:
        if self.serial_connection is None or not self.serial_connection.is_open:
            logger.error("Serial connection not established. Call connect() first.")
            return None
        try:
            raw = self.serial_connection.readline()
            if not raw:
                return None
            line = raw.decode("utf-8", errors="ignore").strip()
            if not line:
                return None
            return self._parse_gga(line)
        except serial.SerialException as e:
            logger.error("Serial read error: %s", e)
            return None
        except Exception as e:
            logger.error("Unexpected read error: %s", e)
            return None

    def run(self) -> None:
        if not self.connect():
            logger.error("Failed to connect to GPS. Exiting.")
            return
        self._running = True
        try:
            while self._running:
                reading = self.read_gps_data()
                if reading is not None:
                    logger.info(
                        "GPS Reading - Latitude: %.6f, Longitude: %.6f, Altitude: %s, Satellites: %d",
                        reading.latitude, reading.longitude,
                        reading.altitude if reading.altitude is not None else "N/A",
                        reading.satellite_count if reading.satellite_count is not None else 0,
                    )
        except KeyboardInterrupt:
            logger.info("KeyboardInterrupt received. Shutting down...")
        finally:
            self.disconnect()

    def stop(self) -> None:
        self._running = False


def main() -> None:
    gps_reader = GPSReader()

    def signal_handler(signum, frame):
        logger.info("Signal %d received. Initiating shutdown...", signum)
        gps_reader.stop()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        gps_reader.run()
    except Exception as e:
        logger.error("Fatal error in main loop: %s", e)
    finally:
        gps_reader.disconnect()


if __name__ == "__main__":
    main()

