import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'access_log.txt'

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def log_access(tag_id):
    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
    log_entry = f'{timestamp} - RFID Tag: {tag_id}\n'
    try:
        with open(LOG_FILE, 'a', encoding='utf-8') as f:
            f.write(log_entry)
    except OSError as e:
        print(f'Error writing to log file: {e}', file=sys.stderr)
    print(f'Access granted for RFID Tag: {tag_id}')

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f'Listening on {SERIAL_PORT} @ {BAUD_RATE} baud. Press Ctrl+C to stop.')
        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f'Serial read error: {e}', file=sys.stderr)
                break
            if not raw:
                continue
            tag_id = raw.decode('ascii', errors='replace').strip()
            if tag_id:
                log_access(tag_id)
    except serial.SerialException as e:
        print(f'Error opening serial port: {e}', file=sys.stderr)
    except Exception as e:
        print(f'Unexpected error: {e}', file=sys.stderr)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print('Serial port closed.')

if __name__ == '__main__':
    main()

