import serial
import time
import json
from flask import Flask, Response, request, abort

app = Flask(__name__)

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
RESPONSE_DELAY = 0.1

data_list = [
    {'id': 1, 'name': 'Item 1', 'done': False},
    {'id': 2, 'name': 'Item 2', 'done': False},
]


def get_serial_connection():
    try:
        return serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=1,
        )
    except serial.SerialException as exc:
        raise RuntimeError(f"Failed to open serial port {SERIAL_PORT}: {exc}") from exc


def send_command(connection, command):
    try:
        connection.write(command.encode('ascii'))
        connection.flush()
    except serial.SerialException as exc:
        raise RuntimeError(f"Write failed on {SERIAL_PORT}: {exc}") from exc


def read_response(connection):
    time.sleep(RESPONSE_DELAY)
    try:
        raw = connection.read(1024)
    except serial.SerialException as exc:
        raise RuntimeError(f"Read failed on {SERIAL_PORT}: {exc}") from exc
    return raw.decode('ascii', errors='replace').replace('\n', '<br>')


@app.route('/version', methods=['GET'])
def get_version():
    connection = None
    try:
        connection = get_serial_connection()
        send_command(connection, '*IDN?\n')
        response = read_response(connection)
        return Response(response, mimetype='text/html')
    except RuntimeError as exc:
        return Response(str(exc), status=503, mimetype='text/plain')
    finally:
        if connection is not None:
            try:
                connection.close()
            except Exception:
                pass


@app.route('/getdata', methods=['GET'])
def get_data():
    return Response(json.dumps(data_list), mimetype='application/json')


@app.route('/getset/<int:item_id>', methods=['GET'])
def get_set(item_id):
    item = next((d for d in data_list if d['id'] == item_id), None)
    if item is None:
        return Response(json.dumps({'error': 'Item not found'}), status=404, mimetype='application/json')
    return Response(json.dumps(item), mimetype='application/json')


@app.route('/getpost/<int:item_id>/<name>', methods=['GET', 'POST'])
def get_post(item_id, name):
    if request.method == 'POST':
        new_id = data_list[-1]['id'] + 1 if data_list else 1
        new_item = {'id': new_id, 'name': name, 'done': False}
        data_list.append(new_item)
        return Response(json.dumps(data_list), status=201, mimetype='application/json')
    else:
        return Response(json.dumps(data_list), mimetype='application/json')


@app.route('/postjson', methods=['POST'])
def post_json():
    if request.is_json:
        data = request.get_json()
    else:
        data = request.form

    if not isinstance(data, dict):
        return Response(json.dumps({'error': 'Invalid request body'}), status=400, mimetype='application/json')

    new_id = data_list[-1]['id'] + 1 if data_list else 1
    name = data.get('name', '')
    done = data.get('done', False)

    if isinstance(done, str):
        done = done.lower() == 'true'

    new_item = {'id': new_id, 'name': name, 'done': done}
    data_list.append(new_item)
    return Response(json.dumps(data_list), status=201, mimetype='application/json')


if __name__ == '__main__':
    try:
        app.run(host='0.0.0.0', port=5000)
    except KeyboardInterrupt:
        pass

