import bluetooth
import time
import sys

# Bluetooth device address and RFCOMM channel
BLUETOOTH_DEVICE_ADDRESS = "00:06:66:63:61:64"
RFCOMM_CHANNEL = 4


def send_command_to_bluetooth(command):
    """
    Sends a command to the Bluetooth device.

    Args:
        command (str): The command to send.

    Raises:
        RuntimeError: If there's an error connecting or sending data.
    """
    sock = None
    try:
        sock = bluetooth.BluetoothSocket(bluetooth.RFCOMM)
        sock.connect((BLUETOOTH_DEVICE_ADDRESS, RFCOMM_CHANNEL))
        sock.send(command.encode('utf-8'))
        print(f"Sent: {command}")
    except bluetooth.btcommon.BluetoothError as e:
        raise RuntimeError(f"Bluetooth error: {e}")
    except OSError as e:
        raise RuntimeError(f"OS error: {e}")
    finally:
        if sock is not None:
            try:
                sock.close()
            except Exception:
                pass


def main():
    """
    Main function to continuously prompt for commands and send them to the Bluetooth device.
    """
    try:
        while True:
            try:
                user_command = input("Enter command (or 'exit' to quit): ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_command.lower() == 'exit':
                print("Exiting program.")
                break

            command_with_newline = 'X' + user_command + '\n'
            try:
                send_command_to_bluetooth(command_with_newline)
            except RuntimeError as e:
                print(f"Error: {e}", file=sys.stderr)
                break

            time.sleep(0.1)

    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        print("Program finished.")


if __name__ == "__main__":
    main()

